(window.GIM_TS=window.GIM_TS||{})["Bava Kamma.5"]={"from":120,"a":[["\u0003במה דברים אמורים\u0004 — \u0003במדליק בתוך שלו והלכה\u0004 האש \u0003ודלקה בתוך של חבירו, אבל מדליק בתוך של חבירו\u0004 — \u0003דברי הכל משלם כל מה שהיה בתוכו.\u0004","\u0003ומודה ר' יהודה לחכמים במשאיל מקום לחבירו\u0004 בשדהו \u0003להגדיש\u0004 בו \u0003גדיש, והגדיש\u0004 חבירו תבואה בחצירו \u0003והטמין\u0004 באותו גדיש דבר אחר, שאם גרם בעל השדה לשריפת הגדיש \u0003שאין משלם אלא דמי גדיש בלבד,\u0004 שהרי לא קיבל חבירו רשות להטמין כלים אלה באותו גדיש. וכן אם קיבל רשות \u0003להגדיש חטין\u0004 והלך \u0003והגדיש שעורין,\u0004 או שקיבל רשות להגדיש \u0003שעורין והגדיש חטין.\u0004 וכן אם הגדיש \u0003חטין וחיפן\u0004 (כיסה אותן) \u0003בשעורין,\u0004 או הגדיש \u0003שעורין וחיפן בחטים\u0004 — מודה ר' יהודה בכל אלה \u0003שאינו משלם אלא דמי שעורין בלבד,\u0004 שהוא הפחות שבהם.","ובענין דומה \u0003אמר רבא: הנותן דינר זהב לאשה\u0004 לשמירה \u0003ואמר לה \"הזהרי בו\u0004 בדינר זה, כי \u0003של כסף הוא\",\u0004 והיא לא ידעה שהוא של זהב, אם \u0003הזיקתו\u0004 את הדינר בעצמה — \u0003משלמת דינר זהב\u0004 כפי שוויו האמיתי, \u0003משום דאמר\u0004 \u0005[שיכול לומר]\u0006 \u0003לה: מאי הוה ליך גביה דאזקתיה\u0004 \u0005[מה היה לך אצלו שהזקת אותו],\u0006 כלומר, לא היית צריכה להזיק, ואין זה משנה אם היה זה של כסף או של זהב. ואולם אם \u0003פשעה\u0004 (התרשלה) \u0003בו\u0004 ואירע שאבד או נגנב — \u0003משלמת\u0004 רק דמי דינר \u0003של כסף, דאמרה ליה\u0004 \u0005[ש\u0006היא \u0005יכולה לומר לו]:\u0006 \u0003נטירותא דכספא\u0004 \u0005[שמירה של\u0006 דינר \u0005כסף]\u0006 שהוא פחות בערכו — \u0003קבילי\u0004 \u0005[קיבלתי]\u0006 \u0003עלי,\u0004 אך \u0003נטירותא דדהבא\u0004 \u0005[שמירה של\u0006 דינר \u0005זהב]\u0006 שהוא יקר — \u0003לא קבילי\u0004 \u0005[קיבלתי]\u0006 \u0003עלי.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרדכי לרב אשי: אתון\u0004 \u0005[אתם]\u0006 \u0003ב\u0004שמו של \u0003רבא מתניתו לה\u0004 \u0005[אתם שונים אותה],\u0006 \u0003אנן ממתניתא פשיטא לן\u0004 \u0005[אנו מן הברייתא ברור לנו]\u0006 דבר זה, שהרי שנינו: הגדיש \u0003חטין וחיפן בשעורין,\u0004 הגדיש \u0003שעורין וחיפן בחטין\u0004 — \u0003אינו משלם אלא דמי שעורין בלבד. אלמא אמר ליה\u0004 \u0005[מכאן\u0006 שיכול המדליק \u0005לומר לו]\u0006 לבעל הגדיש: \u0003נטירותא דשערי קבילי\u0004 \u0005[שמירה של שעורים קיבלתי]\u0006 \u0003עלי\u0004 ולא יותר, \u0003הכא נמי אמרה ליה\u0004 \u0005[כך גם כן יכולה\u0006 האשה \u0005לומר לו]:\u0006 \u0003נטירותא דדהבא\u0004 \u0005[שמירה של זהב]\u0006 \u0003לא קבילי\u0004 \u0005[קיבלתי]\u0006 \u0003עלי.\u0004","\u0003אמר רב: שמעית מילתא\u0004 \u0005[שמעתי דבר\u0006 הלכה\u0005]\u0006 \u0003ל\u0004שיטת \u0003ר' יהודה\u0004 שבמשנתנו \u0003ולא ידענא\u0004 \u0005[יודע אני]\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 אותה הלכה. \u0003אמר שמואל: ולא ידע\u0004 \u0005[ו\u0006כי \u0005אין יודע]\u0006 \u0003אבא\u0004 (שמו הפרטי של רב) \u0003מאי שמיע ליה\u0004 \u0005[מה שמע]?\u0006 אלו הם הדברים ששמע: \u0003ל\u0004שיטת \u0003ר' יהודה\u0004 ש\u0003מחייב על נזקי טמון באש עשו תקנת נגזל באשו,\u0004 שכשם שבנגזל תיקנו חכמים שיכול הוא להישבע כמה גזל ממנו הגזלן, ויצטרך הגזלן לשלם, כך לדעת ר' יהודה שחייב על טמון באש, אם ישבע בעל הגדיש שדברים מסויימים היו בגדישו — יצטרך המבעיר לשלם אותם דברים.","ובענין זה \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003אמימר:\u0004 האם \u0003עשו תקנת נגזל\u0004 זו שנשבע ונוטל, גם \u0003במסור\u0004 (מלשין) שגורם להחרמת רכושו של חבירו בידי גויים, \u0003או לא?\u0004 ומבררים את הבעיה: \u0003אליבא דמאן דאמר לא דיינינן דינא דגרמי\u0004 \u0005[לדעת מי שאומר\u0006 ש\u0005אין אנו דנים דין של גורמי\u0006 נזיקין\u0005]\u0006 אלא מחייבים רק על נזק ישיר בידים — \u0003לא תבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 שאלה זו, שוודאי דין \u0003מסורות\u0004 \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא דיינינן\u0004 \u0005[אין אנו דנים]\u0006 אפילו בנזק ברור, כיון שהוא בדרך של גרם נזיקין בלבד.","\u0003אלא כי תבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 הרי זה \u0003אליבא דמאן דאמר דיינינן דינא דגרמי\u0004 \u0005[לשיטת מי שאומר שאנו דנים דין של גורמי\u0006 נזיקין\u0005]\u0006 והשאלה היא: האם \u0003עשו תקנת נגזל\u0004 זו גם \u0003במסור, דמשתבע\u0004 \u0005[שנשבע]\u0006 הנפגע על טענתו שכך לקחו ממנו \u0003ושקיל\u0004 \u0005[ונוטל]\u0006 כטענתו, \u0003או לא?\u0004 לשאלה זו לא נמצאה תשובה, ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","מסופר: \u0003ההוא גברא דבטש בכספתא דחבריה שדייה בנהרא\u0004 \u0005[אדם אחד בעט בקופת כסף,\u0006 כספת, \u0005של חבירו\u0006 ו\u0005השליכה בנהר],\u0006 \u0003אתא מריה\u0004 \u0005[בא בעליה]\u0006 של הכספת \u0003ואמר: הכי והכי הוה\u0004 \u0005[כך וכך היה]\u0006 \u0003לי בגוה\u0004 \u0005[בתוכה].\u0006 \u0003יתיב\u0004 \u0005[היה יושב]\u0006 \u0003רב אשי וקא מעיין ביה\u0004 \u0005[ומעיין בה\u0006 בשאלה זו\u0005]:\u0006 \u0003כי האי גוונא מאי\u0004 \u0005[כגון זה מה\u0006 הדין\u0005]?\u0006 האם מאמינים אנו לניזק או לא?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי:\u0004 \u0003לאו היינו מתניתין\u0004 \u0005[האם אין זו משנתנו]\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ומודים חכמים לר' יהודה במדליק את הבירה שמשלם כל מה שבתוכו, שכן דרך בני אדם להניח בבתים.\u0004 ואם כן צריך לסמוך על הניזק ולשלם מה שטוען שהיה שם, ומה מקום להסתפק בשאלה זו?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003אי דקא טעין זוזי\u0004 \u0005[אם שטוען\u0006 הניזק ש\u0005מטבעות]\u0006 היו שם — \u0003הכא נמי\u0004 \u0005[כאן גם כן\u0006 הדין\u0005]\u0006 שישלם. \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003דקא טעין מרגניתא\u0004 \u0005[ש\u0006הוא \u0005טוען\u0006 ש\u0005מרגליות]\u0006 היו בקופה, והשאלה היא: \u0003מאי\u0004 \u0005[מה]\u0006 הדין? \u0003מי מנחי אינשי מרגניתא בכספתא\u0004 \u0005[האם מניחים אנשים מרגליות בכספת]\u0006 ונאמין לו, \u0003או לא?\u0004 ואף שאלה זו לא נפתרה, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יימר לרב אשי: טעין כסא דכספא\u0004 \u0005[\u0006אם הניזק \u0005טוען\u0006 שהיתה לו בין השאר \u0005כוס כסף]\u0006 \u0003בבירה\u0004 (ארמון) ששרף חבירו, \u0003מאי\u0004 \u0005[מה]\u0006 דינו? האם נאמן הוא, או לא? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003חזינא\u0004 \u0005[רואים אנו]\u0006 \u0003אי איניש\u0004 \u0005[אם אדם]\u0006 \u0003אמיד\u0004 (עשיר) \u0003הוא\u0004 שיש מקום לשער \u0003דאית ליה כסא דכספא\u0004 \u0005[שיש לו כוס כסף],\u0006 \u0003אי נמי איניש מהימנא\u0004 \u0005[או גם כן\u0006 ש\u0005אדם נאמן]\u0006 \u0003הוא דמפקדי אינשי גביה\u0004 \u0005[שמפקידים אנשים אצלו\u0006 חפצי ערך\u0005]\u0006 — \u0003משתבע ושקיל\u0004 \u0005[נשבע\u0006 שכך היה אצלו \u0005ונוטל]\u0006 כטענתו. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 היה איש כזה — \u0003לאו כל כמיניה\u0004 \u0005[אין זה בכוחו]\u0006 לטעון כן וליטול כפי דבריו.","ובענין אחר \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אויא לרב אשי: מה\u0004 ההבדל \u0003בין גזלן לחמסן? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003חמסן\u0004 — \u0003יהיב דמי\u0004 \u0005[נותן כסף]\u0006 עבור החפץ שנוטל מן הבעלים שלא כרצונם, ואילו \u0003גזלן\u0004 — \u0003לא יהיב דמי\u0004 \u0005[אינו נותן כסף].\u0006","ותמה רב אדא ו\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אי יהיב דמי\u0004 \u0005[אם נותן כסף]\u0006 \u0003חמסן קרית ליה\u0004 \u0005[אתה קורא לו]?\u0006 הרי כיון שנותן כסף ומשלם עבור מה שנטל, הרי זה קונה כדינו, ואף שלא מכר בעל החפץ מרצונו, \u0003והאמר\u0004 \u0005[והרי\u0006 כך \u0005אמר]\u0006 \u0003רב הונא:\u0004 מי ש\u0003תלוה\u0004 \u0005[תלו אותו]\u0006 כדי להכריחו למכור דבר \u0003וזבין\u0004 \u0005[ומכר]\u0006 — \u0003זביניה זביני\u0004 \u0005[מכירתו מכירה],\u0006 משמע שגם מכירה באונס נחשבת כמכירה חוקית! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שמכירה מתוך אונס נחשבת מכירה — הרי זה במקרה ש\u0003אמר \"רוצה אני\",\u0004 שהסכים למכירה למרות שהוכרח לה, \u0003הא\u0004 \u0005[זה]\u0006 שהמכירה לא חלה — הרי זה במקרה ש\u0003לא אמר \"רוצה אני\".\u0004"],["\u0003גץ\u0004 (ניצוץ) \u0003שיצא מתחת הפטיש\u0004 של הנפח \u0003והזיק\u0004 — \u0003חייב\u0004 הנפח על הנזק שגרם.","\u0003גמל שהיה טעון פשתן ועבר ברשות הרבים, ונכנס פשתנו לתוך החנות ודלקו בנרו של חנוני\u0004 שהיה בחנות, \u0003ו\u0004על ידי הפשתן הבוער \u0003הדליק את הבירה\u0004 (הבית) ומה שבתוכו — \u0003בעל\u0004 ה\u0003גמל חייב. הניח חנוני נרו מבחוץ\u0004 וגרם על ידי כך לדליקת הפשתן שעל גבי הגמל ולשריפת הבית — \u0003החנוני חייב. ר' יהודה אומר:\u0004 \u0003ב\u0004מקרה שהיה הנר המונח בחוץ \u0003נר חנוכה\u0004 — \u0003פטור\u0004 החנווני שמצווה היא שיהא נר חנוכה בחוץ.","\u0003אמר רבינא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003מ\u0004דברי \u0003ר' יהודה\u0004 כי \u0003נר חנוכה מצוה להניחה בתוך\u0004 גובה \u0003עשרה\u0004 טפחים מן הקרקע, \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר שגם \u0003למעלה מעשרה\u0004 טפחים מצווה היא, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אמר ר' יהודה\u0004 שב\u0003נר חנוכה\u0004 המונח בחוץ \u0003פטור\u0004 החנווני? \u0003לימא ליה\u0004 \u0005[שיאמר לו]\u0006 בעל הגמל לחנווני: \u0003הוה ליה לאנוחה\u0004 \u0005[היה לו להניחה,\u0006 את הנר\u0005]\u0006 \u0003למעלה מ\u0004גובה \u0003גמל ורוכבו\u0004 באופן שלא יידלק בו פשתנם של גמלים! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003מצוה להניחה בתוך עשרה\u0004 טפחים ולא גבוה יותר?","\u0003אמרי\u0004 \u0005[אומרים]\u0006 ודוחים: \u0003לא,\u0004 אין מכאן ראיה, \u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 ש\u0003אפילו למעלה מעשרה\u0004 טפחים ניתן להניח נר חנוכה, \u0003מאי אמרת\u0004 \u0005[מה אומר אתה],\u0006 שיכול בעל הגמל לטעון: \u0003אבעי לך לאנוחה\u0004 \u0005[היה לך להניחה]\u0006 בגובה שלפחות \u0003למעלה מגמל ורוכבו,\u0004 על כך יש להשיב: \u0003כיון\u0004 ש\u0003במצוה קא עסיק\u0004 \u0005[הוא עוסק]\u0006 \u0003כולי האי לא אטרחוה רבנן\u0004 \u0005[וכל כך לא הטריחו חכמים\u0006 להגביה נרו\u0005].\u0006","ועוד בענין גובה נר חנוכה \u0003אמר רב כהנא: דרש רב נתן בר מניומי משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' תנחום: נר חנוכה שהניחה\u0004 במקום שהוא \u0003למעלה מעשרים אמה\u0004 מן הקרקע — \u0003פסולה\u0004 משום שאין אנשים מסתכלים בגובה זה, ועיקר עניינו של נר חנוכה שיראוהו. דין נר חנוכה כמוהו \u0003כ\u0004דין \u0003סוכה וכ\u0004דין קורה של \u0003מבוי\u0004 שכאשר הם למעלה מעשרים אמה הרי אלו פסולים.","","\u0003מרובה מדת תשלומי כפל ממדת תשלומי ארבעה וחמשה,\u0004 שהיקף עבירות הגניבה שחייבים לשלם עבורן כפל מרובה יותר מאלה שחייבים לשלם עליהן פי ארבעה וחמישה. \u0003שמדת תשלומי כפל נוהגת בין ב\u0004גונב \u0003דבר שיש בו רוח חיים ובין ב\u0004גונב \u0003דבר שאין בו רוח חיים, ו\u0004אילו \u0003מדת תשלומי ארבעה וחמשה אינה נוהגת אלא בשור ושה\u0004 חיים \u0003בלבד, שנאמר: \"כי יגנב איש שור או שה וטבחו או מכרו\u0004 חמשה בקר ישלם תחת השור וארבע צאן תחת השה\u0003\"\u0004(שמות כא, לז).","ועוד הגבלה של קנסות אלה: \u0003אין הגונב אחר הגנב משלם תשלומי כפל\u0004 לגנב או לבעלים על גניבה זו, \u0003ולא הטובח ולא המוכר אחר הגנב\u0004 אם גנב ממנו \u0003משלם תשלומי ארבעה וחמשה\u0004 אלא קרן בלבד.","על דברי המשנה מעירים: שנינו ענין אחד בו מרובה מידת תשלומי כפל ממדת תשלומי ארבעה וחמישה, \u0003ואילו\u0004 הבחנה אחרת ש\u0003מדת תשלומי כפל נוהגת בין בגנב בין בטוען טענת גנב,\u0004 כלומר, אף באדם שהפקידו אצלו פקדון וטען שנגנב ממנו ונמצא שהוא בעצמו גנבו, \u0003ומדת תשלומי ארבעה וחמשה אינה נוהגת אלא בגנב בלבד\u0004 — \u0003לא קתני\u0004 \u0005[שנה]\u0006 במשנה.","וזה שלא נשנתה הבחנה זו הריהו \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לר' חייא בר אבא,\u0004 ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: הטוען טענת גנב בפקדון,\u0004 אם התברר שגנבו הוא עצמו — \u0003משלם תשלומי כפל,\u0004 אם \u0003טבח ומכר\u0004 — \u0003משלם תשלומי ארבעה וחמשה\u0004 ואין הבדל בין תשלומי כפל לתשלומי ארבעה וחמישה בטוען טענת גנב.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ענין זה באופן אחר: \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי דין זה השנוי במשנתנו \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לר' חייא בר אבא,\u0004 ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: הטוען טענת גנב בפקדון משלם תשלומי כפל, טבח ומכר משלם תשלומי ארבעה וחמשה?\u0004 שכיון שהמשנה אינה מחלקת בענין זה, הרי זו הוכחה שלענין זה אין הבדל בין גונב לטוען טענת גנב.","ומשיבים: מכאן אין ראיה, שכן \u0003מי קתני\u0004 \u0005[האם שנה]\u0006 במשנה בניסוח כולל: \u0003\"אין בין\u0004 תשלומי כפל לתשלומי ארבעה וחמישה אלא...\" הבדל זה? הלא לשון \u0003\"מרובה\" קתני\u0004 \u0005[שנה]\u0006 ומביא דוגמא לכך שאכן מרובה מדת תשלומי כפל ממדת תשלומי ארבעה וחמישה, ואולם \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003ושייר\u0004 דברים אחרים שלא שנה, ואין להוכיח איפוא ממה שלא נזכר דין זה.","שנינו במשנה \u0003שמדת תשלומי כפל נוהגת\u0004 בין בדבר שיש בו רוח חיים ובין בדבר שאין בו רוח חיים. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מניין הדברים הללו]?\u0006 ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 בפרשה העוסקת בתשלומי כפל: \u0003\"על כל דבר פשע\"\u0004 (שמות כב, ח) — הרי זה \u0003כלל, \"על שור על חמור על שה ועל שלמה\"\u0004 — הרי זה \u0003פרט, \"על כל אבדה\"\u0004 — \u0003חזר וכלל,\u0004 אם כן הרי זה כלל ופרט וכלל, ולפי המדות שהתורה נדרשת בהן, במקום בו יש","\u0003כלל ופרט וכלל אי\u0004 (אין) \u0003אתה דן\u0004 את הכלל \u0003אלא כעין הפרט\u0004 ואינך מכליל בו דברים שונים מן הפרט לגמרי, ולענייננו נאמר: \u0003מה הפרט\u0004 (שור, חמור, שה, שלמה) \u0003מפורש\u0004 — \u0003דבר המטלטל וגופו\u0004 (הוא עצמו) שווה \u0003ממון, אף כל דבר המטלטל וגופו ממון\u0004 הריהו נדון בתשלומי כפל,","\u0003יצאו\u0004 מכלל זה \u0003קרקעות שאינן מטלטלין, יצאו עבדים שהוקשו\u0004 (הושוו) בכתוב לכמה עניינים \u0003לקרקעות, יצאו שטרות שאף על פי ש\u0004הם \u0003מטלטלין\u0004 — \u0003אין גופן ממון\u0004 אלא הם רק הוכחה לתביעת ממון, וכן גם \u0003יצא הקדש\u0004 מכלל זה, שכן \u0003\"רעהו\" כתיב\u0004 \u0005[נאמר]\u0006 בענין זה (\"ישלם שנים לרעהו\". שמות כב, ח), והקדש אינו בכלל רעהו.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 למדים רק כעין הפרט, נאמר אם כן: \u0003מה הפרט מפורש\u0004 — \u0003דבר שנבלתו מטמא במגע ובמשא\u0004 כגון שור וחמור \u0003אף כל דבר שנבלתו מטמא במגע ובמשא, אבל עופות\u0004 שאין נבלתם מטמאה במגע ובמשא \u0003לא\u0004 יהיו בכלל זה, ויהיה פטור עליהם מתשלומי כפל!","ודוחים: \u0003ומי מצית אמרת הכי\u0004 \u0005[והאם יכול אתה לומר כך]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"שלמה\" כתיב\u0004 \u0005[נאמר]\u0006 ועליה אי אפשר לדון בדיני טומאת נבילה! \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003אנן\u0004 \u0005[אנו]\u0006 \u0003בבעלי חיים קאמרינן\u0004 \u0005[אומרים אנו],\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003בבעלי חיים\u0004 שנגנבו, רק אם גנב \u0003דבר שנבלתו מטמא במגע ובמשא\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 משלם כפל, \u0003דבר שאין נבלתו מטמא במגע ובמשא\u0004 — \u0003לא\u0004 ישלם עליו כפל,"],["\u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003כל חד וחד\u0004 \u0005[אחד ואחד]\u0006 מן הפרטים המנויים כאן \u0003כלל ופרט\u0004 וכלל \u0003באפי נפשיה דרשינן ליה\u0004 \u0005[בפני עצמו אנו דורשים אותו]\u0006 ומכל אחד למדים לסוג מסויים של דברים הדומים לו, ואין למדים מכל הפרטים כאחד. וכיון שכך, נמצא שבעלי החיים המנויים שם יש בהם צד משותף אחד — שנבלתם מטמאה במגע ובמשא \u0003אבל עופות לא!\u0004","ודוחים: \u0003אם כן, נכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 ברשימת בעלי החיים רק \u0003חד פרטא\u0004 \u0005[פרט אחד]\u0006 והייתי לומד ממנו הגדרה זו — כל שנבלתו מטמאה, ואין בכלל זה עופות. וכיון שריבתה התורה בפרטים הרי זה להרבות בעניינים ובסוגים נוספים של בעלי חיים, ובכלל זה עופות.","ומקשים על כך: \u0003הי\u0004 \u0005[איזה]\u0006 פרט מרשימת הפרטים \u0003נכתוב רחמנא\u0004 \u0005[תכתוב התורה]?\u0006 \u0003אי כתב רחמנא\u0004 \u0005[אילו היתה כותבת התורה]\u0006 כפרט \u0003\"שור\"\u0004 בלבד, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי רק דבר ה\u0003קרב לגבי מזבח\u0004 כקרבן — \u0003אין\u0004 \u0005[כן]\u0006 הריהו בכלל כפל, ואילו דבר \u0003שאין קרב לגבי מזבח\u0004 — \u0003לא.\u0004 \u0003ו\u0004כן, \u0003אי כתב רחמנא\u0004 \u0005[אילו היתה כותבת התורה]\u0006 רק \u0003\"חמור\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי רק דבר ה\u0003קדוש בבכורה\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 הריהו בכלל כפל, שכן יש קדושה לפטר רחם של חמור, ואולם דבר \u0003שאין קדוש בבכורה —\u0004 \u0003לא!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003אם כן נכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 רק \u0003\"שור\" ו\"חמור\", \"שה\" למה לי? שמע מינה\u0004 \u0005[למד מכאן],\u0006 מייתור זה, \u0003לאתויי\u0004 \u0005[להביא\u0006 לרבות\u0005]\u0006 גם \u0003עופות.\u0004","ומקשים עוד: \u0003ואימא\u0004 \u0005[ואמור]\u0006 כי למדנו מריבוי זה \u0003לאתויי\u0004 \u0005[להביא]\u0006 רק \u0003עופות טהורים, דומיא\u0004 \u0005[\u0006ב\u0005דומה]\u0006 ל\u0003שה\u0004 שיש בנבלתו טומאה, ואף בנבלת עופות טהורים יש טומאה מסויימת, שכן נבלת העוף הטהור \u0003מטמא בגדים אבית\u0004 \u0005[בבית]\u0006 \u0003הבליעה,\u0004 שאם בלע אדם מנבלת העוף הטהור הרי הוא נטמא ומטמא בגדים, \u0003אבל עופות טמאים דלית בהו\u0004 \u0005[שאין בהם]\u0006 \u0003טומאה\u0004 במותם כלל, ש\u0003לא מטמאי\u0004 \u0005[מטמאים]\u0006 \u0003בגדים אבית\u0004 \u0005[בבית]\u0006 \u0003הבליעה, לא\u0004 יהיה בהם דין כפל! ומשיבים: \u0003\"כל\"\u0004 הכתוב בפסוק זה (\"על כל דבר פשע\"), לשון \u0003ריבויא\u0004 \u0005[ריבוי]\u0006 \u0003הוא,\u0004 ואם כן, אין כאן לימוד בדרך של כלל ופרט וכלל הבא ללמד על מה שהוא כעין הפרט, אלא יש כאן לימוד אחר בדרך של ריבוי ומיעוט, ולפי מידת לימוד זו כל הדברים השייכים בדרך כלשהי לענין המדובר נלמדים מלשון הריבוי, ובכלל זה לענייננו כל בעלי החיים, ואף עופות טמאים, שאף הם בכלל דין כפל.","ומקשים: \u0003וכל היכא דכתב\u0004 \u0005[מקום שנאמר\u0006 בו\u0005]\u0006 \u0003\"כל\"\u0004 לשון \u0003ריבויא\u0004 \u0005[\u0006\u0005ריבוי]\u0006 \u0003הוא?\u0004 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003מעשר\u0004 שני, שאת דמיו מעלים לירושלים וקונים בהם דברים למאכל, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בו \u0003\"כל\",\u0004 \u0003וקא דרשינן ליה\u0004 \u0005[ואנו דורשים אותו]\u0006 \u0003ב\u0004דרך לימוד של \u0003כלל ופרט\u0004 ולא בדרך לימוד של ריבוי.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 על הכתוב \"ונתתה הכסף בכל אשר תאוה נפשך בבקר ובצאן וביין ובשכר ובכל אשר תשאלך נפשך\" (דברים יד, כו) דורשים: \u0003\"ונתת\u0004 ה\u0003הכסף בכל אשר תאוה נפשך\"\u0004 — הרי זה \u0003כלל, \"בבקר ובצאן וביין ובשכר\"\u0004 — הרי זה \u0003פרט, \"ובכל אשר תשאלך נפשך\"\u0004 — \u0003חזר וכלל,\u0004 הרי זה \u0003כלל ופרט וכלל,\u0004 ולפי כללי מדרש ההלכה, \u0003אי\u0004 (אין) \u0003אתה דן אלא כעין הפרט,\u0004 ומכאן למדים: \u0003מה הפרט מפורש\u0004 שהוא \u0003פרי מפרי,\u0004 כלומר, דבר שהוא עצמו תוצר של פרי, כגון יין הנעשה מן הענבים, \u0003וגידולי קרקע,\u0004 כלומר, דבר שבעיקרו גדל או ניזון מן הקרקע, \u0003אף כל\u0004 הדברים שאפשר לקנות בכסף מעשר שני צריכים להיות \u0003פרי מפרי וגידולי קרקע,\u0004 ונמצא שהמלה \"כל\" (\"בכל אשר תאוה נפשך\") משמשת ללימוד בדרך כלל ופרט וכלל!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: יש לחלק בין המקרים, \u0003\"בכל\"\u0004 הרי הוא לשון \u0003כללא\u0004 \u0005[כלל],\u0006 ואילו \u0003\"כל\"\u0004 לשון \u0003ריבויא\u0004 \u0005[ריבוי]\u0006 \u0003הוא. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 ותרץ באופן אחר: לשון \u0003\"כל\"\u0004 — \u0003כללא\u0004 \u0005[כלל]\u0006 \u0003הוא\u0004 כרגיל, \u0003מיהו\u0004 \u0005[אולם]\u0006 \u0003\"כל\" דהכא\u0004 \u0005[ש\u0006נאמר \u0005כאן],\u0006 בענין תשלומי כפל, לשון \u0003ריבויא\u0004 \u0005[ריבוי]\u0006 \u0003הוא.\u0004","וראיה לדבר: \u0003מכדי כתיב מעיקרא\u0004 \u0005[הלוא נאמר מתחילה]\u0006 בתחילת אותה פרשיה \u0003כלל ופרט וכלל,\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 (שמות כב, ו): \u0003\"כי יתן איש אל רעהו\"\u0004 — הרי זה \u0003כלל, \"כסף או כלים\"\u0004 — \u0003פרט, \"לשמר\"\u0004 — \u0003הדר\u0004 \u0005[חזר]\u0006 \u0003וכלל,\u0004","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר כי \u0003האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 שאנו עוסקים בו, \u0003\"על כל דבר פשע\"\u0004 (שמות כב ח), \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003ל\u0004דרך לימוד של \u0003כלל ופרט הוא דאתא\u0004 \u0005[שבא],\u0006 אם כן \u0003נכתוב רחמנא להני פרטי גבי האיך\u0004 \u0005[שתכתוב התורה את הפרטים הללו,\u0006 שור חמור וכו' \u0005אצל אותם]\u0006 \u0003כלל ופרט\u0004 וכלל האמורים בתחילה, ואם כן הכתוב הנוסף \u0003\"על כל דבר פשע\" למה לי? שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \"כל\" זה לשון \u0003ריבויא\u0004 \u0005[ריבוי]\u0006 \u0003הוא,\u0004 וכיון שריבוי הוא — הרי הוא מרבה את כל בעלי החיים, ואף שאינם ממש כעין הפרט.","ושואלים: \u0003השתא דאמרת\u0004 \u0005[עכשיו שאתה אומר]\u0006 שלשון \u0003\"כל\u0004 דבר פשע \u0003\"\u0004לשון \u0003ריבויא\u0004 \u0005[ריבוי]\u0006 היא, \u0003כל הני פרטי\u0004 \u0005[הפרטים הללו],\u0006 שור, חמור, שה, שלמה, \u0003למה לי?\u0004 כי בדרך לימוד זו פרטים אלה באים למעט מן הריבוי, ומה הם באים למעט? ומשיבים: \u0003חד\u0004 \u0005[אחד]\u0006 מהם בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003קרקע, וחד למעוטי\u0004 \u0005[ואחד למעט]\u0006 \u0003עבדים, וחד\u0004 \u0003למעוטי\u0004 \u0005[ואחד למעט]\u0006 \u0003שטרות,\u0004 ו\u0003\"שלמה\"\u0004 הכתובה שם באה \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003דבר שאינו מסויים,\u0004 שאינו מוגדר במידותיו ובגבולותיו, ומה שנאמר \u0003\"על כל אבדה\"\u0004 בא ללמדנו \u0003לכ\u0004 פי שאמר \u0003ר' חייא בר אבא,\u0004 ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: הטוען טענת גנב\u0004"],["\u0003באבידה,\u0004 שמצא אבידה ואינו רוצה להשיב אותה וטוען בשקר שנגנבה ממנו — אף הוא \u0003משלם תשלומי כפל, שנאמר: \"על כל אבדה אשר יאמר\"\u0004 (שמות כב, ח).","\u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]:\u0006 אמר המפקיד למחזיק הפקדון: \u0003היכן פקדוני? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אבד.\u0004 אמר המפקיד: \u0003משביעך אני\u0004 שאכן אבד ממך, \u0003ואמר\u0004 מחזיק הפקדון: \u0003אמן,\u0004 והרי זה כקבלת שבועה על עצמו, \u0003ו\u0004לבסוף \u0003העדים מעידים אותו,\u0004 את מחזיק הפקדון, \u0003שאכלו,\u0004 כלומר, שלקחו לעצמו והשתמש באותו פקדון — \u0003משלם את הקרן.\u0004 אם \u0003הודה על פי עצמו\u0004 בלא עדים — הרי זה \u0003משלם קרן וחומש\u0004 (חמישית) נוסף לכך כקנס, ומביא קרבן \u0003אשם\u0004 גזילות על חטאו בגניבה (ראה ויקרא ה, כ–כו).","אמר המפקיד לנפקד: \u0003היכן פקדוני?\u0004 \u0003אמר לו: נגנב.\u0004 אמר לו המפקיד: \u0003משביעך אני\u0004 שאכן נגנב ממך, \u0003ואמר\u0004 הנפקד: \u0003אמן, והעדים מעידים אותו ש\u0004הוא עצמו \u0003גנבו\u0004 — הרי זה \u0003משלם תשלומי כפל.\u0004 אם \u0003הודה מעצמו\u0004 בלא עדים שהוא גנבו — \u0003משלם\u0004 רק \u0003קרן וחומש ואשם.\u0004 עד כאן לשון המשנה.","ומעירים: \u0003קתני מיהא\u0004 \u0005[שנה על כל פנים]\u0006 \u0003בטוען טענת גנב\u0004 ש\u0003משלם תשלומי כפל, אבל בטוען טענת אבד\u0004 — \u0003לא משלם תשלומי כפל.\u0004 ועוד שנה: \u0003ואפילו טוען טענת גנב\u0004 רק \u0003בשבועה הוא\u0004 ש\u0003משלם תשלומי כפל, אבל שלא בשבועה\u0004 שאם כיחש ולא נשבע לשקר על כך — \u0003אינו משלם תשלומי כפל.\u0004","ושואלים: \u0003מנהני מילי\u0004 \u0005[מניין הדברים הללו],\u0006 מה המקור בתורה לחלוקת הדינים הללו? ומסבירים: \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 על הכתוב \"כי יתן איש אל רעהו כסף או כלים לשמור וגונב מבית האיש \u0003אם ימצא הגנב\u0004 ישלם שנים\" (שמות כב, ו) — \u0003בטוען טענת גנב\u0004 ונמצא לבסוף שהוא עצמו הגנב. \u0003הכתוב מדבר\u0004 ודנים בדבר:","\u0003אתה אומר\u0004 כי \u0003בטוען טענת גנב\u0004 הכתוב מדבר, \u0003או אינו אלא בגנב עצמו?\u0004 ועל כך משיבים: \u0003כשהוא אומר\u0004 בהמשך אותו כתוב \u0003\"אם לא ימצא הגנב\"\u0004 (שמות כב, ז) משמע כי \u0003בטוען טענת גנב הכתוב מדבר,\u0004 שאין גנב אחר בנמצא, כדברי הנפקד, אלא הוא עצמו גנבו, ואף האמור מקודם הריהו בטוען טענת גנב.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003\"אם ימצא הגנב\"\u0004 — \u0003בגנב עצמו הכתוב מדבר.\u0004 ודנים בדבר: \u0003אתה אומר בגנב עצמו, או אינו אלא בטוען טענת גנב?\u0004 לכך משיבים: \u0003כשהוא אומר\u0004 בהמשך \u0003\"אם לא ימצא הגנב\"\u0004 — \u0003הרי טוען טענת גנב אמור, הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים \"אם ימצא הגנב\"\u0004 — \u0003בגנב עצמו הכתוב מדבר.\u0004","ומעירים: אף שנחלקו הברייתות בפירוש מה שנאמר \"אם ימצא הגנב\", אם בגנב עצמו אם בטוען טענת גנב נאמרו הדברים, \u0003דכולי עלמא מיהת\u0004 \u0005[לדעת הכל על כל פנים]\u0006 מה שנאמר \u0003\"אם לא ימצא הגנב\" בטוען טענת גנב כתיב\u0004 \u0005[נאמר],\u0006 ויש לשאול: \u0003מאי משמע\u0004 \u0005[מה המשמעות],\u0006 כיצד נובע הדבר מן הכתובים? \u0003אמר רבא,\u0004 כך יש להבין: \u0003\"אם לא ימצא\" כמה\u0004 (כמו) \u0003שאמר, אלא\u0004 יתברר \u0003שהוא עצמו גנבו\u0004 — הרי זה \u0003ישלם שנים.\u0004 עד כאן בבירור מקור הדין שהטוען טענת גנב חייב בכפל.","ומעתה פונים לדיון השני: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 שחיוב כפל זה הוא דווקא כאשר היה \u0003בשבועה?\u0004","ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר בכתוב \u0003\"ונקרב בעל הבית אל האלהים\"\u0004 (שמות כב, ז), כוונתו — שיבוא \u0003לשבועה.\u0004 ויש לדון: \u0003אתה אומר\u0004 שהכוונה שיבוא \u0003לשבועה או אינו אלא\u0004 שיבוא \u0003לדין?\u0004 על כך יש להשיב כי נלמד מגזירה שווה, \u0003נאמר שליחות יד למטה\u0004 בהמשך הפרשה (\"שבועת ה' תהיה בין שניהם אם לא שלח ידו במלאכת רעהו\". (שמות כב, י), \u0003ונאמר שליחות יד למעלה\u0004 בענייננו (\"אם לא שלח ידו במלאכת רעהו\". (שמות כב, ז), \u0003מה להלן\u0004 הכוונה היא ב\u0003שבועה,\u0004 שכן נאמר במפורש בכתוב, \u0003אף כאן לשבועה.\u0004","ודנים בברייתות שהובאו: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר],\u0006 הברייתא השניה, כי \u0003חד\u0004 \u0005[\u0006פסוק \u0005אחד]\u0006 (\"אם ימצא\") נדרש \u0003בגנב, וחד\u0004 \u0005[ואחד]\u0006 (\"אם לא ימצא\") \u0003בטוען טענת גנב\u0004 — \u0003היינו דכתיבי תרי קראי\u0004 \u0005[זהו\u0006 הטעם \u0005שנאמרו שני כתובים],\u0006 \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר],\u0006 הברייתא הראשונה, כי \u0003תרוייהו\u0004 \u0005[שניהם]\u0006 שני הפסוקים עוסקים \u0003בטוען טענת גנב, תרי קראי\u0004 \u0005[שני כתובים]\u0006 לאותו דבר \u0003למה לי?\u0004 הלא די היה באחד!","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 יש טעם בדבר, \u0003חד למעוטי\u0004 \u0005[\u0006פסוק \u0005אחד\u0006 מאלה בא \u0005למעט]\u0006 ולהדגיש שמדובר רק בטוען טענת גנב ולא בטוען \u0003טענת אבד.\u0004","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 \u0003חד\u0004 \u0005[\u0006פסוק \u0005אחד]\u0006 מדבר \u0003בגנב,\u0004 \u0003וחד\u0004 \u0005[ואחד]\u0006 \u0003בטוען טענת גנב,\u0004 ש\u0003לא מייתר\u0004 \u0005[מיותר]\u0006 מעתה שום פסוק, \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003טענת אבד מנא ליה\u0004 \u0005[מניין לו]?\u0006 ומשיבים: ממה שיכול היה לומר \u0003\"\u0004אם לא ימצא \u0003גנב\"\u0004 ונאמר \u0003\"הגנב\",\u0004 הרי זה להדגיש: דווקא הטוען טענת גנב הוא המשלם כפל, ולא הטוען טענה אחרת כגון טענת אבידה.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר],\u0006 הברייתא הראשונה, כי \u0003תרוייהו\u0004 \u0005[שניהם\u0006 שני הכתובים\u0005]\u0006 מדברים \u0003בטוען טענת גנב,\u0004 ש\u0003מיעט ליה\u0004 \u0005[לו]\u0006 הכתוב בכך \u0003טוען טענת אבד,\u0004 הריבוי של \u0003\"גנב\" \"הגנב\" מאי דריש ביה\u0004 \u0005[מה\u0006 הוא \u0005דורש בו,\u0006 למד ממנו\u0005]?\u0006","ומשיבים: \u0003אמר\u0004 \u0005[יכול היה\u0006 \u0005לומר]\u0006 \u0003לך\u0004 כי \u0003מבעי ליה\u0004 \u0005[צריך לו]\u0006 ריבוי זה \u0003לכ\u0004 פי שאמר \u0003ר' חייא בר אבא אמר ר' יוחנן.\u0004 ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: הטוען טענת גנב בפקדון\u0004 — \u0003משלם תשלומי כפל,\u0004 ואם \u0003טבח ומכר\u0004 — אף \u0003משלם תשלומי ארבעה וחמשה.\u0004","ושואלים: \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003חד\u0004 \u0005[\u0006פסוק \u0005אחד]\u0006 מדבר \u0003בגנב וחד\u0004 \u0005[ואחד]\u0006 \u0003בטוען טענת גנב, דהאי\u0004 \u0005[ש\u0006ריבוי \u0005זה]\u0006 \u0003\"גנב\" \"הגנב\" אפקיה\u0004 \u0005[הוציא אותו]\u0006 ודרש בו \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003טענת אבד,\u0004 הלכה זו של \u0003ר' חייא בר אבא\u0004 לחייבו אף ארבעה וחמישה אם טבח או מכר \u0003מנא ליה\u0004 \u0005[מניין לו]?\u0006","ומשיבים: \u0003אמר\u0004 \u0005[יכול היה\u0006 \u0005לומר]\u0006 \u0003לך\u0004 שלימוד זה \u0003הקישא\u0004 \u0005[היקש]\u0006 \u0003הוא\u0004 שבסמיכות הכתובים מקיש הכתוב גנב לטוען טענת גנב, ומוסיפים: \u0003ו\u0004גם אם מצד הסברה אין הדברים דומים לגמרי זה לזה והיה מקום לשאול על היקש זה, הכלל הוא ש\u0003אין משיבין על הקישא\u0004 \u0005[היקש].\u0006","ושואלים עוד: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003חד\u0004 \u0005[\u0006פסוק \u0005אחד]\u0006 \u0003בגנב וחד\u0004 \u0005[ואחד]\u0006 \u0003בטוען טענת גנב\u0004 — \u0003שפיר\u0004 \u0005[יפה],\u0006 \u0003אלא למאן דאמר תרוייהו\u0004 \u0005[ל\u0006דעת \u0005מי שאומר\u0006 ש\u0005שניהם]\u0006 עוסקים \u0003בטוען טענת גנב, גנב עצמו\u0004 שמשלם כפל \u0003מנא ליה\u0004 \u0005[מניין לו]?\u0006","\u0003וכי תימא ליתי\u0004 \u0005[ואם תאמר שיבוא,\u0006 יילמד\u0005]\u0006 הדבר \u0003בקל וחומר מטוען טענת גנב,\u0004 ונאמר כך: אם רק טוען טענה זו חייב, גנב עצמו כל שכן שחייב בכפל וארבעה וחמישה. ואולם אם קל וחומר הוא \u0003דיו לבא מן הדין להיות כנדון\u0004 ויש לדון בו כבכל דיני קל וחומר, שהדבר שנלמד מקל וחומר אינו יכול להיות חמור יותר מהמלמד עצמו, ואם כן נאמר: \u0003מה להלן\u0004 בטוען טענת גנב (שהוא המלמד) הרי חיוב זה הוא דווקא \u0003בשבועה\u0004 של שקר — \u0003אף כאן\u0004 הגנב לא יתחייב אלא בשבועה!","ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא,\u0006 נלמד, \u0005לו]\u0006 הדבר \u0003מדתנא דבי\u0004 \u0005[ממה ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה, דתנא דבי\u0004 \u0005[ש\u0006כן \u0005שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה\u0004 על הפסוק האמור בגנב \"אם המצא תמצא בידו הגניבה משור עד חמור עד שה חיים שנים ישלם\" (שמות כב, ג): \u0003יאמר\u0004 הכתוב \u0003שור וגניבה והכל בכלל,\u0004 ומפני מה נמנו כל הפרטים האחרים (חמור, שה)?","על כך יש להשיב: \u0003אילו\u0004 היה כתוב \u0003כך הייתי אומר: מה הפרט מפורש\u0004 — שור שהוא דבר ה\u0003קרב לגבי מזבח, אף כל\u0004 דבר ה\u0003קרב לגבי מזבח\u0004 חייב עליו הגנב תשלומי כפל, \u0003מה יש לך להביא\u0004 (להוסיף) מדיוק זה — \u0003שה,\u0004 שאף הוא קרב לגבי מזבח, אבל דברים אחרים אינם בכלל \"גניבה\","],["\u0003כשהוא אומר \"שה\"\u0004 — \u0003הרי שה\u0004 כבר \u0003אמור\u0004 במפורש, ואין צורך בלימוד זה של \"כעין הפרט\", \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים\u0004 אם כן מה אני לומד מלשון \u0003\"גניבה\"\u0004 — \u0003לרבות כל דבר.\u0004","ויש לשאול על כך: אם כן \u0003יאמר\u0004 רק \u0003\"שור\" \"שה\" ו\"גניבה\" והכל בכלל!\u0004 ומשיבים: \u0003אילו כך, הייתי אומר: מה הפרט מפורש\u0004 — \u0003דבר הקדוש בבכורה\u0004 שהוא שור ושה — \u0003אף כל דבר הקדוש בבכורה,\u0004","\u0003מה יש לך להביא\u0004 (להוסיף) על ידי פרט זה — \u0003חמור. כשהוא אומר\u0004 במפורש \u0003\"חמור\"\u0004 — \u0003הרי חמור\u0004 כבר \u0003אמור\u0004 במפורש, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים\u0004 לומד מלשון \u0003\"גניבה\"\u0004 — \u0003לרבות כל דבר.\u0004","ויש לשאול עוד: אם כן, \u0003יאמר\u0004 הכתוב \u0003\"שור\" ו\"חמור\" \"שה\" ו\"גניבה\" והכל בכלל!\u0004 ומשיבים: \u0003אילו כך, הייתי אומר: מה הפרט מפורש\u0004 — \u0003בעלי חיים, אף כל בעלי חיים.\u0004","\u0003מה יש לך להביא\u0004 על המנוי? — \u0003שאר בעלי חיים, כשהוא אומר\u0004 בסוף הפסוק \u0003\"חיים\"\u0004 — \u0003הרי\u0004 בעלי \u0003חיים אמור, הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים \"גניבה\"\u0004 — \u0003לרבות כל דבר.\u0004 במדרש הלכה זה מצויים דברים תמוהים רבים.","ומבררים את המדרש לפרטיו: \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003יאמר \"שור\" ו\"גניבה\".\u0004 ותוהים: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"שור\" ו\"גניבה\"\u0004 בסדר זה? הלא \u0003\"גניבה\" ו\"שור\" הוא דכתיב\u0004 \u0005[שנאמר]!\u0006","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 במשמעות \u0003\"אילו נאמר\" קאמר\u0004 \u0005[אומר],\u0006 כלומר, \u0003אילו נאמר \"שור\" ו\"גניבה\"\u0004 היינו דורשים בדרך זו, אולם גם כך אין הדבר עולה יפה, \u0003ומי מצית אמרת\u0004 \u0005[והאם יכול אתה לומר]\u0006 לדרך זו את המשך הדברים בברייתא: \u0003מה הפרט מפורש\u0004 שור — אף כל שהוא כעין שור? הלא אם היה כתוב בסדר זה \u0003הוה\u0004 \u0005[היה,\u0006 נעשה\u0005]\u0006 \u0003\"שור\" פרט, ו\"גניבה\" כלל,\u0004 והיה זה \u0003פרט וכלל,\u0004 ולפי כללי ההלכה שבידינו בפרט וכלל אנו אומרים: \u0003נעשה כלל מוסיף על הפרט, ואיתרבו להו כל מילי\u0004 \u0005[ונתרבו כל הדברים]\u0006 בין הדומים לפרט בין שאינם דומים לפרט!","\u0003אלא\u0004 יש לחזור מהסבר זה ולומר שהדרשה \u0003כדכתיב קאמרי\u0004 \u0005[כפי שהכתוב אומר],\u0006 \u0003\"גניבה\"\u0004 קודם ואחר כך \u0003\"שור\".\u0004 ואולם גם כך \u0003מי מצית אמרת\u0004 \u0005[האם יכול אתה לומר]\u0006 במקרה כזה \u0003\"הכל בכלל\", או\u0004 לומר \u0003\"מה הפרט מפורש\"\u0004 כפי שנזכר בברייתא? הלא דרך זו שייכת רק בלימוד של כלל ופרט וכלל, ואילו כאן יש רק כלל ופרט שהרי \u0003הוה ליה\u0004 \u0005[הריהי]\u0006 \u0003\"גניבה\"\u0004 — \u0003כלל ו\"שור\"\u0004 — \u0003פרט,\u0004 ולפי כלל ההלכה במקרה של \u0003כלל ופרט\u0004 אנו אומרים: \u0003אין בכלל אלא מה שבפרט,\u0004 ולפי זה \u0003שור\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 — \u0003לא!\u0004","\u0003אמר רבא:\u0004 כך יש להבין: כששואל ה\u0003תנא\u0004 בתחילה: יאמר \"שור\" ו\"גניבה\" \u0003א\"חיים\" קא סמיך ליה\u0004 \u0005[על\u0006 המילה \u0005\"חיים\" הוא סומך]\u0006 ורואה בה כלל נוסף הבא לאחר הפרטים, \u0003ו\u0004לפי זה בדרך מדרש ההלכה של \u0003כלל ופרט וכלל קאמר ליה\u0004 \u0005[אומר לו],\u0006 כלומר, לדעתו כיון שיש כאן \"גניבה\" \"שור\" ו\"חיים\" שהם כלל ופרט וכלל די היה בכך ולמה נכתבו פרטים נוספים.","ומקשים על כך: \u0003והא לא דמי כללא בתרא לכללא קמא\u0004 \u0005[והרי אינו דומה הכלל האחרון לכלל הראשון]\u0006 שהרי הכלל הראשון (\"גניבה\") מדבר על כל גניבה, ואילו הכלל האחרון (\"חיים\") מצומצם בהרבה וכולל רק בעלי חיים, ואין הם כוללים אותם דברים עצמם, ואם כן אין לדרוש כאן כלל ופרט וכלל! ומשיבים: \u0003הא תנא\u0004 \u0005[תנא זה]\u0006 \u0003דבי\u0004 \u0005[מבית]\u0006 מדרשו של \u0003ר' ישמעאל הוא, דכהאי גוונא דריש כללי ופרטי\u0004 \u0005[שכגון זה דורש כללים ופרטים],\u0006 שלשיטתו, גם אם אין הכללים דומים זה לזה עדיין נדרשים הם בכלל ופרט וכלל.","\u0003והכי קא קשיא ליה\u0004 \u0005[וכך היה קשה לו]:\u0006 \u0003\"אם המצא תמצא\"\u0004 המופיע בתחילת אותו פסוק, שהוא לשון ריבוי, \u0003למה לי?\u0004 וכך פירוש הברייתא: \u0003יאמר \"שור\" ו\"גניבה\" ו\"חיים\", והכל בכלל\u0004 לפי שיטת כלל ופרט וכלל.","על כך אמר בברייתא בתשובה: \u0003אילו כן, הייתי אומר: מה הפרט מפורש\u0004 שהוא \u0003דבר הקרב לגבי מזבח\u0004 — \u0003אף כל הקרב לגבי מזבח, מה יש להביא?\u0004 — \u0003שה, כשהוא אומר \"שה\"\u0004 בפסוק — \u0003הרי שה\u0004כבר \u0003אמור\u0004 במפורש, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים \"גניבה\"? לרבות כל דבר.\u0004","ועל כך יש שוב לשאול: אם כן \u0003יאמר \"גניבה\" ו\"שור\" ו\"שה\" ו\"חיים\", והכל בכלל!\u0004 יש לומר: \u0003אילו כן, הייתי אומר: מה הפרט מפורש דבר הקדוש בבכורה, אף כל דבר הקדוש בבכורה,\u0004","\u0003מה יש לך להביא\u0004 על ידי תוספת זו? — \u0003חמור,\u0004 שאף הוא קדוש בבכורה, ואולם \u0003כשהוא אומר\u0004 בפסוק \u0003\"חמור\"\u0004 — \u0003הרי חמור\u0004 כבר \u0003אמור\u0004 במפורש, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים \"גניבה\"? לרבות כל דבר.\u0004","ועל כך יש שוב לשאול: אם כן, \u0003יאמר \"גניבה\" ו\"שור\" ו\"שה\" ו\"חמור\" ו\"חיים\", והכל בכלל!\u0004 לכך יש להשיב: \u0003אילו כן, הייתי אומר: מה הפרט מפורש\u0004 שהוא כולל רק \u0003בעלי חיים\u0004 — \u0003אף כל בעלי חיים,\u0004","\u0003מה יש לך להביא?\u0004 — \u0003שאר בעלי חיים,\u0004 ואולם \u0003כשהוא אומר\u0004 בכתוב עצמו \u0003\"חיים\"\u0004 — \u0003הרי חיים אמור, הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים\u0004 לומד מלשון \u0003\"גניבה\"\u0004 ככלל? — הרי זה בא \u0003לרבות כל דבר,\u0004 אפילו דברים שאינם חיים. ואם כן, הריבוי של \u0003\"אם המצא תמצא\" למה לי?\u0004"],["ושואלים: \u0003אי הכי, שפיר קשיא ליה\u0004 \u0005[אם כך, יפה קשה לו]!\u0006 שלפי האופן שהעמדנו והסברנו את מהלך הברייתא, יפה הקשה התנא \"המצא תמצא\" למה לי, ומה התירוץ לדבר?","ומשיבים: \u0003משום דאית ליה פירכא\u0004 \u0005[שיש לו שבירה,\u0006 תשובה\u0005]\u0006 לקושיה זו, כי \u0003לרבות כל דבר מהיכא קמייתי ליה\u0004 \u0005[מהיכן\u0006 הוא \u0005מביא,\u0006 לומד \u0005אותו]?\u0006 — \u0003מכלל בתרא\u0004 \u0005[האחרון],\u0006 אולם באותו \u0003כללא גופיה\u0004 \u0005[הכלל עצמו]\u0006 \u0003\"חיים\" כתיב ביה\u0004 \u0005[נאמר בו]\u0006 ואי אפשר ללמוד ממנו גם לדברים שאינם בעלי חיים!","ואם כן \u0003כלל ופרט וכלל\u0004 שיש לפנינו \u0003מאי קא מהני ליה\u0004 \u0005[מה מועיל לו,\u0006 מה נדרש ממנו\u0005]?\u0006 \u0003אי לאתויי\u0004 \u0005[אם להביא]\u0006 לרבות \u0003כל דבר\u0004 — \u0003הא\u0004 \u0005[הרי]\u0006 \u0003\"חיים\" כתיב\u0004 \u0005[נאמר],\u0006 ולכן לא ניתן היה לרבות מכאן אלא כך: \u0003בעלי חיים\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 — \u0003לא.\u0004 \u0003משום הכא\u0004 \u0005[כך]\u0006 \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 לומר גם \u0003\"אם המצא\u0004 תמצא\u0003\".\u0004 שצמד המלים \"המצא תמצא\" הוא עצמו שני הכללים, שכוונתם — כל מה שיימצא, מכל סוג. ומן הכללים הללו ומן הפרטים (שור, חמור ושה) למדים בדרך כלל ופרט וכלל לרבות כל דבר.","\u0003אמרי\u0004 \u0005[אומרים]\u0006 ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003שני כללות\u0004 (כללים) \u0003דסמיכי אהדדי נינהו\u0004 \u0005[שסמוכים זה לזה הם],\u0006 שהכלל הראשון והשני (\"אם המצא\" \"תמצא\") סמוכים זה לזה, ואין הפרט נמצא ביניהם, ואם כן אין זה כלל ופרט וכלל, אלא כלל וכלל ופרט! \u0003אמר רבינא: כדאמרי במערבא\u0004 \u0005[כפי שאומרים\u0006 בענין זה \u0005בארץ ישראל]:\u0006 \u0003כל מקום\u0004 במקרא \u0003שאתה מוצא\u0004 בו \u0003שני כללות הסמוכים זה לזה\u0004 — \u0003הטל פרט\u0004 המופיע לצידם והציבהו \u0003ביניהם,\u0004 כלומר, דרוש כאילו היה הפרט כתוב באמצע בין הכללים, \u0003ודונם בכלל ופרט\u0004 וכלל.","ובפירוט הדברים שואלים: \u0003שדי\u0004 \u0005[זרוק,\u0006 הטל\u0005]\u0006 את המלה \u0003\"שור\" בין \"המצא\" ל\"תמצא\", לאתויי מאי\u0004 \u0005[להביא,\u0006 לרבות \u0005מה],\u0006 אלו דברים נוספים נלמדים לחיוב תשלומי כפל על ידי כך? \u0003אי לאתויי\u0004 \u0005[אם להביא,\u0006 לרבות\u0005]\u0006 וללמוד מכאן כל \u0003בעלי חיים\u0004 — הלא \u0003מ\u0004המלה \u0003\"חיים\" נפקא\u0004 \u0005[יוצא]\u0006 הדבר! \u0003אלא לאתויי\u0004 \u0005[להביא]\u0006 \u0003דבר\u0004 כעין הפרט \u0003שאין\u0004 הוא בכלל \u0003בעלי חיים, ודרוש הכי\u0004 \u0005[כך]:\u0006 \u0003מה הפרט\u0004 (\"שור\") \u0003מפורש\u0004 שהוא \u0003דבר המטלטל וגופו ממון, אף כל דבר המטלטל וגופו ממון.\u0004","\u0003ותו\u0004 \u0005[ועוד]\u0006 שואלים: \u0003שדי\u0004 \u0005[הטל]\u0006 את הפרט \u0003\"חמור\" בין \"המצא\" ל\"תמצא\", לאתויי מאי\u0004 \u0005[להביא מה]\u0006 על ידי כך? \u0003אי לאתויי\u0004 \u0005[אם להביא]\u0006 \u0003דבר שאין בעלי חיים\u0004 — הלא \u0003מ\"שור\" נפקא\u0004 \u0005[יוצא]\u0006 הדבר! \u0003אלא\u0004 נאמר שבא \u0003לאתויי\u0004 \u0005[להביא]\u0006 \u0003דבר מסויים,\u0004 שאי אפשר לחייב גנב בתשלומי כפל על דבר שאינו מוגדר בסימניו ובמידותיו.","\u0003אי הכי\u0004 \u0005[אם כך]\u0006 המלה \u0003\"שה\" למה לי? אלא\u0004 יש לחזור מכל אופן הסברה זה, ולומר כי במקום בו שני כללים סמוכים ופרט בצידם, אין זה לימוד בשיטת כלל ופרט וכלל, אלא בדרך הלימוד של \u0003ריבה ומיעט וריבה הוא,\u0004 ו\u0003כ\u0004דרך \u0003תנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל\u0004 לענין אחר.","\u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל\u0004 בענין סימני דגים טהורים: \u0003\"במים\" \"במים\" שתי פעמים\u0004 האמורות בכתוב (\"את זה תאכלו מכל אשר במים כל אשר לו סנפיר וקשקשת במים...\", ולאחריהם מופיע הפרט \"בימים ובנחלים\". ויקרא יא, ט) — \u0003אין זה כלל ופרט, אלא ריבה ומיעט וריבה,\u0004 ועל ידי ריבוי זה \u0003ריבה הכל.\u0004 ואף הכתוב שלנו בענין גניבה נדרש לשיטה זו בדרך ריבוי ומיעוט וריבוי.","ושואלים: לדרך זו \u0003מאי רבי\u0004 \u0005[מה ריבה]\u0006 — \u0003רבי כל מילי\u0004 \u0005[ריבה כל דבר]?\u0006 \u0003אי הכי, כל הני פרטי\u0004 \u0005[אם כך, כל אותם הפרטים]\u0006 הכתובים באמצע \u0003למה לי,\u0004 אם ריבה הכל? ומשיבים: הפרטים באים לכך: \u0003חד למעוטי\u0004 \u0005[אחד למעט]\u0006 גונב \u0003קרקע,\u0004 \u0003וחד למעוטי\u0004 \u0005[ואחד למעט]\u0006 גונב \u0003עבדים,\u0004 \u0003וחד למעוטי\u0004 \u0005[ואחד למעט]\u0006 גונב \u0003שטרות,\u0004 שבכל אלה אין דין כפל, ומה שנאמרו בכתוב זה גם לשונות כלליים \u0003\"גניבה\" ו\"חיים\"\u0004 לא לצורך מיעוט לענין כפל נאמרו אלא לדרשה אחרת, \u0003לכדרב\u0004 \u0005[ל\u0006כמו \u0005ש\u0006אמר \u0005רב],\u0006 ש\u0003אמר: אחייה\u0004 \u0005[החייה,\u0006 השאר בעינו\u0005]\u0006 \u0003לקרן כעין שגנב,\u0004 שצריך הדיין להשאיר את הקרן, את ערכו המקורי של הדבר הנגנב כמו שהיה בשעת הגניבה, ואם פחת בינתיים שוויו — צריך הגנב לשלם כשוויו בזמן הגניבה. עד כאן עסקנו במקור לחיוב כפל בגנב עצמו, לדעת הברייתא הראשונה הסבורה כי שני הפסוקים \"אם ימצא הגנב\" (שמות כב, ו) \"אם לא ימצא הגנב\" (שמות כב, ז) עוסקים בטוען טענת גנב.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר],\u0006 הברייתא השניה, כי \u0003חד\u0004 \u0005[\u0006פסוק \u0005אחד]\u0006 \u0003בגנב\u0004 עצמו, \u0003וחד\u0004 \u0005[ו\u0006פסוק \u0005אחד]\u0006 \u0003בטוען טענת גנב, וגנב עצמו נפקא ליה\u0004 \u0005[יוצא לו]\u0006 \u0003מ\"אם ימצא הגנב\",\u0004 אם כן \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"אם המצא תמצא\" מאי דריש ביה\u0004 \u0005[מה דורש\u0006 הוא \u0005בו]?\u0006 הלא אינו לומד ממנו דבר!","ומשיבים: \u0003מבעי ליה\u0004 \u0005[נצרך לו]\u0006 \u0003ל\u0004כפי שאמר \u0003רבא בר אהילאי,\u0004 ש\u0003אמר רבא בר אהילאי:\u0004 \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רב,\u0004 ש\u0003אמר\u0004 כלל בדיני קנסות: \u0003מודה בקנס\u0004 שהוא עצמו הודה שחייב בדבר שיש בו קנס. אף ש\u0003אחר כך באו עדים\u0004 והעידו בו על המעשה — \u0003פטור?\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אם המצא תמצא\u0004 בידו הגניבה... שנים ישלם\u0003\"\u0004 (שמות כב, ג), וכך יש להבין: \u0003\"אם המצא\"\u0004 פירושו \u0003בעדים\u0004 שבאו עדים שגנב, \u0003\"תמצא\"\u0004 פירושו \u0003בדיינים,\u0004 כלומר, אז הריהו חייב בתשלומי כפל, \u0003פרט למרשיע את עצמו,\u0004 שהודה בעצמו על אשמתו. שכיון שהרשיע עצמו והמציא בעצמו את הגניבה — אינו בדין תשלומי כפל, וכיוצא בזה כל תשלומי הקנס האמור בתורה.","ושואלים: \u0003ולמאן דאמר תרוייהו\u0004 \u0005[ול\u0006דעת \u0005מי שאומר\u0006 ש\u0005שניהם],\u0006 שני הכתובים, מדברים \u0003בטוען טענת גנב, דהאי\u0004 \u0005[שזה]\u0006 \u0003\"אם המצא תמצא\" מפיק ליה\u0004 \u0005[מוציא\u0006 לומד \u0005אותו]\u0006 \u0003לגנב עצמו,\u0004 שגם הגנב (שלשיטה זו לא נתפרש בכתוב) משלם כפל, דין זה של \u0003מרשיע\u0004 את \u0003עצמו\u0004 שפטור מכפל (ושאר קנסות) \u0003מנלן\u0004 \u0005[מניין לנו]?\u0006 ומשיבים: \u0003מ\u0004דיוק הכתוב \u0003\"אשר ירשיען אלהים\u0004 ישלם שנים לרעהו\u0003\"\u0004 (שמות כב, ח), לומר: דווקא זה שהרשיעו הדיינים משלם כפל (ושאר קנסות), \u0003ולא המרשיע את עצמו.\u0004","ושואלים לצד שני: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 \u0003חד\u0004 \u0005[\u0006פסוק \u0005אחד]\u0006 \u0003בגנב, וחד\u0004 \u0005[ו\u0006פסוק \u0005אחד]\u0006 \u0003בטוען טענת גנב, דאייתי ליה\u0004 \u0005[שמביא,\u0006 מוציא \u0005אותו]\u0006 מן הכתוב \u0003\"המצא תמצא\"\u0004 \u0003ל\u0004מעט \u0003מרשיע את עצמו, האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"אשר ירשיען\" מאי דריש ביה\u0004 \u0005[מה דורש\u0006 הוא \u0005בו]?\u0006 ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך: ההוא מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 \u0003ל\u0004עצם הדין ש\u0003מודה בקנס\u0004 (ולא באו אחרי כן עדים) ש\u0003פטור\u0004 מן הקנס.","ומן הצד השני: \u0003ומאן דאמר תרוייהו\u0004 \u0005[ו\u0006לדעת \u0005מי שאומר\u0006 כי \u0005שניהם],\u0006 שני הכתובים, מדברים \u0003בטוען טענת גנב\u0004 ומ\"המצא תמצא\" למד לגנב עצמו, \u0003קסבר\u0004 \u0005[סבור]:\u0006 ש\u0003מודה בקנס ואחר כך באו עדים\u0004 — \u0003חייב\u0004 שלא כרב. ואם כן מ\"ירשיעון\" אין למדים אלא למודה בקנס ולא באו עדים שפטור.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 כי \u0003חד\u0004 \u0005[\u0006פסוק \u0005אחד]\u0006 מדבר \u0003בגנב וחד\u0004 \u0005[ו\u0006פסוק \u0005אחד]\u0006 \u0003בטוען טענת גנב, דנפקא ליה גנב מהתם\u0004 \u0005[שיוצא לו\u0006 דין \u0005גנב משם],\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 שהריבוי בכתוב זה \u0003\"אם המצא תמצא\"\u0004 בא ללמדנו למה שאמר \u0003רבא בר אהילאי,\u0004 שבא למעט מרשיע עצמו ואחר כך באו עדים. \u0003אבל כל הני פרטי\u0004 \u0005[הפרטים הללו]\u0006 (שור, חמור, שה, חיים) \u0003למה לי?\u0004 שהרי לשיטה זו המיעוט של קרקעות עבדים ושטרות מכפל נלמד ממקור אחר!","ומשיבים: יש לתרץ זאת \u0003כדתנא דבי\u0004 \u0005[כ\u0006שיטה \u0005ששנה\u0006 החכם \u0005שמבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל, דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: כל פרשה שנאמרה\u0004 בתורה \u0003ונשנית\u0004 (נאמרה פעם שנית), \u0003לא נשנית אלא ל\u0004צורך \u0003דבר\u0004 מסויים \u0003שנתחדש בה,\u0004 ואגב חידוש זה ייתכן שחזרה התורה וכתבה גם שאר דברים שאין בהם חידוש. ואף כאן התחדש בפרשה מהמילים \"המצא תמצא\" הדין שמודה בקנס ואחר כך באו עדים שפטור.","ושואלים: כיון שאנו משווים גנב לטוען טענת גנב \u0003ואימא\u0004 \u0005[ואמור]\u0006 שאף \u0003גנב עצמו\u0004 (כמו הטוען טענת גנב) לא יתחייב בתשלומי כפל אלא \u0003בשבועה.\u0004 שרק כשייחשד בגניבה, וישבע שלא גנב, ויוכח שנשבע לשקר — ישלם כפל!","ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[\u0006יכול אתה \u0005לעלות על דעתך]\u0006 לומר כן, \u0003דתניא\u0004 \u0005[ש\u0006כן כבר \u0005שנינו\u0006 בברייתא\u0005],\u0006 ש\u0003ר' יעקב אומר:\u0004 מה שנאמר בגנב \u0003\"שנים ישלם\"\u0004 (שמות כב, ח) כוונתו — ישלם תמיד, אף \u0003שלא בשבועה.\u0004 והוא דן: \u0003אתה אומר\u0004 שישלם אף \u0003שלא בשבועה, או אינו\u0004 משלם \u0003אלא\u0004 דווקא \u0003בשבועה? אמרת לא כך היה,\u0004 כלומר, אי אפשר לומר כך.","ושואלים: מה פירושה של ברייתא זו, \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"לא כך היה\",\u0004 כלומר, מדוע אי אפשר לומר כך? \u0003אמר אביי,\u0004 כך יש להבין: ש\u0003לא לכתוב רחמנא\u0004 \u0005[תכתוב התורה]\u0006 \u0003\"שנים ישלם\" בגנב, וליתי\u0004 \u0005[ויבוא,\u0006 ויילמד\u0005]\u0006 דין זה בפשטות \u0003בקל וחומר מטוען טענת גנב.\u0004 ונאמר כך: \u0003ומה טוען טענת גנב דבהיתירא אתא לידיה\u0004 \u0005[שבהיתר בא לידו]\u0006 החפץ כפקדון, אלא שלאחר זמן גנבו — \u0003אמר קרא לישלם תרי\u0004 \u0005[אמר הכתוב שישלם שנים],\u0006 \u0003גנב עצמו דבאיסורא אתא לידיה\u0004 \u0005[שבאיסור בא\u0006 החפץ \u0005לידו]\u0006 \u0003לא כל שכן\u0004 שמשלם כפל?","\u0003אלא \"שנים ישלם\" דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003בגנב עצמו למה לי?\u0004 הרי זה בא להוסיף בדין הגנב ולומר ש\u0003אפילו שלא בשבועה\u0004 משלם תשלומי כפל.","ושואלים: \u0003והאי\u0004 \u0005[ו\u0006כתוב \u0005זה]\u0006 \u0003\"אם המצא\"\u0004 (שבסופו נאמר \"ישלם שנים\") \u0003להכי הוא דאתא\u0004 \u0005[ל\u0006דבר \u0005זה הוא שבא]\u0006 ללמדנו? \u0003הא מיבעי ליה לכדתניא\u0004 \u0005[הרי צריך הוא\u0006 לענין אחר \u0005לכפי ששנינו\u0006 בברייתא\u0005]:\u0006 נאמר \"אם המצא תמצא בידו הגניבה\" (שמות כב, ח), \u0003\"ידו\"\u0004"],["\u0003אין לי אלא\u0004 אם נמצאה הגניבה בתוך \u0003ידו\u0004 ממש, ואולם אם נמצא הדבר הגנוב בתוך \u0003גגו\u0004 או בתוך \u0003חצירו\u0004 או בתוך \u0003קרפיפו\u0004 (חצר סגורה) \u0003מנין\u0004 שכך הוא הדין? — \u0003תלמוד לומר: \"אם המצא תמצא\"\u0004 (שמות כב, ג), \u0003מכל מקום,\u0004 שבכל מקום ואופן שהגניבה ברשותו חייב לשלם. ואם כן למדנו כבר דבר אחר מכפילות הפסוק!","ומשיבים: \u0003אם כן,\u0004 אם רק דבר זה בא הכתוב ללמדנו, \u0003לימא קרא\u0004 \u0005[שיאמר הכתוב]\u0006 \u0003או \"המצא המצא\" או\u0004 שיאמר \u0003\"תמצא תמצא\", מדשני קרא\u0004 \u0005[מ\u0006מה \u0005ששינה הכתוב]\u0006 בלשונו ואמר \"המצא תמצא\", \u0003שמע מינה תרתי\u0004 \u0005[למד מכאן שני\u0006 דברים\u0005],\u0006 הן לענין ריבוי שהגנב עצמו משלם כפל בכל דבר שגנב, והן לענין הגדרת המקום בו נמצאת הגניבה.","וחוזרים לדון \u0003גופא\u0004 \u0005[לגופם]\u0006 של דברים שנאמרו קודם לכן, \u0003אמר רב:\u0004 את ה\u0003קרן\u0004 משלם הגנב \u0003כעין שגנב,\u0004 כלומר, באותו ערך שהיה לדבר בשעה שגנבו. ואילו \u0003תשלומי כפל ותשלומי ארבעה וחמשה\u0004 משלם \u0003כ\u0004ערכם ב\u0003שעת העמדה בדין.\u0004","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר, מהו מקור דין זה של \u0003רב?\u0004 ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"גניבה\" ו\"חיים\"\u0004 (\"אם המצא תמצא בידו הגניבה משור עד חמור עד שה חיים\". שמות כב, ח), \u0003אמאי קאמר רחמנא\u0004 \u0005[מדוע אמרה התורה]\u0006 \u0003\"חיים\" בגניבה?\u0004 כוונתו: \u0003אחייה\u0004 \u0005[החייה,\u0006 השאר\u0005]\u0006 את ה\u0003קרן כעין\u0004 המצב שהיתה בשעה \u0003שגנב,\u0004 ולכן את הקרן צריך להחזיר כשוויה בשעת הגניבה.","\u0003אמר רב ששת: אמינא\u0004 \u0005[אומר אני]\u0006 \u0003כי ניים ושכיב\u0004 \u0005[כאשר נמנם ושכב]\u0006 \u0003רב אמר להא שמעתא\u0004 \u0005[את ההלכה הזו],\u0006 כלומר, לא דקדק רב בדבריו אלה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 היתה הבהמה שגנב \u0003כחושה, והשמינה\u0004 פיטם אותה הגנב — \u0003משלם תשלומי כפל ותשלומי ארבעה וחמשה כעין שגנב.\u0004 מכאן שמשלם הכל כעין שגנב, ולא כשעת העמדה בדין כדברי רב!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: מכאן אין ראיה לדחות את דברי רב, \u0003משום דאמר ליה\u0004 \u0005[שיכול לומר לו]\u0006 הגנב לבעל הבהמה : \u0003אנא פטימנא\u0004 \u0005[אני פיטמתי]\u0006 את הבהמה הכחושה \u0003ואת שקלת\u0004 \u0005[ואתה תקבל]\u0006 את דמיה כשוויה בשעת העמדה בדין? ואין להביא מכאן ראיה לסתור את דברי רב.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 סתירה לדברי רב ממקור אחר בו לא קיימת טענה זו, ששנינו: היתה הבהמה \u0003שמינה\u0004 בזמן שנגנבה, \u0003והכחישה,\u0004 שגרם לה הגנב לרזות או לרדת בערכה — \u0003משלם תשלומי כפל ותשלומי ארבעה וחמשה כעין שגנב,\u0004 ושלא כדברי רב!","ומשיבים: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 יש טעם מיוחד לדבר — \u0003משום דאמרינן ליה\u0004 \u0005[שאנו אומרים לו]\u0006 לגנב: \u0003מה לי קטלה\u0004 (הרגה) \u0003כולה, מה לי קטלה פלגא\u0004 \u0005[חציה],\u0006 שהרי הכחשתה בידי הגנב היא כעין הריגתה במקצת על ידו, ולכן משלם ארבעה וחמישה כשעה שגנב כאילו טבחה אז מיד, אלא \u0003כי קאמר\u0004 \u0005[כאשר אומר]\u0006 \u0003רב\u0004 את הלכתו הרי זה \u0003ב\u0004מקרה של \u0003יוקרא וזולא\u0004 \u0005[יוקר וזול],\u0006 שעלה או ירד ערך הגניבה, \u0003הוא דקאמר\u0004 \u0005[שאומר],\u0006 ולא במקרה של שינוי שחל בגוף הדבר לטובה או לרעה.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא דמעיקרא שויא זוזא\u0004 \u0005[אם תאמר שמתחילה\u0006 היתה \u0005שווה זוז\u0006 אחד\u0005]\u0006 \u0003ולבסוף שויא\u0004 \u0005[היתה שווה]\u0006 \u0003ארבעה זוזי\u0004 \u0005[זוזים]\u0006 ישלם במקרה זה \u0003קרן כעין שגנב\u0004 במחיר של זוז אחד. אם כן, \u0003לימא פליגא\u0004 \u0005[האם נאמר\u0006 איפוא כי \u0005חלוקים]\u0006 דברי \u0003רב\u0004 על דבריו של \u0003רבה,\u0004 ש\u0003אמר רבה: האי מאן\u0004 ש\u0003גזל חביתא דחמרא מחבריה\u0004 \u0005[חבית יין מחבירו],\u0006 \u0003מעיקרא שויא זוזא\u0004 \u0005[בתחילה\u0006 היתה \u0005שווה זוז]\u0006 \u0003ולבסוף שויא\u0004 \u0005[שווה]\u0006 \u0003ארבעה זוזי\u0004 \u0005[זוזים],\u0006 אם \u0003תברה\u0004 \u0005[שברה]\u0006 \u0003או שתייה\u0004 \u0005[שתה אותה],\u0006 כלומר, שעשה בה מעשה ואיבדה מן העולם בעצמו — \u0003משלם ארבע\u0004 זוזים כשוויה לבסוף. ואולם אם \u0003איתבר\u0004 \u0005[נשברה]\u0006 \u0003ממילא\u0004 (מעצמה) — \u0003משלם\u0004 רק \u0003זוזא\u0004 \u0005[זוז]\u0006 אחד, כשוויה בשעת הגניבה, ואם כן רבה מחלק אף בתשלום הקרן עצמה, שלא בכל מקרה משלם כעין שגנב ושלא כדברי רב.","\u0003אמרי\u0004 \u0005[אומרים]\u0006 כדי ליישב את הדברים: \u0003כי קאמר\u0004 \u0005[כאשר אומר]\u0006 \u0003רב\u0004 שמשלם כשעת הגניבה, הרי זה \u0003כגון דמעיקרא שויא\u0004 \u0005[שמתחילה\u0006 היתה \u0005שווה]\u0006 הגניבה \u0003ארבע\u0004 זוזים \u0003ולבסוף שויא זוזא\u0004 \u0005[שווה זוז]\u0006 אחד, שבכגון זה \u0003קרן\u0004 משלם \u0003כעין שגנב,\u0004 ואילו \u0003תשלומי כפל ותשלומי ארבעה וחמשה\u0004 — \u0003כשעת העמדה בדין.\u0004","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חנינא\u0004 ברייתא שיש בה כדי \u0003לסיועיה\u0004 \u0005[לסייע לו]\u0006 \u0003לרב,\u0004 וכך שנינו בה: \u0003בעל הבית שטען טענת גנב בפקדון\u0004 שנמסר לידו, \u0003ונשבע\u0004 שאכן נגנב, \u0003ו\u0004לבסוף \u0003הודה\u0004 שהוא עצמו גנב, \u0003ובאו עדים\u0004 והעידו שהוא גנבה, \u0003אם עד שלא באו עדים הודה\u0004 — \u0003משלם קרן וחומש\u0004 לבעלים \u0003ו\u0004מביא קרבן \u0003אשם,\u0004 כפי שמשלם כל המחזיר גזילה מדעתו לאחר שנשבע וחזר בו, \u0003ואם משבאו עדים הודה\u0004 — \u0003משלם תשלומי כפל ואשם\u0004 כדין טוען טענת גנב, \u0003ו\u0004אולם \u0003חומשו\u0004 שצריך לתת לבעל הפקדון \u0003עולה לו בכפילו\u0004 (מכוסה על ידי תשלום הכפל) שמשלם, אלו \u0003דברי ר' יעקב.\u0004"],["\u0003וחכמים אומרים:\u0004 נאמר בכופר בפקדון \"ושלם אותו \u0003בראשו וחמשיתיו\u0004 יוסף עליו\" (ויקרא ה, כד), לומר: \u0003ממון המשתלם בראש,\u0004 כלומר, כאשר משלם את הקרן בלבד, רק אז \u0003מוסיף\u0004 עליו \u0003חומש,\u0004 ואולם כאשר משלם \u0003ממון שאין משתלם בראש\u0004 ונותן יותר ממה שלקח — \u0003אין מוסיף\u0004 עליו \u0003חומש. ר' שמעון בן יוחאי אומר: אין חומש ו\u0004אף לא \u0003אשם משתלם במקום שיש\u0004 תשלומי \u0003כפל.\u0004","\u0003קתני מיהת\u0004 \u0005[שנה על כל פנים]:\u0006 \u0003חומשו עולה לו בכפילו,\u0004 אלו \u0003דברי ר' יעקב.\u0004 ומעתה נברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה\u0006 \u0005הדבר]?\u0006 \u0003אילימא דמעיקרא שויא\u0004 \u0005[אם נאמר שמתחילה\u0006 היתה \u0005שווה]\u0006 הגניבה \u0003ארבעה\u0004 זוזים \u0003ולבסוף שויא\u0004 \u0005[שווה]\u0006 \u0003ארבעה,\u0004 כיצד יכול הוא לומר \u0003חומשו עולה לו בכפילו?\u0004","הלא \u0003כפילא\u0004 \u0005[הכפל]\u0006 \u0003ארבעה\u0004 הוא, \u0003ו\u0004אילו \u0003חומשא\u0004 \u0005[והחומש]\u0006 אינו אלא \u0003זוזא\u0004 \u0005[זוז]\u0006 אחד! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003דמעיקרא שויא\u0004 \u0005[שמתחילה שווה]\u0006 הגניבה \u0003ארבעה\u0004 זוזים, \u0003ולבסוף שויא זוזא\u0004 \u0005[שווה זוז\u0006 אחד\u0005],\u0006 ובמקרה זה יהיה \u0003דכפילא זוזא\u0004 \u0005[שהכפל\u0006 הוא \u0005זוז]\u0006 לפי ערכה עכשיו \u0003וחומשיה זוזא\u0004 \u0005[והחומש זוז]\u0006 לפי ערכה כשנגנבה,","\u0003אלמא\u0004 \u0005[מכאן]\u0006 תסיק כי \u0003קרן\u0004 (וכן חומשו) משלם \u0003כעין\u0004 הערך \u0003שגנב, תשלומי כפל ותשלומי ארבעה וחמשה כשעת העמדה בדין,\u0004 וכדברי רב!","את ההוכחה הזו דוחים, \u0003אמר רבא: לעולם\u0004 תפרש שמדובר במקרה \u0003דמעיקרא שויא\u0004 \u0005[שמתחילה\u0006 היה \u0005שווה]\u0006 \u0003ארבעה והשתא נמי שויא\u0004 \u0005[ועכשיו גם כן שווה]\u0006 \u0003ארבעה\u0004 זוזים, \u0003ודקא קשיא\u0004 \u0005[ו\u0006מה \u0005שהיה קשה]\u0006 לך הרי \u0003כפילא\u0004 \u0005[הכפל]\u0006 \u0003ארבעה וחומשיה זוזא\u0004 \u0005[וחומשו\u0006 רק \u0005זוז אחד]!\u0006 — \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שנשבע וחזר ונשבע ארבע פעמים\u0004 לשקר \u0003והודה, והתורה אמרה \"וחמשתיו\"\u0004 (ויקרא ה, כד) שהוא לשון רבים, לומר:","\u0003התורה ריבתה חמישיות הרבה בקרן אחת,\u0004 שככל שמוסיף ונשבע לשקר משלם עוד ועוד חמישיות.","לעצם בירור הענין בברייתא שהבאנו, \u0003אמר מר\u0004 \u0005[החכם],\u0006 \u0003וחכמים אומרים: \"בראשו וחמשתיו\"\u0004 — \u0003ממון המשתלם בראש מוסיף חומש, ממון שאין משתלם בראש אין מוסיף חומש.\u0004 ומדייקים: \u0003אבל\u0004 אף לשיטתם קרבן \u0003אשם מייתי\u0004 \u0005[מביא].\u0006","ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003חומש\u0004 ש\u0003לא משלם\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"בראשו וחמשתיו\",\u0004 אם כן \u0003אשם נמי\u0004 \u0005[גם כן]\u0006 \u0003לא משלם, דהא כתיב\u0004 \u0005[שהרי נאמר\u0006 באותו כתוב\u0005]:\u0006 \u0003\"בראשו וחמשתיו... ואת אשמו\"\u0004 (ויקרא ה כד–כה)!","ומשיבים: \u0003אמרי\u0004 \u0005[\u0006יכולים היו \u0005לומר]\u0006 \u0003לך רבנן\u0004 \u0005[חכמים]:\u0006 המלה \u0003\"את\"\u0004 הבאה באמצע (\"ואת אשמו\") \u0003פסקיה קרא\u0004 \u0005[הפסיקה את הכתוב]\u0006 לומר שדין הקרן (\"ראשו וחמישיתו\") ודין החמישית שווים, ואין כן דין האשם, שאותו מביא בכל אופן.","\u0003ו\u0004לעומתם \u0003ר' שמעון בן יוחאי\u0004 הסבור שאף מאשם פטור מה הוא אומר? \u0003\"ואת\"\u0004 אותה \"את\" עצמה שנאמרה עם וי\"ו החיבור (\"ואת\") \u0003ערביה קרא\u0004 \u0005[ערב אותו\u0006 את האשם \u0005הכתוב]\u0006 לומר שדין החומש ודין האשם שווים. שמשלם שניהם רק כאשר משלם קרן בלבד. ומן הצד השני \u0003ורבנן אמרי\u0004 \u0005[וחכמים\u0006 היו יכולים \u0005לומר]\u0006 \u0003לך\u0004 בתשובה לסברתו של ר' שמעון בר יוחאי: אם כן ש\"ואת\" בא לערב, עדיף היה ש\u0003לא ליכתוב רחמנא\u0004 \u0005[תכתוב התורה]\u0006 \u0003לא וי\"ו ולא \"את\",\u0004 ושתכתוב רק \"אשמו\", וכיון שנאמר שם \"ואת\" — הרי זה להפסיק.","\u0003ור' שמעון בן יוחאי אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 כך בתשובה לטענה זו: בכל מקרה \u0003\"את\"\u0004 בלבד \u0003לא סגיא\u0004 \u0005[די,\u0006 אי אפשר\u0005]\u0006 ש\u0003לא כתב\u0004 \u0005[ייכתב],\u0006 משום שהוא צריך \u0003לאפסוקי\u0004 \u0005[להפסיק]\u0006 \u0003בין ממון גבוה\u0004 (אשם, שהוא קרבן לה') \u0003לממון הדיוט\u0004 (חומש, הניתן לנגזל), \u0003הלכך אתא\u0004 \u0005[על כן באה]\u0006 \u0003וי\"ו ערביה קרא\u0004 \u0005[\u0006ו\u0005עירב את הפסוק]\u0006 שנית, לצרף דין חומש ואשם עם הקרן.","ודנים עוד באותו ענין של חובת התשלומים במקרה שינוי שנעשה בדבר שנגנב אצל הגנב. \u0003אמר ר' אילעא: גנב טלה\u0004 וגדל \u0003ונעשה איל,\u0004 או גנב \u0003עגל ונעשה שור\u0004 — \u0003נעשה\u0004 הדבר הגנוב \u0003שינוי בידו\u0004 של הגנב \u0003וקנאו\u0004 בכך, שנעשה כקניינו של הגנב, אף שחייב להשיב לבעלים את מחירו ואת כפילו. ולכן, אם \u0003טבח ומכר\u0004 אותם כשהם כבר איל או שור — \u0003שלו הוא טובח, שלו הוא מוכר,\u0004 ואינו צריך לשלם ארבעה וחמישה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' חנינא לר' אילעא\u0004 ממה ששנינו בברייתא: \u0003גנב טלה ונעשה איל, עגל ונעשה שור\u0004 — \u0003משלם תשלומי כפל ותשלומי ארבעה וחמשה כעין שגנב. ואי סלקא דעתך קנייה\u0004 \u0005[ואם עולה על דעתך\u0006 לומר ש\u0005קנאו]\u0006 \u0003בשינוי\u0004 כאשר נעשה איל או שור, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003משלם\u0004 ארבעה וחמישה? הלא לשיטתך \u0003שלו הוא טובח, שלו הוא מוכר!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אילעא: \u0003ואלא מאי\u0004 \u0005[מה]\u0006 תאמר, כי \u0003שינוי לא קני\u0004 \u0005[קונה],\u0006 אם כן \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003משלם כעין שגנב? לשלם כי השתא\u0004 \u0005[שישלם כמו\u0006 שווים \u0005עכשיו],\u0006 כבהמה גדולה, איל או שור!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' חנינא: \u0003כי השתא היינו טעמא\u0004 \u0005[כמו עכשיו זהו הטעם]\u0006 שהוא \u0003לא משלם\u0004 — \u0003משום דאמר ליה\u0004 \u0005[שאומר לו]\u0006 הגנב לבעל הבהמה: וכי \u0003תורא גנבי\u0004 \u0005[שור גנבתי]\u0006 \u0003ממך,\u0004 או \u0003דיכרא גנבי\u0004 \u0005[איל גנבתי]\u0006 \u0003ממך?\u0004 לא גנבתי אלא עגל או טלה, ולכן אני משלם כפי הערך שהיה כשגנבתי. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אילעא: \u0003רחמנא ניצלן מהאי דעתא\u0004 \u0005[ה' יצילנו מדעה כזו],\u0006 מן הטענה המוזרה שלך! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' חנינא: \u0003אדרבה\u0004 (להיפך), \u0003רחמנא ניצלן מדעתא דידך\u0004 \u0005[ה' יצילנו מהדעה שלך]\u0006 שאינה מבוססת.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' זירא: וניקנינהו\u0004 \u0005[ושיקנה אותם]\u0006 הגנב את הבהמות הללו שבידו \u0003בשינוי השם\u0004 בלבד, שהרי קודם היו קרויות בשמות אחרים: \"טלה\" ו\"עגל\" ועכשיו נקראות \"איל\" ו\"שור\"!","\u0003אמר רבא:\u0004 זה אינו נחשב שינוי, כי אפילו \u0003שור בן יומו קרוי\u0004 כבר \u0003\"שור\",\u0004 וכן \u0003איל בן יומו קרוי \"איל\".\u0004 וראיה לדבר, \u0003שור בן יומו קרוי \"שור\"\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"שור או כשב או עז כי יולד\"\u0004 (ויקרא כב, כז), הרי שמשעה שנולד קרוי הוא \"שור\", וכן","\u0003איל בן יומו קרוי \"איל\"\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 שאמר יעקב ללבן: \u0003\"ואילי צאנך לא אכלתי\"\u0004 (בראשית לא, לח), נדייק מדבריו ש\u0003אילים הוא\u0004 ש\u0003לא אכל,\u0004 אבל \u0003כבשים\u0004 שהם קטנים יותר \u0003אכל? אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003איל בן יומו קרוי \"איל\",\u0004 והתכוון יעקב לומר שלא אכל כלל מהם לא כגדולים ולא כקטנים.","ושואלים: \u0003מכל מקום קשיא\u0004 \u0005[קשה]\u0006 לר' אילעא מן הברייתא שהביא ר' חנינא, שאם גדילתה של הבהמה אכן נחשבת שינוי וקנין מדוע משלם ארבעה וחמישה? \u0003אמר רב ששת: הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 — כשיטת \u0003בית שמאי היא, דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]:\u0006 \u0003שינוי במקומו עומדת,\u0004 כלומר, השינוי אינו מועיל להפקיע את הדבר הנגנב מרשות הבעלים, אלא נחשב הוא עוד ברשות הבעלים, \u0003ו\u0004לכן הגנב \u0003לא קני\u0004 \u0005[קונה]\u0006 את החפץ בשינוי ומשום כך משלם ארבעה וחמישה.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 אדם ש\u0003נתן לה,\u0004 לזונה, \u0003באתננה חיטין ועשאן\u0004 הזונה \u0003סולת,\u0004 או נתן לה \u0003זיתים ועשאן שמן, ענבים ועשאן יין. תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]\u0006 ש\u0003אסור\u0004 להביא דברים אלה לקרבן, משום אתנן זונה, שאסרה התורה להקריב דבר שניתן כתשלום לזונה (\"לא תביא אתנן זונה ומחיר כלב בית ה' אלהיך\". דברים כג, יט). \u0003ותני חדא\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחת]\u0006 ש\u0003מותר\u0004 משום שאין זה שוב אותו חפץ. \u0003ואמר רב יוסף: תני\u0004 \u0005[שנה]\u0006 החכם \u0003גוריון\u0004 שמן העיר \u0003אספורק: בית שמאי אוסרין, ובית הלל מתירין,\u0004 ששתי ברייתות חלוקות אלה הן שיטותיהן החלוקות של בית שמאי ובית הלל.","ומבררים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003בית שמאי\u0004 האוסרים? — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"לא תביא אתנן זונה ומחיר כלב בית ה' אלהיך... כי תועבת ה' אלהיך גם שניהם\" (דברים כג, יט), \u0003\"גם\"\u0004 בא \u0003לרבות\u0004 את \u0003שינוייהם,\u0004 שגם אם נשתנו הדברים עדיין הם אסורים. \u0003ובית הלל\u0004 המתירים סבורים כי הכתוב במקרא \u0003\"הם\"\u0004 (\"שניהם\"), בא להדגיש: \u0003ולא שינוייהם.\u0004","\u0003ובית שמאי\u0004 משיבים לכך: \u0003ההוא\u0004 \u0005[אותו]\u0006"],["\u0003\"הם\"\u0004 — \u0003ולא ולדותיהם הוא דאתא\u0004 \u0005[שבא]\u0006 ביטוי זה ללמדנו. ושואלים: \u0003ובית הלל,\u0004 מהיכן לומדים הם הלכה זו? ומשיבים: \u0003תרתי שמעית מינה\u0004 \u0005[שני\u0006 דברים \u0005שומע,\u0006 לומד \u0005אתה ממנו\u0006 מאותו ביטוי\u0005]:\u0006 \u0003\"הם\"\u0004 — \u0003ולא שינויהם, \"הם\" —\u0004 \u0003ולא ולדותיהם.\u0004 ושואלים: \u0003ובית הלל, הכתיב\u0004 \u0005[הלא נאמר]\u0006 בפסוק \u0003\"גם\"\u0004 שהוא לשון ריבוי! ואומרים: אכן, \u0003\"גם\" לבית הלל קשיא\u0004 \u0005[קשה].\u0006","ומעירים: מכל מקום \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי\u0004 \u0005[נחלקו]\u0006 חכמים בברייתא \u0003אלא דמר סבר\u0004 \u0005[שחכם זה סבור]:\u0006 \u0003שינוי קונה, ומר סבר\u0004 \u0005[וחכם זה סבור]:\u0006 \u0003אין שינוי קונה, אבל לענין שלומי\u0004 \u0005[תשלומים]\u0006 \u0003כולי עלמא כדמעיקרא\u0004 \u0005[לדעת הכל כמו\u0006 שהיה הדבר הגנוב שווה \u0005מתחילה]\u0006 \u0003משלם, דקתני\u0004 \u0005[ש\u0006הרי \u0005שנה]\u0006 באותה ברייתא שהובאה מקודם: \u0003משלם תשלומי כפל ותשלומי ארבעה וחמשה כעין שגנב.\u0004","אם כן \u0003לימא תיהוי תיובתא\u0004 \u0005[האם נאמר\u0006 ש\u0005תהא זו קושיה חמורה על\u0006 דעתו\u0005]\u0006 של \u0003רב,\u0004 ש\u0003אמר רב: קרן\u0004 — \u0003כעין שגנב משלם,\u0004 ואילו \u0003תשלומי כפל ותשלומי ארבעה וחמשה\u0004 — \u0003כשעת העמדה בדין?\u0004 \u0003אמר רבא\u0004 בפירוש הדברים: אם נשתנו \u0003טלאים\u0004 בגופם (שגדלו, או שמנו) — מחזיר \u0003כדמעיקרא\u0004 \u0005[כמו\u0006 ערך הגניבה \u0005מתחילה],\u0006 אם נשתנו \u0003דמים,\u0004 שנשתנה מחיר הדבר הגנוב במשך הזמן — משלם \u0003כ\u0004ערך \u0003של עכשיו.\u0004","\u0003אמר רבה:\u0004 דין זה ש\u0003שינוי קונה\u0004 — \u0003כתיבא ותנינא\u0004 \u0005[כתוב\u0006 בתורה \u0005ושנינו\u0006 אותו במשנה\u0005].\u0006 \u0003כתיבא\u0004 \u0005[כתוב]:\u0006 \u0003\"והשיב את הגזלה אשר גזל\"\u0004 (ויקרא ה, כג), ויש לשאול: \u0003מה תלמוד לומר\u0004 מה באו ללמדנו המילים, המיותרות לכאורה, \u0003\"אשר גזל\"?\u0004 ומשיבים: \u0003אם\u0004 החפץ נשאר \u0003כעין שגזל,\u0004 שלא נשתנה — \u0003יחזיר\u0004 אותו עצמו (\"את הגזילה\"), \u0003ואם לאו\u0004 \u0005[לא],\u0006 שנשתנה החפץ — \u0003דמים בעלמא\u0004 \u0005[בלבד]\u0006 \u0003בעי שלומי\u0004 \u0005[צריך לשלם]\u0006 ואינו צריך להחזיר את החפץ עצמו (\"אשר גזל\").","וכן \u0003תנינא\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003הגוזל עצים ועשאן כלים,\u0004 גזל \u0003צמר ועשאן בגדים\u0004 — \u0003משלם כשעת הגזילה,\u0004 ואינו מחזיר אותם כפי שהם עתה לאחר שהשתנו, בגדים או כלים.","\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 אפשר ללמוד זאת ממשנה אחרת, ששנינו: \u0003לא הספיק\u0004 הבעלים \u0003ליתנו,\u0004 את צמר ראשית הגז, \u0003לו,\u0004 לכהן, \u0003עד\u0004 (קודם) \u0003שצבעו\u0004 את הצמר — \u0003פטור,\u0004 שאין חיוב בנתינת ראשית הגז אלא על צמר כברייתו. \u0003אלמא\u0004 \u0005[מכאן]\u0006 מקור נוסף במשנה ש\u0003שינוי קונה.\u0004","וממשיך רבה ואומר: ואילו לגבי \u0003יאוש\u0004 בגניבה ובגזילה, כאשר לא עשה הגנב או הגזלן שינוי בחפץ, אבל התייאשו הבעלים ממנו, \u0003אמרי רבנן דניקני\u0004 \u0005[אמרו חכמים שיקנה]\u0006 בכך המחזיק את החפץ, \u0003מיהו לא ידעינן אי דאורייתא אי דרבנן\u0004 \u0005[ואולם אין אנו יודעים אם מן התורה\u0006 היא הלכה זו, \u0005אם\u0006 תקנה \u0005מדברי חכמים]\u0006 שיאוש קונה.","ורבה מסביר את צדדי הספק הזה: \u0003אי דאורייתא\u0004 \u0005[אם מן התורה]\u0006 היא הלכה זו, יש לכאורה ראיה לדבר, \u0003מידי דהוה\u0004 \u0005[כשם שהוא]\u0006 הדין ב\u0003מוצא אבידה, מוצא אבידה לאו\u0004 \u0005[האם לא]\u0006 \u0003כיון דמייאש מרה מינה מקמי דתיתי לידיה\u0004 \u0005[שמתייאש בעליה ממנה לפני שתגיע לידו]\u0006 של המוצא — \u0003קני ליה\u0004 \u0005[קונה אותה]\u0006 המוצא ביאוש זה, \u0003האי נמי\u0004 \u0005[זו\u0006 גניבה וכיוצא בה \u0005גם כן],\u0006 \u0003כיון דמייאש מרה קני ליה\u0004 \u0005[שמתייאש בעליה קונה אותה\u0006 הגנב ביאוש\u0005],\u0006 \u0003אלמא קני\u0004 \u0005[מכאן\u0006 שיאוש \u0005קונה].\u0006","\u0003או דלמא לא דמיא\u0004 \u0005[שמא אינה דומה]\u0006 גניבה \u0003לאבידה,\u0004 שכן אפשר לחלק ולומר \u0003אבידה הוא דכי אתאי לידיה\u0004 \u0005[שכאשר באה לידו] —\u0006 \u0003בהתירא אתיא לידיה\u0004 \u0005[בהיתר\u0006 הוא ש\u0005באה לידו]\u0006 ולכן גם יאוש קונה לו מן התורה, \u0003אבל האי\u0004 \u0005[זה]\u0006 הגנב \u0003כיון דבאיסורא אתאי לידיה\u0004 \u0005[שבאיסור באה לידו],\u0006 בגניבה או בגזילה, רק \u0003מדרבנן\u0004 \u0005[מדברי חכמים]\u0006 \u0003הוא\u0004 שיאוש קונה לו,","\u0003דאמור רבנן ניקני\u0004 \u0005[שאמרו חכמים שיקנה]\u0006 את החפץ ביאוש הבעלים \u0003מפני תקנת השבים,\u0004 כדי שלא להכביד על בעלי תשובה המבקשים להחזיר את מה שגנבו.","\u0003ורב יוסף\u0004 חלק בענין זה על רבה ו\u0003אמר:\u0004 \u0003יאוש אינו קונה\u0004 בגניבה וגזילה \u0003ואפילו מדרבנן\u0004 \u0005[מדברי חכמים],\u0006 וכל עוד לא עשה הגנב או הגזלן שינוי בחפץ, צריך הוא להחזיר את החפץ עצמו לבעליו.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב יוסף לרבה\u0004 על שיטתו שיאוש קונה בגניבה וגזילה, ממה ששנינו: \u0003גזל חמץ ועבר עליו הפסח,\u0004 וחמץ זה אסור עתה בהנאה ככל חמץ שעבר עליו הפסח, ואין לו עוד כל ערך —"],["\u0003אומר לו\u0004 הגזלן לבעל החמץ: \u0003\"הרי שלך לפניך\",\u0004 ומחזיר לו את החמץ עצמו, אף שכעת החמץ אסור בהנאה ואין לו ערך. \u0003והאי\u0004 \u0005[והרי]\u0006 הבעלים \u0003כיון דמטא עידן איסורא\u0004 \u0005[שמגיע זמן איסור\u0006 חמץ בערב פסח\u0005]\u0006 \u0003ודאי מייאש\u0004 \u0005[מתייאש]\u0006 הוא ממנו, \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003יאוש קנה\u0004 לגזלן, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אומר לו\u0004 הגזלן \u0003\"הרי שלך לפניך\"?\u0004 הלא \u0003דמי מעליא בעי שלומי ליה\u0004 \u0005[דמים מעולים,\u0006 שלמים, \u0005צריך לשלם לו],\u0006 שהרי גוף החמץ נקנה לגזלן עם היאוש!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003כי קאמינא אנא\u0004 \u0005[כאשר אומר אני]\u0006 שיאוש קונה, הרי זה כאשר \u0003זה\u0004 (הבעלים) \u0003מתייאש, וזה\u0004 (הגנב) \u0003רוצה לקנות.\u0004 ואולם \u0003האי\u0004 \u0005[זה]\u0006 המקרה שאנו דנים בו, חמץ, הוא שונה, שכן \u0003זה\u0004 (הבעלים) \u0003מתייאש,\u0004 \u0003ו\u0004אילו \u0003זה\u0004 (הגנב) \u0003אינו רוצה לקנות\u0004 בגלל איסור חמץ.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי לרבה:\u0004 על הכתוב בדין הקרבן \u0003\"קרבנו\"\u0004 (ויקרא א, ג) דרשו שיש בכך הדגשה: קרבנו שלו כשר להקרבה, \u0003ולא הגזול,\u0004 שהוא פסול לקרבן ואין המקריב יוצא בו. ומעתה נברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהגזלן מקדיש ומביא את הקרבן \u0003לפני יאוש\u0004 הבעלים, \u0003למה לי קרא\u0004 \u0005[מקרא]\u0006 לומר שאינו יוצא בקרבן גזול? הרי זה \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שהרי אפילו להקדישה אינו יכול כיון שאינה שלו!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן שהקדישה והקריבה \u0003לאחר יאוש,\u0004 ואם כן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003יאוש לא קני\u0004 \u0005[קונה],\u0006 ולכן אינו יכול להקדיש בהמה זו!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 לפי הבנתך\u0005],\u0006 \u0003הא דתניא\u0004 \u0005[זו ששנינו\u0006 בברייתא\u0005]:\u0006 נאמר בטומאת הזב: \u0003\"\u0004ב\u0003משכבו\"\u0004 (ויקרא טו, ה) ודרשו: משכבו שלו מטמא, \u0003ולא\u0004 משכב \u0003הגזול,\u0004 ונברר:","\u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003גזל עמרא ועבדיה\u0004 \u0005[צמר ועשה אותו]\u0006 \u0003משכב, מי איכא למאן דאמר\u0004 \u0005[האם יש מי שאומר]\u0006 כי \u0003שינוי מעשה לא קני\u0004 \u0005[קונה],\u0006 ומדוע לא ייטמא המשכב? \u0003אלא מאי אית\u0004 \u0005[מה יש]\u0006 \u0003לך למימר\u0004 \u0005[לומר]\u0006 שמדובר שם ש\u0003גזל משכב דחבריה\u0004 \u0005[של חבירו],\u0006 \u0003הכי נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר ש\u0003גזל קרבן דחבריה\u0004 \u0005[של חבירו],\u0006 שכבר הקדישו חבירו, ולכן אינו יוצא בו, שהרי הוא של הקדש ואינו שלו, ואין מכאן ראיה לענין יאוש.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי לרב יוסף\u0004 ממה ששנינו במשנה: \u0003עורות של בעל הבית\u0004 — \u0003מחשבה\u0004 שחשב להשתמש בהם כמות שהם בלא כל תוספת, \u0003מטמאתן,\u0004 הריהם נחשבים בכך ככלי גמור וראויים לקבל טומאה.","\u0003ו\u0004עורות \u0003של עבדן\u0004 (בעל מלאכה העוסק בעיבוד עורות ומוכרם לאחרים) — \u0003אין מחשבה\u0004 שלו להשתמש בעורות כפי שהם \u0003מטמאתן,\u0004 כיון שלא הוא המחליט בדבר אלא הקונים יחליטו מה רצונם לעשות בעור.","\u0003של גנב\u0004 — \u0003מחשבה\u0004 שלו להשתמש בעורות שגנב כמות שהם \u0003מטמאתן, של גזלן\u0004 — \u0003אין מחשבה\u0004 שלו \u0003מטמאתן.\u0004","\u0003ר' שמעון אמר: חילוף הדברים\u0004 בדינם של גנב וגזלן, עורות \u0003של גזלן\u0004 — \u0003מחשבה מטמאתן\u0004 שקנה אותם, \u0003ושל גנב\u0004 — \u0003אין מחשבה מטמאתן, לפי שלא נתייאשו הבעלים\u0004 מן הגניבה.","\u0003ו\u0004על כל פנים \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 מכך שאם היה יאוש בעלים היתה מחשבת הגנב מטמאתם, כי \u0003יאוש\u0004 בלבד \u0003קנה! אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף לאביי: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003כגון שקיצען\u0004 (חתך אותו) הגזלן ויישר את קצותיהו לשימושו, וכיון שיש כאן גם יאוש וגם שינוי מעשה מסויים — בוודאי הגזלן קונה אותם כך.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבה בר רב חנן:\u0004 כיצד יכול אתה לפרש שמדובר כאן בשינוי של מעשה? \u0003והלא עיצבא שנו כאן,\u0004 שכאן מדובר בחתיכת עור ישרה וחלקה שחשב להשתמש בה כמות שהיא, \u0003ועיצבא אין צריכה קיצוע\u0004 כדי לבוא לידי שימוש ולכן היא מקבלת טומאה כפי שהיא,","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 קודם לכן: \u0003כל מקום שאין\u0004 בו \u0003חסרון מלאכה\u0004 כדי להביאו לשימושו אלא הדבר יכול לשמש כמו שהוא — \u0003מחשבה מטמאתו\u0004 אם מחליט שהוא גמר מלאכתו, אם \u0003יש\u0004 בדבר \u0003חסרון מלאכה,\u0004 כלומר, שיש עוד צורך לעשות מלאכה בחפץ זה כדי להכשירו לשימושו — \u0003אין מחשבה מטמאתו\u0004 גם אם חשב להשתמש בו כמות שהוא, שהרי בדרך כלל אין משאירים את הדבר בצורה הגולמית הזו, \u0003חוץ מן העיצבא\u0004 שבה אף מחשבה מטמאת, שכן כל מה שעושים בה מלאכה נוספת אינו אלא ליופי בלבד, והיא עצמה כבר ראויה לשימושה, ובמקרה זה של עיצבא חילקה המשנה בין בעל הבית לעבדן וכו'!","\u0003אלא אמר רבא: האי מילתא קשי בה\u0004 \u0005[דבר זה הקשה בו]\u0006 \u0003רבה לרב יוסף עשרין ותרתין שנין\u0004 \u0005[עשרים ושתים שנה],\u0006 \u0003ולא איפרקה\u0004 \u0005[נפתרה]\u0006 הקושיה \u0003עד דיתיב\u0004 \u0005[שישב]\u0006 \u0003רב יוסף ברישא\u0004 \u0005[בראש]\u0006 הישיבה לאחר כל אותן שנים \u0003ופרקה\u0004 \u0005[ופתר אותה\u0006 בעיה\u0005]\u0006 באומרו כי \u0003שינוי השם,\u0004 כאשר משתנה שמו של החפץ, \u0003כשינוי מעשה דמי\u0004 \u0005[נחשב]\u0006 ונקנה החפץ למחזיק בו.","והסבר הדבר: הרי \u0003שינוי מעשה מאי טעמא\u0004 \u0005[מה טעם]\u0006 אין הגנב מחזיר את החפץ כמו שהוא כעת? כי \u0003התם מעיקרא\u0004 \u0005[שם,\u0006 בכלי שעושים מעץ, \u0005מתחילה]\u0006 היו אלה \u0003עצים,\u0004 ואילו \u0003השתא\u0004 \u0005[עכשיו]\u0006 הריהם \u0003כלים,\u0004 אף \u0003שינוי השם נמי\u0004 \u0005[גם כן],\u0006 \u0003מעיקרא קרו ליה \"משכא\"\u0004 \u0005[מתחילה קראו לו עור]\u0006 \u0003והשתא\u0004 \u0005[ועכשיו]\u0006 קוראים לו \u0003\"אברזין\"\u0004 (עור לכיסוי).","ומקשים: \u0003והרי מריש\u0004 (קורות לבנין) \u0003דאיכא\u0004 \u0005[שיש בו]\u0006 \u0003שינוי השם\u0004 על ידי עצם השימוש בו, \u0003דמעיקרא\u0004 \u0005[שמתחילה]\u0006 לפני שבנו אותו קוראים לו \u0003\"כשורא\"\u0004 \u0005[קורה]\u0006 \u0003והשתא\u0004 \u0005[ועכשיו]\u0006 קוראים לו \u0003\"טללא\"\u0004 \u0005[קירוי],\u0006 \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]\u0006 שעשו תקנה \u0003על המריש הגזול שבנאו\u0004 הגזלן \u0003בבירה\u0004 (בנין) \u0003שנוטל\u0004 הנגזל \u0003דמיו\u0004 של המריש, ואין מחייבים את הגזלן להחזיר את המריש עצמו \u0003מפני תקנת השבים\u0004 בתשובה, שאם יחייבוהו להחזיר את המריש עצמו, ואפילו אם לשם כך יצטרך להרוס את כל הבנין, יכול הדבר לגרום שלא יעשו הגזלנים תשובה, ולכן תיקנו חכמים שישלם לו את הדמים, ולא את המריש עצמו.","ומכאן נדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 \u0003מפני תקנת השבים,\u0004"],["\u0003הא לאו הכי\u0004 \u0005[אבל\u0006 אם \u0005לא\u0006 היה \u0005כך]\u0006 — \u0003הדר בעיניה\u0004 \u0005[\u0006היה \u0005חוזר בעינו,\u0006 כפי שהוא\u0005]\u0006 אף שנעשה בו שינוי השם! \u0003אמר רב יוסף:\u0004 אין זה שינוי השם כאן משום ש\u0003מריש שמו עליו\u0004 גם לאחר שניתן בבנין. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 על הכתוב בתיאור בית המקדש: \"וצלעות הבית והעובים\" (יחזקאל מא, כו) ופירשו: \u0003\"צלעות הבית\"\u0004 — \u0003אלו המלטטין\u0004 (הנסרים שנותנים סביב החלונות), \u0003\"והעבים\" —\u0004 \u0003אלו המרישות,\u0004 הקורות, משמע שהם נקראים מרישים גם אחרי שנותנו בבנין.","\u0003ר' זירא אמר\u0004 שיש להסביר בדרך אחרת: \u0003שינוי החוזר לברייתו,\u0004 שאין השינוי בו בלתי הפיך, אלא יכול להחזיר את הדבר לכמות שהיה קודם — \u0003בשינוי השם\u0004 בלבד \u0003לא הוי\u0004 \u0005[אינו]\u0006 \u0003שינוי.\u0004","ושואלים: \u0003ו\u0004כי \u0003שינוי השם\u0004 אפילו בדבר \u0003שאינו חוזר לברייתו, מי הוי\u0004 \u0005[האם הוא]\u0006 נחשב \u0003שינוי? והרי צינור\u0004 של עץ \u0003דמעיקרא\u0004 \u0005[שמתחילה]\u0006 לפני שעשו בו חקיקה וחלל קוראים לו \u0003\"קציצתא\"\u0004 \u0005[בול עץ],\u0006 \u0003והשתא\u0004 \u0005[עכשיו]\u0006 קוראים לו \u0003\"צינורא\"\u0004 \u0005[צינור],\u0006 ואם כן נשתנה שמו ואינו חוזר לברייתו, \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003צינור שחקקו,\u0004 שתחילה עשה בו חור \u0003ולבסוף קבעו\u0004 במקומו והשתמש בו להעברת מים, \u0003פוסל את המקוה\u0004 אם הזרים מים דרכו למקוה, לפי שמים שאובים פוסלים את המקוה, וכיון שהצינור היה כבר כעין כלי, הרי המים שבו נחשבים כמים שהיו בכלי (שאובים).","ואולם אם תחילה \u0003קבעו\u0004 את בול העץ בארץ \u0003ולבסוף חקקו\u0004 והשתמש בו להעברת מים — \u0003אינו פוסל את המקוה,\u0004 שמתחילתו אין זה כלי אלא כחלק מן הקרקע.","\u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003שינוי השם מילתא היא\u0004 \u0005[דבר\u0006 חשוב \u0005הוא],\u0006 אם כן \u0003אפילו קבעו ולבסוף חקקו נמי ליפסל\u0004 \u0005[גם כן ייפסל],\u0006 שהרי על ידי חקיקה משתנה שמו ונקרא \"צינור\", ונמצא כעושה כלי חדש, וצריך היה להיפסל!","ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 דין \u0003שאיבה, דמדרבנן\u0004 \u0005[שמדברי סופרים]\u0006 \u0003היא\u0004 הלכה זו שמים שאובים פוסלים את המקוה, ולכן לא החמירו בו עד כדי כך. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמקילים בפסול זה של שאובים לפי שהוא מדברי סופרים \u0003אפילו דרישא\u0004 \u0005[\u0006במקרה \u0005הראשון]\u0006 שחקקו ובסוף קבעו \u0003נמי\u0004 \u0005[גם כן]\u0006 יהא כשר המקוה! ומשיבים: יש לחלק, \u0003התם\u0004 \u0005[שם]\u0006 בחקקו תחילה \u0003איכא\u0004 \u0005[יש]\u0006 \u0003תורת כלי עליו\u0004 כבר \u0003ב\u0004היותו \u0003תלוש, הכא\u0004 \u0005[כאן]\u0006 כשקבעו קודם \u0003אין תורת כלי עליו בתלוש,\u0004 ולכן אמרו חכמים שלא חל עליו שם כלי ממש.","ועוד, \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי רב יוסף, ממה ששנינו: \u0003הגנב, והגזלן, והאנס\u0004 (מי שכופה אנשים למכור לו דברים השייכים להם) — \u0003הקדישן\u0004 שהקדישו את הדברים הללו \u0003הקדש, ותרומתן תרומה, ומעשרותן מעשר.\u0004 משמע שביאוש לבד קונה!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: אף \u0003התם\u0004 \u0005[שם]\u0006 \u0003איכא\u0004 \u0005[יש]\u0006 \u0003שינוי השם,\u0004 \u0003דמעיקרא\u0004 \u0005[שמתחילה]\u0006 קוראים לכך \u0003\"טיבלא\"\u0004 \u0005[טבל]\u0006 \u0003והשתא\u0004 \u0005[ועכשיו]\u0006 קוראים לו \u0003\"תרומה\",\u0004 וכן ב\u0003הקדש, מעיקרא\u0004 \u0005[מתחילה]\u0006 היה זה קרוי \u0003\"חולין\", והשתא\u0004 \u0005[ועכשיו]\u0006 \u0003\"הקדש\".\u0004","\u0003אמר רב חסדא אמר ר' יונתן: מניין לשנוי שהוא קונה\u0004 בגזילה — \u0003שנאמר:\u0004 \u0003\"והשיב את הגזלה\"\u0004 (ויקרא ה, כג), ודי במילים אלה, \u0003מה תלמוד לומר,\u0004 מה באות ללמדנו המילים הנוספות \u0003\"אשר גזל\"\u0004 (ויקרא ה, כג)? — לומר: \u0003אם\u0004 החפץ הוא עדיין \u0003כעין שגזל,\u0004 כלומר, שלא היה בו שינוי — \u0003יחזיר\u0004 אותו עצמו, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003דמים בעלמא בעי שלומי\u0004 \u0005[כסף בלבד צריך לשלם],\u0006 ואינו חייב להחזיר את החפץ עצמו שכבר נקנה לו.","ושואלים: והרי \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"אשר גזל\" מיבעי\u0004 \u0005[צריך]\u0006 לנו \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003גזל אביו,\u0004 ללמדנו \u0003ש\u0004הבן \u0003אינו מוסיף חומש על\u0004 הקרן כאשר מחזיר דבר שהוא \u0003גזל אביו,\u0004 כלומר, שגזל חפץ מאביו ונשבע עליו לשקר!","ומשיבים: \u0003אם כן\u0004 שרק לצורך זה בא הכתוב, \u0003ניכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003\"והשיב את גזילו\"\u0004 ונלמד שרק על גזילו שלו חייב, אולם \u0003\"אשר גזל\" למה לי למכתב\u0004 \u0005[לכתוב]?\u0006 \u0003שמע מינה תרתי\u0004 \u0005[למד מכאן שני\u0006 דברים\u0005],\u0006 הן לענין גזל אביו, והן לענין שינוי קונה.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 סוגיה זו בלשון אחרת, הפוכה. \u0003אמר רב חסדא אמר ר' יונתן: מניין לשנויי שאינו קונה\u0004 בגזלן — \u0003שנאמר: \"והשיב את הגזילה\"\u0004 — \u0003מכל מקום,\u0004 שאף שנשתנתה, מחזיר אותה עצמה. ומקשים: \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"אשר גזל\"!\u0004 ומשיבים: \u0003ההוא מיבעי ליה\u0004 \u0005[אותו\u0006 כתוב \u0005נצרך לו]\u0006 לענין אחר, שאמרו: \u0003על גזילו שלו מוסיף חומש, ואין מוסיף חומש על גזל אביו.\u0004","ועוד באותו נושא \u0003אמר עולא: מניין ליאוש\u0004 בלבד \u0003שאינו קונה\u0004 — \u0003שנאמר\u0004 במביאי קרבנות לא ראויים: \u0003\"והבאתם גזול\u0004 ו\u0003את הפסח ואת החולה\u0004 והבאתם את המנחה הארצה אותה מידכם\" (מלאכי א, יג), מלשון הכתוב נלמד ששווים הם בדינם: \u0003גזול\u0004 שלא ניתן להביאו כקרבן, הרי זה \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003פסח, מה פסח\u0004 הריהו פסול \u0003דלית ליה תקנתא\u0004 \u0005[שאין לו תקנה]\u0006 \u0003כלל,\u0004 שהוא בעל מום תמידי,"],["\u0003אף גזול\u0004 הרי זה פסול \u0003דלית ליה תקנתא\u0004 \u0005[שאין לו תקנה]\u0006 ואסור לעולם, \u0003לא שנא\u0004 \u0005[שונה]\u0006 \u0003לפני יאוש ולא שנא\u0004 \u0005[שונה]\u0006 \u0003אחר יאוש.\u0004 משמע שאין היאוש עושה קנין.","\u0003רבא אמר:\u0004 דין זה נלמד \u0003מהכא\u0004 \u0005[מכאן]\u0006 שאת הכתוב \u0003\"קרבנו\"\u0004 (ויקרא א, ג), דרשו: \u0003ולא הגזול.\u0004 ונברר \u0003אימת\u0004 \u0005[מתי]\u0006 מדובר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהביאו לקרבן \u0003לפני יאוש\u0004 — \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 \u0003למה לי קרא\u0004 \u0005[מקרא]\u0006 לזה? הלא אין הבהמה שלו ואינו יכול להקדישה!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003לאחר יאוש, ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי \u0003יאוש לא קני\u0004 \u0005[קונה].\u0006 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבא\u0004 עצמו \u0003הוא\u0004 ש\u0003אמר\u0004 שיש להסביר ברייתא זו שמדובר בה ש\u0003גזל קרבן דחבריה\u0004 \u0005[של חבירו]\u0006 שחבירו הקדישו כבר לקרבן, אבל אם הגזלן הקדישו לאחר יאוש — כשר! ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003הדר ביה\u0004 \u0005[\u0006ש\u0005חזר בו\u0006 רבא\u0005]\u0006 והולך בשיטה אחרת. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003חד מינייהו\u0004 \u0005[\u0006ש\u0005אחת מהן],\u0006 מן השמועות הסותרות הללו, \u0003רב פפא אמרה\u0004 ולא רבא, וכיון שהיה תלמיד מובהק לרבא ייחסו את הדבר לרבא עצמו.","לאחר בירור כמה גופי הלכה, חוזרים אנו לפירושה של המשנה. שנינו: \u0003ומדת תשלומי ארבעה וחמשה\u0004 אינה נוהגת אלא בשור ושה בלבד.","ושואלים: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 נאמר כך? \u0003נילף\u0004 \u0005[נלמד]\u0006 בגזירה שווה \u0003\"שור\" \"שור\" מ\u0004מה שנאמר בדיני \u0003שבת, מה להלן\u0004 בדיני שבת \"שור\" האמור בתורה (\"ויום השבת... לא תעשה כל מלאכה... ושורך וחמורך וכל בהמתך...\". דברים ה, יד) הרי זה לאו דווקא, אלא כל \u0003חיה ועוף כיוצא בהן, אף כאן\u0004 בדין טביחה ומכירה נאמר ששאר \u0003חיה ועוף כיוצא בהן\u0004 ואף עליהם ישלם הטובח והמוכר ארבעה וחמישה!","\u0003אמר רבא: אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין תשלומי ארבעה וחמישה: \u0003\"שור ו\"שה\" \"שור ו\"שה\" שני פעמים\u0004 (\"כי יגנוב איש שור או שה וטבחו או מכרו, חמשה בקר ישלם תחת השור וארבע צאן תחת השה\". שמות כא, לז), ובא הדבר להדגשה למעט: \u0003שור ושה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003מידי אחרינא\u0004 \u0005[דבר אחר] —\u0006 \u0003לא.\u0004","בבירור דבר זה \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003הי מייתר\u0004 \u0005[איזה\u0006 משני הכתובים \u0005מיותר]\u0006 ובא רק ללמדנו הלכה זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003שור ושה דסיפא\u0004 \u0005[ש\u0006כתוב \u0005בסוף]\u0006 הוא \u0003מייתר\u0004 \u0005[\u0006ה\u0005מיותר],\u0006 \u0003דניכתוב רחמנא\u0004 \u0005[ש\u0006יכולה היתה \u0005התורה לכתוב]\u0006 כך בלי להזכיר שור ושה פעם נוספת: \u0003\"כי יגנב שור או שה\u0004\u0003וטבחו ומכרו חמשה בקר ישלם תחתיו וארבע צאן תחתיו\",\u0004 על כך יש להשיב: \u0003אי כתב רחמנא הכי\u0004 \u0005[אילו\u0006 היתה \u0005כותבת התורה כך],\u0006 \u0003הוה אמינא בעי שלומי\u0004 \u0005[הייתי אומר\u0006 ש\u0005צריך לשלם]\u0006 \u0003תשעה,\u0004 חמישה בקר וארבעה צאן, \u0003לכל אחד ואחד.\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 גם בנוסח זה של הכתוב לא הייתי אומר כך, שכן \u0003הא כתיב\u0004 \u0005[\u0006\u0005הרי נאמר]\u0006 בו \u0003\"תחתיו\" \"תחתיו\"\u0004 שתי פעמים, ואם כן \u0003חד\u0004 \u0005[\u0006פעם \u0005אחת]\u0006 \u0003\"תחתיו\" מייתר\u0004 \u0005[מיותר]\u0006 ובא לומר שמשלם תחת כל אחד מן הדברים הגנובים תשלום נפרד.","ואולם \u0003ההוא מיבעי ליה\u0004 \u0005[צריך אותו\u0006 \"תחתיו\"\u0005]\u0006 \u0003לדרשה אחרינא\u0004 \u0005[אחרת],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יכול גנב שור שוה מנה ישלם תחתיו נגידין\u0004 (שוורים כחושים וגרועים)? \u0003תלמוד לומר: \"תחתיו\" \"תחתיו\"\u0004 (\"תחת השור... תחת השה\"), לומר: השור שמשלם תחתיו יהיה שווה כמו השור שגנב. נמצא ש\"שור\" ו\"שה\" שבסוף הפסוק אינו מיותר!","\u0003אלא\u0004 תאמר כי \u0003\"שור\" ו\"שה\" דרישא\u0004 \u0005[ש\u0006כתוב \u0005בתחילה]\u0006 הוא ה\u0003מיותר, דנכתוב רחמנא\u0004 \u0005[ש\u0006יכולה היתה \u0005התורה לכתוב]\u0006 כך: \u0003\"כי יגנב איש וטבחו ומכרו חמשה בקר ישלם תחת השור וארבע צאן תחת השה\".\u0004","על כך יש להשיב: \u0003אי כתב רחמנא הכי\u0004 \u0005[אילו\u0006 היתה \u0005כותבת התורה כך]\u0006 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 אינו חייב בארבעה וחמישה \u0003עד דגניב תרי וטבח להו\u0004 \u0005[שגונב שניים\u0006 גם שור וגם שה\u0005וטובח אותם]\u0006 ולא יתחייב על אחד מהם בלבד, לכן מחלק הפסוק בתחילתו בין שור לשה, ואין כתוב זה מיותר! ומשיבים: ללימוד זה אין צורך לכתוב \"שור ו\"שה\" שהרי \u0003\"וטבחו\" כתיב\u0004 \u0005[נאמר]\u0006 בלשון יחיד, ומלשון זו למדים \u0003לחד\u0004 \u0005[לאחד]\u0006 בלבד.","ומקשים: ועדיין יש לומר שאין כתוב זה מיותר, \u0003ואימא\u0004 \u0005[ואמור]\u0006 כך: אילו לא היה כתוב \"שור או שה\" בתחילה, סבורים היינו כי אינו משלם ארבעה וחמישה \u0003עד דגניב תרוייהו ומזבין להו\u0004 \u0005[שגונב\u0006 את \u0005שניהם ומוכר אותם]\u0006 ולא אחד בלבד! ומשיבים: לא היינו אומרים כן, שהרי \u0003\"ומכרו\" כתיב\u0004 \u0005[נאמר]\u0006 בלשון יחיד, \u0003לחד\u0004 \u0005[לאחד]\u0006 בלבד.","ומציעים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 אם לא היה כתוב \"שור ו\"שה\" בתחילת הפסוק \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שאינו חייב ארבעה וחמישה \u0003עד דגניב תרי, וטבח חד ומזבין חד\u0004 \u0005[שגונב שניים\u0006 יחד \u0005וטובח אחד ומוכר אחד]!\u0006 ומשיבים: \u0003\"או מכרו\" כתיב\u0004 \u0005[נאמר],\u0006 משמע שחייב על טביחה או על מכירה.","ומקשים: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 אם לא היה כתוב \"שור\" ו\"שה\" \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 אינו חייב ארבעה וחמישה \u0003עד דגניב תרוייהו וטבח חד ומשייר חד\u0004 \u0005[שגונב שניהם וטובח אחד ומשייר אחד],\u0006 \u0003או מזבין חד\u0004 \u0005[מוכר אחד]\u0006 \u0003ומשייר חד\u0004 \u0005[אחד]!\u0006 ונמצא איפוא שגם \"שור או שה\" שבתחילת הפסוק אינו מיותר.","\u0003אלא\u0004 כך יש לומר: \u0003\"שור\" דסיפא\u0004 \u0005[ש\u0006כתוב \u0005בסוף]\u0006 \u0003ו\"שה\" דרישא מייתר\u0004 \u0005[ש\u0006כתוב \u0005בתחילה מיותר],\u0006 \u0003דניכתוב רחמנא\u0004 \u0005[ש\u0006יכולה היתה \u0005התורה לכתוב]:\u0006 \u0003\"כי יגנב איש שור וטבחו ומכרו חמשה בקר ישלם תחתיו וארבע צאן תחת השה\",\u0004 אם כן \u0003\"שור\" דסיפא\u0004 \u0005[שבסוף]\u0006 \u0003ו\"שה\" דרישא\u0004 \u0005[שבתחילה]\u0006 \u0003למה לי? שמע מינה\u0004 \u0005[למד מכאן]\u0006 מכפל זה כי דווקא \u0003שור ושה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 חייב בארבעה וחמישה, \u0003מידי אחרינא\u0004 \u0005[דבר אחר] —\u0006 \u0003לא\u0004 חייב.","שנינו במשנה כי \u0003אין הגונב אחר הגנב משלם תשלומי כפל. אמר רב: לא שנו\u0004 הלכה זו \u0003אלא\u0004 שגנב את החפץ מן הגנב \u0003לפני יאוש\u0004 בעלים הראשונים, \u0003אבל\u0004 אם גנבו \u0003לאחר יאוש\u0004 — כבר \u0003קנאו גנב ראשון\u0004 ונעשה גוף החפץ שייך לו, \u0003וגנב שני משלם תשלומי כפל לגנב ראשון\u0004 כאילו היה בעליו מתחילה.","\u0003אמר רב ששת: אמינא כי ניים ושכיב\u0004 \u0005[אומר אני\u0006 ש\u0005כאשר נמנם ושכב]\u0006 \u0003רב אמר להא שמעתא\u0004 \u0005[את\u0006 \u0005ההלכה הזו],\u0006 כלומר, שאין ההלכה מבוססת כראוי. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אמר ר' עקיבא: מפני מה אמרה תורה טבח ומכר משלם תשלומי ארבעה וחמשה?\u0004 — \u0003מפני שנשתרש\u0004 (היכה שורשים, נתחזק) \u0003בחטא\u0004 על ידי מעשה עבירה כפול זה של גניבה וטביחה או מכירה. ומעתה נברר: \u0003אימת\u0004 \u0005[מתי]\u0006 היתה הטביחה או המכירה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003לפני יאוש\u0004 הבעלים,"],["\u0003מי איכא\u0004 \u0005[האם יש]\u0006 בזה ענין של \u0003נשתרש\u0004 בחטא? והרי עדיין אין הדבר הגנוב נחשב כשלו, ואין תוקף למכירה! \u0003אלא\u0004 ודאי מדובר \u0003לאחר יאוש, ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 כי \u0003יאוש קני\u0004 \u0005[קונה],\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003משלם תשלומי ארבעה וחמשה?\u0004 הלא את \u0003שלו הוא טובח, שלו הוא מוכר!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחיה להוכחה זו: יש להסביר \"נשתרש בחטא\" באופן שונה, \u0003כדאמר\u0004 \u0005[כמו שאמר]\u0006 \u0003רבא\u0004 להלן בפירוש דברי ר' עקיבא: \u0003מפני ששנה בחטא,\u0004 כלומר, שחטא וחזר וחטא, שגנב ואחר כך מכר את החפץ הגנוב, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש לומר שנענש \u0003מפני ששנה בחטא,\u0004 ולא משום שהחפץ שייך לו והועילה המכירה, ולכן יש אפשרות להבין את הדברים לפני יאוש, ואין מכאן הוכחה כנגד רב.","ומציעים הוכחה אחרת: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנו בברייתא על הכתוב \u0003\"וטבחו או מכרו\"\u0004 (שמות כא, לז): \u0003מה טביחה\u0004 שמחייבים עליה תשלומי ארבעה וחמישה, היא פעולה \u0003שאינה חוזרת, אף מכירה\u0004 שמתחייב עליה היא כזו \u0003שאינה חוזרת.\u0004","ונברר \u0003אימת\u0004 \u0005[מתי]\u0006 היתה מכירה זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003לפני יאוש\u0004 הבעלים, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אינה חוזרת?\u0004 הלא מתברר שמכר דבר שלא היה שייך לו, והמכר בטל! \u0003אלא\u0004 ודאי מדובר \u0003לאחר יאוש, ואי סלקא דעתך קנייה\u0004 \u0005[ואם עולה על דעתך\u0006 לומר שהגנב \u0005קנאו],\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003משלם ארבעה וחמשה?\u0004 הלא את \u0003שלו הוא טובח, שלו הוא מוכר!\u0004","ומשיבים: \u0003כדאמר\u0004 \u0005[כמו שאמר]\u0006 \u0003רב נחמן\u0004 בפירוש ברייתא זו, שמכירה שאינה חוזרת פירושה \u0003פרט לשהקנה\u0004 הגנב במכירתו את הדבר רק \u0003לשלשים יום\u0004 בלבד, ולא לצמיתות. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש להבין באותו אופן \u0003פרט לשהקנה לשלשים יום.\u0004 אבל אם מכר לצמיתות, אף שהיה זה לפני יאוש — דין התורה שמשלם ארבעה וחמישה, ואין להוכיח מכאן שיאוש אינו קונה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 עוד מברייתא: \u0003גנב\u0004 חפץ \u0003ובא אחר וגנבו\u0004 ממנו — הגנב \u0003הראשון משלם\u0004 לבעלים \u0003תשלומי כפל,\u0004 \u0003ו\u0004הגנב \u0003השני אינו משלם\u0004 לראשון \u0003אלא קרן בלבד.\u0004","\u0003גנב ומכר ובא אחר וגנבו\u0004 מן הקונה — \u0003הראשון משלם\u0004 לבעלים \u0003תשלומי ארבעה וחמשה, והשני משלם\u0004 לקונה שממנו גנב \u0003תשלומי כפל.\u0004 \u0003גנב וטבח ובא אחר וגנבו\u0004 — \u0003הראשון משלם תשלומי ארבעה וחמשה,\u0004 \u0003ו\u0004הגנב \u0003השני אינו משלם\u0004 לגנב הראשון \u0003תשלומי כפל אלא קרן בלבד.\u0004","\u0003קתני מיהא מציעתא\u0004 \u0005[שנה על כל פנים\u0006 בקטע \u0005האמצעי]:\u0006 \u0003גנב ומכר, ובא אחר וגנבו\u0004 — \u0003הראשון משלם תשלומי ארבעה וחמשה, והשני משלם תשלומי כפל.\u0004","ונברר \u0003אימת\u0004 \u0005[מתי]\u0006 היתה המכירה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003לפני יאוש,\u0004 גנב \u0003שני אמאי\u0004 \u0005[מדוע]\u0006 \u0003משלם תשלומי כפל\u0004 לקונה מן הגנב? והרי היה כאן \u0003שינוי רשות בלא יאוש\u0004 הבעלים הראשונים ובמקרה שכזה \u0003מי איכא למאן דאמר דקני\u0004 \u0005[האם יש מי שאומר ש\u0006הוא \u0005קונה]\u0006 בכך, ואין הקונה נחשב כבעליו של הדבר, ובמקרה שכזה פטור הגנב ממנו מתשלומי כפל?","\u0003אלא פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר כאן \u0003לאחר יאוש. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003יאוש קונה, אמאי\u0004 \u0005[מדוע]\u0006 \u0003משלם\u0004 הגנב הראשון \u0003תשלומי ארבעה וחמשה?\u0004 הלא \u0003דידיה\u0004 \u0005[\u0006את \u0005שלו]\u0006 \u0003הוא דזבין\u0004 \u0005[שמכר]!\u0006","\u0003ותו, דקתני רישא\u0004 \u0005[ועוד, ששנה\u0006 שם בקטע ה\u0005ראשון]:\u0006 \u0003גנב, ובא אחר וגנבו\u0004 ממנו — \u0003ראשון משלם תשלומי כפל, והשני אין משלם\u0004 לגנב הראשון \u0003אלא קרן.\u0004","\u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003לאחר יאוש קיימינן\u0004 \u0005[עומדים,\u0006 עוסקים, \u0005אנו],\u0006 \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 ש\u0003יאוש קונה,\u0004 גנב \u0003שני אמאי\u0004 \u0005[מדוע]\u0006 \u0003אינו משלם אלא קרן,\u0004 היה לו לשלם גם כפל לגנב? \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003יאוש לא קני\u0004 \u0005[קונה],\u0006 \u0003וקשיא\u0004 \u0005[וקשה\u0006 הדבר\u0005]\u0006 \u0003לרב!\u0004","\u0003אמר רבא: ותסברא\u0004 \u0005[וכי סבור אתה]\u0006 כי \u0003הא מתרצתא\u0004 \u0005[\u0006שהברייתא \u0005הזו מתורצת,\u0006 מיושבת\u0005]\u0006 \u0003היא\u0004 ואפשר להקשות ממנה? \u0003אלא\u0004 זה \u0003דקתני סיפא\u0004 \u0005[\u0006מה \u0005ששנה\u0006 ב\u0005סופה\u0006 בקטע האחרון שבה\u0005]:\u0006 \u0003גנב וטבח ובא אחר וגנבו\u0004 ממנו — \u0003ראשון משלם תשלומי ארבעה וחמשה, ושני אינו משלם אלא קרן, ומי איכא למאן דאמר\u0004 \u0005[והאם יש מי שאומר]\u0006 כי \u0003שינוי מעשה לא קני\u0004 \u0005[קונה]?\u0006 והרי לכל הדעות לאחר טביחה גוף הבהמה שייך לגנב, ואם כן הגונב ממנו יצטרך לשלם כפל!","\u0003אלא לעולם\u0004 יש לפרש שברייתא זו \u0003כולה\u0004 מדברת \u0003לפני יאוש, ואיפוך סיפא למציעתא ומציעתא לסיפא\u0004 \u0005[והפוך\u0006 ושנה את \u0005ה\u0006דין שב\u0005סוף ל\u0006דין \u0005האמצעי ו\u0006את \u0005ה\u0006דין \u0005האמצעי ל\u0006דין שב\u0005סוף]\u0006 שנתחלפו בברייתא ההלכות, \u0003ואימא הכי\u0004 \u0005[ואמור כך]\u0006 שזו גרסתה המתוקנת של הברייתא: \u0003גנב ומכר ובא אחר וגנבו\u0004 — \u0003הראשון משלם תשלומי ארבעה וחמשה\u0004 לבעלים, \u0003והשני אינו משלם\u0004 לראשון \u0003אלא קרן,\u0004 וטעמו של דבר — משום ש\u0003שינוי רשות בלא יאוש לא קני\u0004 \u0005[קונה]\u0006 ונמצא שלא גנב השני מן הגנב הראשון דבר שהוא בעליו.","\u0003גנב וטבח ובא אחר וגנבו\u0004 — \u0003הראשון משלם תשלומי ארבעה וחמשה, והשני משלם תשלומי כפל\u0004 לגנב הראשון, משום \u0003דקנייה\u0004 \u0005[שקנה\u0006 הגנב \u0005אותה,\u0006 את הבהמה\u0005]\u0006 \u0003בשינוי מעשה\u0004 שטבחה.","ואילו \u0003רב פפא אמר: לעולם לא תיפוך\u0004 \u0005[תהפוך],\u0006 שאין אתה צריך לכך, ואפשר לומר כי \u0003סיפא\u0004 \u0005[\u0006הקטע שב\u0005סוף\u0006 הברייתא\u0005]\u0006 שאם טבח אין הגונב ממנו משלם כפל — כשיטת \u0003בית שמאי היא, דאמרי\u0004 \u0005[שאומרים]:\u0006 \u0003שינוי במקומה עומד,\u0004 כלומר, אין השינוי עצמו יוצר קנין.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שאין אנו הופכים את הברייתא ואין מפרשים אותה לפני יאוש אלא לאחר יאוש \u0003קשיא רישא ומציעתא\u0004 \u0005[קשה הראש והאמצע\u0006 של הברייתא\u0005],\u0006 \u0003לרב\u0004 שאם מדובר במקרה שלאחר יאוש הבעלים, ויאוש קונה כדברי רב, הרי בדין הראשון (גנב ונגנב ממנו) היה צריך הגנב השני לשלם כפל, ובדין האמצעי (גנב ומכר) לא היה הגנב מתחייב ארבעה על המכירה כי שלו הוא מוכר!","ועוד הסבר בברייתא \u0003אמר רב זביד: לעולם\u0004 תפרש כך: הברייתא \u0003כולה\u0004 מדברת \u0003לפני יאוש, והכא במאי עסקינן\u0004 \u0005[וכאן,\u0006 בדין האמצעי — שגנב ומכרו, \u0005במה אנו עוסקים]\u0006 \u0003שנתייאשו הבעלים\u0004 רק \u0003ב\u0004זמן שהגיע ליד ה\u0003לוקח\u0004 (קונה), \u0003ולא נתייאשו\u0004 עדיין \u0003ב\u0004זמן שהיה ביד ה\u0003גנב, דהוה ליה\u0004 \u0005[שהריהו]\u0006 אצל הקונה יש \u0003יאוש ושינוי רשות.\u0004","\u0003ו\u0004אולם \u0003לא תימא\u0004 \u0005[תאמר]\u0006 שמתחייב הגנב השני כפל \u0003משום דבעינן\u0004 \u0005[שצריכים אנו]\u0006 תמיד \u0003יאוש ושינוי רשות,\u0004 ולכן לא מדובר בברייתא בחיוב כפל במקרה שגונב מן הגנב עצמו, אלא מן הקונה. \u0003אלא אפילו ביאוש לחודיה\u0004 \u0005[לבדו]\u0006 \u0003נמי קני גבי\u0004 \u0005[גם כן קנוי אצל]\u0006 \u0003גנב,\u0004 ואף אם היה נגנב ממנו, היה משלם הגנב השני כפל,","\u0003אלא דלא משכחת דמשלמי תרוייהו\u0004 \u0005[שאין אתה מוצא\u0006 אפשרות \u0005שישלמו שניהם]\u0006 גם \u0003גנב ראשון\u0004 ארבעה וחמישה \u0003ו\u0004גם \u0003גנב שני\u0004 כפל \u0003אלא בהכי\u0004 \u0005[\u0006בכגון \u0005זה].\u0006 וכדי למצוא מקרה כעין זה צריך לפרש שמדובר ביאוש ושינוי רשות.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו האמוראים בבעיה זו: \u0003המוכר\u0004 את מה שגנב \u0003לפני יאוש\u0004 הבעלים, \u0003רב נחמן אמר: חייב\u0004 בתשלומי ארבעה וחמישה, \u0003רב ששת אמר: פטור.\u0004","ומסבירים את טעמיהם, \u0003רב נחמן אמר: חייב,\u0004 שכן \u0003\"ומכרו\"\u0004 (שמות כא, לז), \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 בדין ארבעה וחמישה \u0003והא זבין\u0004 \u0005[והרי מכר],\u0006 \u0003לא שנא\u0004 \u0005[שונה]\u0006 \u0003לפני יאוש לא שנא\u0004 \u0005[שונה]\u0006 \u0003לאחר יאוש. רב ששת אמר: פטור, חיוביה\u0004 \u0005[חיובו]\u0006 \u0003לאחר יאוש הוא,\u0004 כיון \u0003דאהנו\u0004 \u0005[שהועילו]\u0006 \u0003מעשיו,\u0004 שהרי המכירה חלה וקנאה הקונה, \u0003אבל לפני יאוש\u0004 ש\u0003לא אהנו\u0004 \u0005[הועילו]\u0006 \u0003מעשיו\u0004 — \u0003לא מיחייב\u0004 \u0005[מתחייב],\u0006 כי \u0003דומיא דטביחה בעינן, דאהנו\u0004 \u0005[בדומה לטביחה אנו צריכים\u0006 שתהיה גם המכירה באופן \u0005שהועילו]\u0006 \u0003מעשיו.\u0004","\u0003אמר רב ששת: מנא אמינא לה\u0004 \u0005[מניין אני אומר אותה],\u0006 את סברתי זו? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר'\u0004 \u0003עקיבא: מפני מה אמרה תורה טבח ומכר משלם ארבעה וחמשה?\u0004 — \u0003מפני שנשתרש\u0004 (נתחזק) \u0003בחטא.\u0004","ונברר: \u0003אימת\u0004 \u0005[מתי]\u0006 היה הדבר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003לפני יאוש, מי איכא\u0004 \u0005[האם יש]\u0006 בכך \u0003נשתרש?\u0004 הרי לא נתן תוקף (\"שורש\") למעשה שעשה! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003לאחר יאוש הוא! אמר רבא:\u0004 אין זו הוכחה, אלא יש לומר שהכוונה בפירוש \"נשתרש\" היא \u0003מפני ששנה בחטא,\u0004 שלא רק שחטא בכך שגנב, אלא הוסיף חטא אחר על כך למוכרו.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממקור אחר, ששנינו בברייתא: נאמר \u0003\"וטבחו\u0004 או \u0003מכרו\",\u0004 והוקשו הדברים לומר: \u0003מה טביחה שאינה חוזרת\u0004 — \u0003אף מכירה שאינה חוזרת.\u0004 ונברר: \u0003אימת\u0004 \u0005[מתי]\u0006 היה הדבר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003לפני יאוש, אמאי\u0004 \u0005[מדוע]\u0006 \u0003אינה חוזרת?\u0004 הלא מכר דבר שאינו שלו! \u0003אלא\u0004 מדובר \u0003לאחר יאוש, ושמע מינה חיובא\u0004 \u0005[ולמד מכאן\u0006 כי \u0005החיוב]\u0006 דווקא \u0003לאחר יאוש הוא\u0004 וכרב ששת! \u0003תרגמה\u0004 \u0005[הסביר אותה\u0006 את הברייתא\u0005]\u0006 \u0003רב נחמן:\u0004 אין הכוונה במכירה שאינה חוזרת מבחינת תוקף המכירה, אלא \u0003פרט לשהקנה לו לשלשים יום\u0004 בלבד שהרי זו מכירה החוזרת למוכרה, שצריך שמבחינתו של המוכר שימכרנה לעולם, אף אם מבחינת תוקפה אינה חלה, כגון שהיה זה לפני יאוש.","ומעירים: \u0003ואף ר'\u0004 \u0003אלעזר סבר\u0004 כרב ששת כי \u0003חיוביה\u0004 \u0005[חיובו]\u0006 של הגנב המוכר דווקא \u0003לאחר יאוש הוא,\u0004 ש\u0003אמר ר'\u0004 \u0003אלעזר:\u0004"],["\u0003תדע שסתם גניבה יאוש בעלים הוא\u0004 —","\u0003שהרי אמרה תורה\u0004 שכאשר \u0003טבח ומכר משלם תשלומי ארבעה וחמשה,\u0004 והרי יכול אתה לשאול על כך: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003לא אייאש\u0004 \u0005[התייאשו]\u0006 הבעלים? \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 שסבור ר' אלעזר \u0003דאמרינן\u0004 \u0005[שאומרים אנו]:\u0006 \u0003סתם גניבה יאוש בעלים היא.\u0004 ומכאן נלמד שלדברי ר' אלעזר רק לאחר יאוש חל החיוב בתשלומי ארבעה וחמישה.","ושואלים על עצם דיוקו של ר' אלעזר: \u0003ודלמא אף על גב\u0004 \u0005[ושמא אף על פי]\u0006 ש\u0003לא אייאש\u0004 \u0005[התייאשו]\u0006 הבעלים מכל מקום חייבתו התורה בארבעה וחמישה!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר דבר זה, כי מכירה שנאמרה בענין זה, הריהי צריכה להיות \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003טביחה,\u0004 שהרי נאמרו יחד (\"וטבחו או מכרו\"), ומעתה, \u0003מה טביחה\u0004 היא פעולה כזו \u0003דאהנו\u0004 \u0005[שהועילו]\u0006 \u0003מעשיו\u0004 — \u0003אף מכירה\u0004 צריכה להיות כזו \u0003דאהנו\u0004 \u0005[שהועילו]\u0006 \u0003מעשיו, ואי\u0004 \u0005[ואם]\u0006 המדובר \u0003לפני יאוש מאי אהנו\u0004 \u0005[מה הועילו]?\u0006","ומקשים עוד על דברי ר' אלעזר: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 מדובר כאן במקרה \u0003דשמעיניה דאייאש\u0004 \u0005[ששמענוהו\u0006 לבעלים \u0005שהתייאש]?\u0006 \u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר דבר זה, שכן מדובר כאן בגניבה \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003טביחה, מה טביחה\u0004 אפילו עשאה \u0003לאלתר\u0004 \u0005[מיד]\u0006 מתחייב, \u0003אף מכירה לאלתר\u0004 \u0005[מיד]\u0006 מתחייב עוד לפני שנודע שהבעלים התייאשו.","ולאחר דיון בדברי ר' אלעזר, מביאים מה ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן: גניבה בנפש\u0004 \u0003תוכיח,\u0004 שאמרה תורה שגונב אדם ומוכרו חייב מיתה, \u0003ש\u0004הרי שם ודאי \u0003אין יאוש בעלים,\u0004 שהרי אין שם \"בעלים\" שיתייאש, \u0003ו\u0004בכל זאת \u0003חייב\u0004 על מכירתו! ומעירים: \u0003מכלל\u0004 הדברים נלמד \u0003דסבר\u0004 \u0005[שסבור]\u0006 \u0003ר' יוחנן\u0004 שאם גנב וטבח \u0003לפני יאוש\u0004 הריהו \u0003חייב\u0004 ארבעה וחמישה.","ומבררים עוד: הגונב וטובח או מוכר \u0003לאחר יאוש מאי\u0004 \u0005[מה]\u0006 יהא הדין לענין תשלומי ארבעה וחמישה? \u0003ר' יוחנן אמר: חייב\u0004 גם אז, \u0003וריש לקיש אמר: פטור.\u0004","ומסבירים את השיטות: \u0003ר' יוחנן אמר\u0004 שהוא \u0003חייב,\u0004 שכן \u0003חיוביה\u0004 \u0005[חיובו]\u0006 של הטובח או מוכר הכתוב בתורה אין בו חילוק \u0003בין לפני יאוש בין לאחר יאוש. ריש לקיש אמר\u0004 שהוא \u0003פטור,\u0004 שלדעתו \u0003חיוביה\u0004 \u0005[חיובו]\u0006 של הגנב דווקא \u0003לפני יאוש הוא, אבל לאחר יאוש —\u0004 \u0003קנה\u0004 הגנב את גוף החפץ, \u0003ושלו הוא טובח ושלו הוא מוכר.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לריש לקיש\u0004 מברייתא זו: \u0003גנב והקדיש ואחר כך טבח\u0004 — \u0003משלם\u0004 על כך \u0003תשלומי כפל\u0004 לבעלים, \u0003ואינו משלם תשלומי ארבעה וחמשה,\u0004 לא לבעלים (שהרי בשעה שטבח היה זה של ההקדש) ולא להקדש שכיון שאין דין כפל בהקדש (שכתוב \"ישלם שנים לרעהו\" והקדש אינו בגדר \"רעהו\") אף אין בו דין ארבעה וחמישה.","ונברר: \u0003אימת\u0004 \u0005[מתי]\u0006 היה הדבר? \u0003אלימא\u0004 \u0005[אם תאמר]\u0006 \u0003לפני יאוש, מי\u0004 \u0005[האם]\u0006 נעשה החפץ \u0003קדוש?\u0004 והלא \u0003\"\u0004ו\u0003איש כי יקדש את ביתו קדש\"\u0004 (ויקרא כז, יד) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 ומכאן למדים: \u0003מה ביתו שלו\u0004 — \u0003אף כל\u0004 מה שהוא מקדיש צריך להיות \u0003שלו,\u0004 ואין הקדש חל על דבר שאינו שלו!","\u0003אלא פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שמדובר כאן \u0003לאחר יאוש, וטעמא\u0004 \u0005[והטעם,\u0006 דווקא\u0005]\u0006 ש\u0003הקדיש הוא\u0004 ש\u0003אינו משלם תשלומי ארבעה וחמשה,\u0004 משום \u0003דכי קא טבח\u0004 \u0005[שכאשר הוא טובח]\u0006 — של \u0003הקדש קא טבח\u0004 \u0005[הוא טובח],\u0006 \u0003אבל\u0004 אם \u0003לא הקדיש\u0004 — אם \u0003טבח משלם תשלומי ארבעה וחמשה. ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר שב\u0003יאוש קונה\u0004 הגנב, \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003משלם\u0004 תשלומי ארבעה וחמישה? הלא את \u0003שלו הוא טובח, שלו הוא מוכר!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש בתשובה: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שהקדישוהו\u0004 ה\u0003בעלים\u0004 עצמם, ולא הגנב, כאשר היתה הבהמה הגנובה \u0003ביד גנב,\u0004 ואם כן יש לפרש ברייתא זו לפני יאוש.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 נעשה \u0003קדוש\u0004 במקרה זה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: גזל\u0004 חפץ \u0003ולא נתייאשו\u0004 ממנו \u0003הבעלים\u0004 — \u0003שניהן,\u0004 הן הבעלים והן הגזלן, \u0003אינן יכולין להקדיש, זה\u0004 (הגזלן) \u0003לפי ש\u0004החפץ \u0003אינו שלו, וזה\u0004 (הבעלים) \u0003לפי שאינו ברשותו! אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003הוא\u0004 ריש לקיש ש\u0003אמר\u0004 הסבר זה בברייתא, היה זה \u0003כ\u0004שיטת ה\u0003צנועין\u0004 (יראי השמים והמדקדקים).","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 בענין כרם רבעי (בשנה הרביעית לנטיעתו) אסור לאכול ממנו חוץ לירושלים בלא פדיון, ויש לחשוש שמא יבואו אנשים לכרם ויקחו ממנו ענבים בלא רשות ויאכלום, ונמצאים נכשלים באיסור אכילת פרי רבעי שלא בירושלים, והיו בעלי הכרמים \u0003הצנועין מניחין את המעות\u0004 שעליהן יחללו את הפירות, \u0003ואומרים: כל\u0004 פרי \u0003הנלקט מזה,\u0004 מן הכרם, על ידי אנשים זרים \u0003יהא מחולל על המעות האלו.\u0004 ונמצא שהיו מחללים את פירות הכרם שנגנבו גם כאשר הם בשעת החילול ביד הגנבים. ומכאן שסבורים הצנועים שלמרות שאין הפירות עוד ברשותם — יכולים הם לחללם ולהעביר את קדושתם למעות, והוא הדין להקדש.","ומקשים על עיקר ההסבר הזה: אם כן, שמדובר בשהקדישוהו הבעלים, ויש ביכולתם לעשות זאת, \u0003הרי\u0004 זה כאילו \u0003חזרה קרן,\u0004 כלומר, הבהמה הגנובה \u0003לבעלים,\u0004 שהחפץ נמצא ברשות ההקדש לפי דעת הבעלים. ואם כן נמצא שעתה הוא לא גנב דבר, שהרי אין הגניבה נחשבת עוד כנמצאת בידו, ומדוע משלם הגנב כפל?","ומשיבים: מדובר כאן \u0003כשעמד בדין,\u0004 שעוד לפני שהקדישו הבעלים כבר תפסו את הגנב והעמידוהו בדין, וכבר נתחייב בתשלומי כפל.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי דאמרי\u0004 \u0005[אם שאמרו]\u0006 בית דין \u0003\"צא תן לו\", מאי איריא\u0004 \u0005[מה שייך,\u0006 למה דווקא\u0005]\u0006 אומרת הברייתא שאם \u0003הקדיש\u0004 (הבעלים) פטור הגנב מארבעה וחמישה, והרי \u0003אפילו לא הקדיש נמי\u0004 \u0005[גם כן]\u0006 \u0003לא ליחייביה\u0004 \u0005[יחייבוהו]\u0006 בארבעה וחמישה!","ש\u0003אמר רבא:\u0004 כיון שאמרו בית דין לגנב \u0003\"צא תן לו\",\u0004 אם אחרי כן הוא \u0003טבח\u0004 או \u0003מכר\u0004 — \u0003פטור, מאי טעמא\u0004 \u0005[מה הטעם]?\u0006","\u0003כיון דפסקוה למילתיה\u0004 \u0005[שפסקו את עניינו]\u0006 \u0003וטבח ומכר\u0004 דבר שפסקו שאינו שלו, והוא ממרה בגלוי את פיהם — \u0003הוה ליה\u0004 \u0005[הריהו נעשה]\u0006 כ\u0003גזלן, וגזלן אינו משלם תשלומי ארבעה וחמשה.\u0004"],["אם אמרו בבית דין רק \u0003\"חייב אתה ליתן לו\",\u0004 אם \u0003טבח ומכר\u0004 — \u0003משלם תשלומי ארבעה וחמשה, מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 — \u0003כיון\u0004 ש\u0003לא פסקה מילתא\u0004 \u0005[נפסק\u0006 ונחתך \u0005הדבר]\u0006 שיתן ממש, \u0003אכתי\u0004 \u0005[עדיין]\u0006 \u0003גנב הוא,\u0004 ואם כן לא ניתן לכאורה להעמיד משנה זו בהקדישוהו בעלים!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דאמרי ליה\u0004 \u0005[שאומרים לו]\u0006 הדיינים: \u0003\"חייב אתה ליתן לו\",\u0004 שעדיין גנב הוא, ומתחייב בארבעה וחמישה אם עדיין לא הקדיש.","\u0003גופא,\u0004 לגופה של ההלכה שהוזכרה קודם, \u0003אמר ר' יוחנן: גזל ולא נתייאשו הבעלים\u0004 — \u0003שניהם אינן יכולים להקדיש\u0004 את הדבר הנגזל, \u0003זה\u0004 (הגזלן) — \u0003לפי ש\u0004הדבר הנגזל \u0003אינו שלו, וזה\u0004 (הבעלים) — \u0003לפי שאינו ברשותו.\u0004 ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 אכן \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: הלכה כסתם משנה,\u0004 כלומר, כדעה המובאת במשנה לא כדעתו של תנא מסויים.","\u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006 \u0003כרם רבעי,\u0004 שהוא כרם בשנה הרביעית לנטיעתו, שפירותיו כפי שהם אסורים באכילה וצריך להעלותם לירושלים ולאוכלם שם, או לחללם בכסף ולהעלות את הכסף לירושלים, ולהשתמש בו שם לאכילה, \u0003היו מציינין\u0004 (מסמנים) \u0003אותו בקזוזות\u0004 (גושי) \u0003אדמה\u0004 שהניחו סביבו, שידעו בכך הכל שהוא כרם רבעי, ולא יבואו לאכול ממנו. ומסבירים: \u0003סימנא\u0004 \u0005[הסימן]\u0006 הוא \u0003כי\u0004 \u0005[כמו]\u0006 \u0003אדמה,\u0004 ובאופן זה: \u0003מה אדמה איכא\u0004 \u0005[יש]\u0006 \u0003הנאה מינה\u0004 \u0005[ממנה]\u0006 לאחר שעיבדוה כראוי, \u0003אף האי\u0004 \u0003נמי כי מפרקא שרי לאיתהנויי מינה\u0004 \u0005[זו\u0006 כרם רבעי \u0005גם כן כאשר\u0006 היא \u0005נפדית מותר ליהנות ממנה].\u0006","ומוסיפה המשנה: \u0003ו\u0004אילו כרם \u0003של ערלה\u0004 היו מסמנים אותו \u0003בחרסית\u0004 (חרסים שבורים). ומסבירים: \u0003סימנא\u0004 \u0005[הסימן]\u0006 הוא \u0003כחרסית, מה חרסית\u0004 היא דבר \u0003שאין הנאה מינה\u0004 \u0005[ממנה],\u0006 \u0003אף האי\u0004 \u0005[זה,\u0006 כרם ערלה\u0005]\u0006 הוא דבר \u0003דלית ביה\u0004 \u0005[שאין בו]\u0006 \u0003הנאה מיניה\u0004 \u0005[ממנו],\u0006 לפי שפירות ערלה אסורים בהנאה לעולם.","ועוד הלכה דומה: \u0003ו\u0004מקום \u0003של קברות\u0004 — היו מסמנים \u0003בסיד\u0004 על מנת שהכהנים והעוסקים בטהרות לא ייטמאו בו. ומסבירים: \u0003סימנא\u0004 \u0005[הסימן]\u0006 הוא \u0003דחיור\u0004 \u0005[ש\u0006הוא \u0005לבן]\u0006 \u0003כעצמות\u0004 המתים. \u0003וממחה\u0004 (וממיס) את הסיד \u0003ושופך\u0004 סיד זה. ומסבירים: \u0003כי היכי דניחוור טפי\u0004 \u0005[כדי שיהא לבן ביותר].\u0006","\u0003אמר רבן שמעון בן גמליאל: במה דברים אמורים\u0004 שעושים סימנים אלה לכרם רבעי וערלה — \u0003ב\u0004שנה ה\u0003שביעית,\u0004 בשנת השמיטה. ומסבירים: וטעמו של דבר ש\u0003הפקר נינהו\u0004 \u0005[הם]\u0006 הפירות, והעוברים על פני הכרם יכולים לקוטפם שהרי בשנת השביעית הכל הפקר, ולכן ראוי לסמן כרם רבעי וערלה מה טיבו, כדי שידעו הלוקטים להיזהר ולא ליהנות ממנו.","\u0003אבל בשאר שני שבוע\u0004 (השנים במחזור שבע השנים) שאינן שמיטה — אין צורך לעשות כך, אלא \u0003הלעיטהו לרשע וימות,\u0004 שאם אדם מסויים רשע הוא וגונב — אין אנו צריכים לחשוש לתקנתו, שלא ייכשל בגניבתו ויאכל דבר האסור באכילה, ולא איכפת לנו אם עבר לא רק על איסור גניבה אלא גם על איסור חמור אחר.","ומוסיפה המשנה: \u0003והצנועין\u0004 (יראי השמים והמדקדקים) שהם בעליו של כרם רבעי, היו \u0003מניחין את המעות, ואומרים: כל הנלקט מ\u0004כרם רבעי \u0003זה מחולל על המעות הללו.\u0004 כדי שלא יכשלו הלוקחים באיסור כרם רבעי. ואם יכולים הבעלים לחלל פירות כרם רבעי שכבר אינם ברשותם אלא נלקטו על ידי גזלנים. משמע אם כן, מסתם משנה, שיש לאדם בעלות לענין הקדש על חפצים גם כשאינם ברשותו וקשה על ר' יוחנן!","\u0003וכי תימא\u0004 \u0005[תאמר]:\u0006 \u0003מאן תנא\u0004 \u0005[מי הוא\u0006 התנא \u0005ששנה]\u0006 הלכה זו ב\u0003צנועין\u0004 — \u0003רבן שמעון בן גמליאל,\u0004 כלומר, שהלכה זו אינה סתם משנה אלא המשך דברי רבן שמעון בן גמליאל, \u0003ור' יוחנן כ\u0004דעת \u0003סתם\u0004 של \u0003יחידאה\u0004 \u0005[יחיד]\u0006 \u0003לא אמר,\u0004 שלמרות שנאמרו הדברים בסתם, וללא ציון שם אומרם, אבל כיון שהם דברי יחיד, הם אינם הלכה,","\u0003ו\u0004אולם \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003רבה בר בר חנה אמר ר' יוחנן: כל מקום ששנה רבן שמעון בן גמליאל במשנתנו\u0004 — \u0003הלכה כמותו, חוץ מ\u0004דין שנשנה בעניינו של \u0003ערב,\u0004 \u0003ו\u0004מה שאמר בדין שאירע בעיר \u0003צידן,\u0004 \u0003ו\u0004מה שאמר בדין \u0003ראיה אחרונה.\u0004 ואם כן בכל דרך שנאמר יוצא שר' יוחנן עצמו סבור שהלכה במשנה זו היא כצנועים, והרי זה בניגוד לדבריו בענין הקדש של דבר שאינו ברשותו!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003לא תימא\u0004 \u0005[אל תאמר]\u0006 שהיו הצנועים אומרים \u0003\"כל הנלקט מזה\",\u0004 כלומר, כל מה שכבר לקטו מזה יהא מחולל, \u0003אלא אימא\u0004 \u0005[אמור]\u0006 \u0003\"כל המתלקט מזה\",\u0004 שכוונתו שהיו מחללים מראש כל מה שעתידים אנשים לקחת. ונמצא שחיללו פירות שעדיין היו ברשותם.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר ר' יוחנן הכי\u0004 \u0005[כך]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: צנועין\u0004 בדין כרם רבעי \u0003ור' דוסא\u0004 בדין לקט עניים \u0003אמרו דבר אחד,\u0004 שהם הולכים בשיטה אחת, שאין אומרים הלעיטהו לרשע וימות אלא דואגים לתקנתו, \u0003ו\u0004אילו \u0003ר' דוסא\u0004 בפירוש \u0003\"נלקט\"\u0004 (בעבר) \u0003קאמר\u0004 \u0005[אומר]!\u0006","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: שחרית\u0004 (בבוקר) \u0003בעל הבית,\u0004 כלומר, בעלי השדה \u0003עומד ואומר: כל שילקטו עניים היום\u0004 משדי \u0003יהא הפקר,\u0004 שאם יזדמן שהעניים יקחו לא רק לקט המגיע להם מן הדין (שתי שיבולים), אלא שיבולים נוספות שאינן שייכות להם כדין, הרי מראש הוא מפקיר מה שהם עתידים ללקוט, כדי שלא יבואו לידי איסור.","\u0003ר' דוסא אומר:\u0004 לא בבוקר אלא \u0003לעיתותי ערב אומר: כל שלקטו עניים יהא הפקר!\u0004 הרי שלדעת ר' דוסא מועיל ההפקר גם לגבי דברים שאירעו כבר, אם כן אף לדברי ר' יוחנן עצמו הצנועים דיברו על מה שנלקח כבר, ולא על מה שעתיד להילקח, שהרי ר' יוחנן ור' דוסא אמרו דבר אחד!","ומשיבים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את השמות בברייתא זו, \u0003ר' יהודה לר' דוסא, ור' דוסא לר' יהודה,\u0004 ולפי זה ר' דוסא הוא האומר שיכול להפקיר רק את מה שיקחו בעתיד. ושואלים: \u0003אמאי אפכת מתניתא\u0004 \u0005[מדוע הופך אתה\u0006 \u0003את\u0004 \u0005הברייתא]?\u0006 \u0003אפכה\u0004 \u0005[הפוך]\u0006 את דברי \u0003ר' יוחנן, ואימא\u0004 \u0005[ואמור]\u0006 בדברי ר' יוחנן כך: \u0003צנועין ור' יהודה אמרו דבר אחד\u0004 שהמדובר על דבר שעתיד להילקט!","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003לא סגיא\u0004 \u0005[אי אפשר]\u0006 ש\u0003לא מתהפכת מתניתא\u0004 \u0005[להפוך את הברייתא]\u0006 גם מטעמים אחרים, \u0003דבהא מתניתין קתני\u0004 \u0005[ש\u0006הרי \u0005בברייתא זו שנה]\u0006 \u0003דאית ליה\u0004 \u0005[שיש לו]\u0006 \u0003לר' יהודה\u0004 דין \u0003ברירה,\u0004 כלומר, שדבר שיתברר בפועל בעתיד יכול לחול כבר עתה, שהרי לדעתו אותו דבר שיתברר בעתיד במשך היום שלקחוהו העניים — יהא הפקר כבר בבוקר. \u0003ו\u0004אולם \u0003שמעינן ליה\u0004 \u0005[ושמענוהו]\u0006 \u0003לר' יהודה בעלמא\u0004 \u0005[בכלל]\u0006 שדעתו \u0003דלית ליה\u0004 \u0005[שאין לו]\u0006 דין \u0003ברירה,\u0004 ולכן חייבים אנו להפוך את השיטות כדי להתאים את שיטת ר' יהודה לשיטתו במקומות אחרים. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006"],["\u0003הלוקח\u0004 (הקונה) \u0003יין מבין הכותים\u0004 (השומרונים) בערב שבת, והם מן הסתם לא הפרישו תרומות ומעשרות, ואין לו עתה פנאי להפריש בפועל את המעשרות מן היין, ורוצה לשתות מן היין בשבת, אם קנה מאה לוגים \u0003אומר\u0004 כך: \u0003שני לוגין שאני עתיד להפריש\u0004 לאחר השבת כדין תרומה גדולה מיין זה \u0003הרי הן תרומה, עשרה\u0004 לוגים הרי הם \u0003מעשר ראשון, תשעה\u0004 לוגים הרי הם \u0003מעשר שני, ומיחל\u0004 (מחלל) את המעשר השני שביין זה על כסף \u0003ושותה מיד\u0004 מן היין, אלו \u0003דברי ר'\u0004 \u0003מאיר.\u0004","ואילו \u0003ר'\u0004 \u0003יהודה ור'\u0004 \u0003יוסי ור'\u0004 \u0003שמעון אוסרין\u0004 לעשות כן. וטעמו של ר' יהודה משום שהוא סבור שאין ברירה, שאין אומרים שיתברר לאחר מעשה למפרע שמה שהופרש היה תרומה ומעשר, ומה ששתה היה חולין.","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003סוף סוף אמאי קא אפכת לה למתניתין\u0004 \u0005[מדוע הפכת את הברייתא]?\u0006 \u0003משום דקשיא\u0004 \u0005[שקשה]\u0006 מדברי \u0003ר'\u0004 \u0003יהודה\u0004 על דברי \u0003ר'\u0004 \u0003יהודה, השתא נמי\u0004 \u0005[עכשיו גם כן]\u0006 \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ר'\u0004 \u0003יוחנן\u0004 על דברי \u0003ר'\u0004 \u0003יוחנן,\u0004","\u0003דאמרת\u0004 \u0005[ש\u0006הרי \u0005אומר אתה]\u0006 \u0003ל\u0004דעת \u0003ר'\u0004 \u0003יוחנן: לא תימא\u0004 \u0005[אל תאמר]\u0006 לשיטת הצנועים \u0003\"כל הנלקט\u0004 בעבר מחולל על המעות הללו \u0003\",\u0004 \u0003אלא אימא\u0004 \u0005[אמור]\u0006 \u0003\"כל המתלקט\"\u0004 בעתיד. \u0003אלמא אית ליה\u0004 \u0005[מכאן שיש לו]\u0006 דין \u0003ברירה,\u0004 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003ר'\u0004 \u0003יוחנן\u0004 עצמו \u0003לית ליה\u0004 \u0005[אין לו]\u0006 דין \u0003ברירה,\u0004 ש","\u0003אמר רב אסי אמר ר'\u0004 \u0003יוחנן: האחין שחלקו\u0004 בירושה את נכסי אביהם — הרי כ\u0003לקוחות הן\u0004 נחשבים והריהם כאילו קנו זה מזה, \u0003ו\u0004לכן \u0003מחזירין זה לזה\u0004 את חלקם בקרקעות ובבתים \u0003ביובל\u0004 כדין כל קנין שחוזר ביובל. ולאחר מכן חוזרים וחולקים שוב את הנכסים. ומכאן שר' יוחנן סבור שאין ברירה, ולכן אין אומרים שנתברר למפרע שכל אח קיבל את חלקו המגיע לו בתורת ירושה, ואין צורך להחזיר!","\u0003אלא לעולם\u0004 צריך לשנות בברייתא לדעת ר' יוחנן \u0003\"כל הנלקט\"\u0004 משום שאין דין ברירה, ואף שיש מכאן לכאורה ראיה שיכול אדם להקדיש דבר שאינו ברשותו,","\u0003ו\u0004מה שפסק ר' \u0003יוחנן\u0004 שאין אדם יכול להקדיש מה שאינו ברשותו הוא משום ש\u0003סתמא אחרינא אשכח\u0004 \u0005[סתם\u0006 משנה \u0005אחר מצא],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין הגונב אחר,\u0004 מן, \u0003הגנב משלם תשלומי כפל.\u0004 ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]\u0006 הגנב השני לא משלם תשלומי כפל? \u0003בשלמא\u0004 \u0005[נניח]\u0006 ש\u0003לגנב ראשון לא משלם\u0004 תשלומי כפל — אפשר לומר שהוא מדייק מלשון הכתוב בדין תשלומי כפל \u0003\"וגנב מבית האיש...\u0004 ישלם שנים\u0003\"\u0004 (שמות כב, ו), להדגיש: \u0003ולא מבית הגנב. אלא לבעלים נשלם\u0004 \u0005[שישלם]\u0006 את הכפל!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שאין כאן תשלום כפל לא לגנב הראשון ולא לבעלים, כי \u0003זה\u0004 הגנב הראשון \u0003לפי שאינו שלו, וזה\u0004 הבעלים \u0003לפי שאינו ברשותו.\u0004","ושואלים: אף שיש סתם משנה המסייע לדברי ר' יוחנן, מכל מקום \u0003ומאי חזית דאזיל בתר ההיא סתמא, ליעביד כי האי סתמא\u0004 \u0005[ומה ראית\u0006 לומר \u0005שהולך אחרי אותו סתם, שיעשה כמו סתם זה]\u0006 של ה\u0003צנועין?\u0004","ומשיבים: \u0003משום\u0004 ש\u0003מסייע ליה\u0004 \u0005[לו]\u0006 לר' יוחנן בשיטתו זו \u0003קרא\u0004 \u0005[הכתוב],\u0006 שהרי נאמר: \u0003\"ואיש כי יקדש את ביתו קדש לה'\"\u0004 (ויקרא כז, יד), ללמד: \u0003מה ביתו ברשותו, אף כל\u0004 דבר שהוא מקדיש צריך להיות \u0003ברשותו.\u0004","\u0003אמר אביי: אי לאו\u0004 \u0005[אם לא]\u0006 ש\u0003אמר ר'\u0004 \u0003יוחנן\u0004 כי \u0003צנועין ור'\u0004 \u0003דוסא אמרו דבר אחד,\u0004 כלומר, שהם בשיטה אחת, \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003צנועין אית להו\u0004 \u0005[יש להם,\u0006 מקבלים\u0005]\u0006 את דברי \u0003ר'\u0004 \u0003דוסא, ו\u0004אילו \u0003ר'\u0004 \u0003דוסא לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את דברי \u0003צנועין.\u0004","ומסביר: \u0003צנועין אית להו\u0004 \u0005[יש להם,\u0006 מקבלים\u0005]\u0006 את תקנתו של \u0003ר'\u0004 \u0003דוסא,\u0004 וטעמם: \u0003ומה בגנב,\u0004 כלומר, זה שלקח בגניבה מכרם רבעי \u0003עבדו רבנן תקנתא\u0004 \u0005[עשו חכמים תקנה]\u0006 לטובתו והתירו לבעלים לפדות דבר שאינו ברשותו, על מנת שלא ייכשל הגנב באיסור, \u0003עניים\u0004 שלקחו בלקט יותר ממה שזכאים הם בדין, שאינם גונבים במזיד אלא לוקחים בטעות, \u0003צריכא למימר\u0004 \u0005[צריך לומר]\u0006 שיעשו להם תקנה שלא יכשלו באיסור? ואילו \u0003ר'\u0004 \u0003דוסא לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 את תקנתם של \u0003צנועין,\u0004 כי דווקא \u0003עניים הוא דעבדו להו רבנן תקנתא\u0004 \u0005[שעשו להם חכמים תקנה]\u0006 \u0003אבל גנב לא עבדו ליה רבנן תקנתא\u0004 \u0005[עשו לו חכמים תקנה]\u0006 ואומרים בו \"הלעיטהו לרשע וימות\".","ובדומה לכך \u0003אמר רבא, אי לאו\u0004 \u0005[אם לא]\u0006 ש\u0003אמר ר'\u0004 \u0003יוחנן: צנועין ור'\u0004 \u0003דוסא אמרו דבר אחד, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003מאן תנא\u0004 \u0005[מי הוא\u0006 התנא \u0005ששנה]\u0006 הלכה זו של \u0003צנועין\u0004 בכרם רבעי? — שיטת ר' \u0003מאיר היא.\u0004","\u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003אמר ר'\u0004 \u0003מאיר\u0004 כי \u0003מעשר\u0004 שני \u0003ממון גבוה הוא,\u0004 שהמעשר השני שייך בעצם להקדש, \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003לענין פדייה\u0004 שיכול הוא לפדותו \u0003אוקמיה רחמנא ברשותיה\u0004 \u0005[העמידתו,\u0006 את המעשר, \u0005התורה\u0006 \u0005ברשותו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואם גאל יגאל איש ממעשרו חמשתו יסף עליו\"\u0004 (ויקרא כז, לא),","\u0003קרייה רחמנא\u0004 \u0005[קראה אותו התורה]\u0006 \u0003\"מעשרו\"\u0004 השייך לו, \u0003ו\u0004לפיכך \u0003מוסיף\u0004 עליו \u0003חומש\u0004 כדין בעלים של דבר הפודהו מן ההקדש.","וכן \u0003כרם רבעי נמי\u0004 \u0005[גם כן]\u0006 נחשב הדבר ברשותו לענין חילולו משום ש\u0003גמר\u0004 \u0005[למד]\u0006 בגזירה שווה, \u0003\"קדש\" \"קדש\" ממעשר\u0004 שני, \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בכרם רבעי: \u0003\"קדש הלולים\"\u0004 (ויקרא יט, כד), \u0003וכתיב גבי\u0004 \u0005[ונאמר אצל]\u0006 \u0003מעשר: \"וכל מעשר הארץ מזרע הארץ מפרי העץ לה' הוא קדש\u0004 לה'\u0003\"\u0004(ויקרא ה כז, ל),","\u0003מה \"קדש\" דכתיב גבי\u0004 \u0005[שנאמר אצל]\u0006 \u0003מעשר, אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003ממון גבוה הוא,\u0004 מכל מקום \u0003לענין פדייה אוקמיה רחמנא ברשותיה\u0004 \u0005[העמידתו התורה ברשותו],\u0006 \u0003אף האי\u0004 \u0005[אותו]\u0006 \u0003\"קדש\" נמי דכתיב גבי\u0004 \u0005[גם כן שנאמר אצל]\u0006 \u0003כרם רבעי, אף על גב דלאו ממון דידיה\u0004 \u0005[אף על פי שלא ממון שלו]\u0006 \u0003הוא\u0004 אלא ממון גבוה, מכל מקום \u0003לענין אחולי אוקמיה רחמנא ברשותיה\u0004 \u0005[חילול העמידתו התורה ברשותו],\u0006","\u0003דהא כי איתיה ברשותיה נמי הא לאו דידיה\u0004 \u0005[שהרי\u0006 גם \u0005כאשר ישנו ברשותו גם כן לא שלו]\u0006 \u0003הוא,\u0004 \u0003והא מצי מחיל\u0004 \u0005[והרי יכול לחלל],\u0006 \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003מצי מחיל\u0004 \u0005[יכול לחלל]\u0006 גם כשלקטוהו אחרים ואינו ברשותו.","\u0003אבל גבי\u0004 \u0005[אצל]\u0006 \u0003לקט, כיון דממונא דידיה\u0004 \u0005[שהממון\u0006 הוא \u0005שלו],\u0006 דווקא \u0003כי איתיה ברשותיה\u0004 \u0005[כאשר ישנו ברשותו]\u0006 \u0003הוא דמצי מפקר ליה\u0004 \u0005[שיכול להפקיר אותו],\u0006 \u0003כי ליתיה ברשותיה לא מצי מפקר ליה\u0004 \u0005[כאשר אינו ברשותו אינו יכול להפקיר אותו]\u0006 לכן היה ראוי לצרף את שיטת צנועין לדברי ר' מאיר, ולא לשיטת ר' דוסא שהתיר להפקיר בלקט שאינו ברשותו.","וכיוצא בו \u0003אמר רבינא: אי לאו\u0004 \u0005[אם לא]\u0006 ש\u0003אמר ר'\u0004 \u0003יוחנן צנועין ור'\u0004 \u0003דוסא אמרו דבר אחד, הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003מאן תנא\u0004 \u0005[מי הוא\u0006 התנא \u0005ששנה]\u0006 \u0003צנועין?\u0004 זו עצמה דעת \u0003ר'\u0004 \u0003דוסא היא,\u0004 והיא דעת יחיד. \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא תקשי\u0004 \u0005[תקשה]\u0006 \u0003סתם משנה\u0004 של צנועים \u0003לר'\u0004 \u0003יוחנן.\u0004 \u0003ו\u0004טעם הדבר — שהרי \u0003ר' יוחנן\u0004 שאמר הלכה כסתם משנה,"],["\u0003כסתם\u0004 משנה \u0003יחידאה\u0004 \u0005[\u0006של דעת \u0005יחיד]\u0006 \u0003לא אמר,\u0004 ונמצא לדרך זו שהוא פוסק כדעת רבים.","בנושא קרוב לשאלה זו \u0003אמרי נהרדעי\u0004 \u0005[אמרו\u0006 חכמי העיר \u0005נהרדעא]:\u0006 \u0003לא כתבינן אורכתא\u0004 \u0005[כותבים אנו שטר הרשאה]\u0006 בו מייפה אדם את כוחו של חבירו לתבוע את פקדונו או את חובו מאדם אחר \u0003אמטלטלי\u0004 \u0005[על מיטלטלים]\u0006. \u0003אמר רב אשי לאמימר: מאי טעמא\u0004 \u0005[מה טעם]\u0006 אין עושים כן? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003משום\u0004 שיטת \u0003ר' יוחנן,\u0004 ש","\u0003אמר ר' יוחנן: גזל ולא נתייאשו הבעלים\u0004 — \u0003שניהם\u0004 (הבעלים והגזלן) \u0003אינן יכולין להקדיש, זה\u0004 (הגזלן) \u0003לפי שאינו שלו, וזה\u0004 (הבעלים) \u0003לפי שאינו ברשותו.\u0004 ואף כאן, כיון שאין המיטלטלים ברשותו של המרשה אינו יכול להקנותם לאחר.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים],\u0006 \u0003אמרי נהרדעי\u0004 \u0005[אמרו\u0006 חכמי \u0005נהרדעא]:\u0006 \u0003לא כתבינן אורכתא אמטלטלי דכפריה\u0004 \u0005[אין אנו כותבים שטר הרשאה על מיטלטלים ש\u0006כבר \u0005כפר בו\u0006 הנפקד במפקיד\u0005],\u0006 שטען שאין בידו חפץ של הלה. ומדייקים: \u0003טעמא\u0004 \u0005[הטעם]\u0006 שאין כותבים אורכתא דווקא \u0003דכפריה\u0004 \u0005[\u0006כ\u0005שכפר בו],\u0006 משום \u0003דמיחזי כשיקרא\u0004 \u0005[שנראה\u0006 שטר ההרשאה \u0005כשקר],\u0006 שמקנה בו המרשה לשליחו דבר שכל עוד לא יוכיח אחרת — אינו שייך לו. \u0003אבל\u0004 אם \u0003לא כפריה\u0004 \u0005[כפר בו]\u0006 — \u0003כתבינן\u0004 \u0005[כותבים אנו].\u0006","\u0003ו\u0004עוד \u0003אמרי נהרדעי\u0004 \u0005[ואמרו\u0006 חכמי \u0005נהרדעא]\u0006 בענין זה של שטר הרשאה: \u0003אורכתא\u0004 \u0005[שטר הרשאה]\u0006 ש\u0003לא כתיב ביה\u0004 \u0005[כתוב בו]\u0006 \u0003\"זיל דון וזכי ואפיק לנפשך\"\u0004 \u0005[\"לך דון\u0006 עם הנפקד \u0005וזכה\u0006 בחפץ \u0005והוצא\u0006 וקח אותו \u0005לעצמך\"]\u0006 — \u0003לית ביה מששא\u0004 \u0005[אין בו ממש].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003משום דאמר ליה האיך\u0004 \u0005[שיכול לומר לו ההוא,\u0006 הנתבע\u0005]:\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בעל דברים דידי את\u0004 \u0005[שלי אתה],\u0006 ואין אני רוצה לדון עימך, אלא עם האיש שעימו יש לי משא ומתן.","\u0003אמר אביי: ואי כתיב ביה\u0004 \u0005[ואם כתוב בו]\u0006 בשטר ההרשאה שהוא נותן לו רשות לדון ולזכות לעצמו \u0003למחצה\u0004 או \u0003לשליש\u0004 \u0003ו\u0004כן \u0003לרביע\u0004 (רבע) של החפץ הנתבע בו — \u0003מיגו דמשתעי דינא אפלגא\u0004 \u0005[מתוך ש\u0006חייב הנתבע \u0005לדבר\u0006 עימו \u0005בדין,\u0006 להתדיין, \u0005על חצי]\u0006 החפץ או שליש ורבע שאותם הוא תובע לעצמו, \u0003משתעי דינא אכולה\u0004 \u0005[מדבר\u0006 עמו \u0005בדין על הכל].\u0006","\u0003אמר אמימר: אי\u0004 \u0005[אם]\u0006 \u0003תפס\u0004 המורשה ממה שקיבל — \u0003לא מפקינן מיניה\u0004 \u0005[מוציאים אנו ממנו],\u0006 שהרי זיכה לו המרשה. \u0003רב אשי אמר:\u0004 \u0003כיון דכתביה ליה\u0004 \u0005[שכתב לו]\u0006 בהרשאה: \u0003\"כל דמתעני מן דינא קבילית עלי\"\u0004 \u0005[\"כל\u0006 מה \u0005שיצא מן הדין\u0006 על ידך \u0005מקבל אני עלי\"]\u0006 — \u0003שליח שויה\u0004 \u0005[עשה אותו].\u0006","\u0003ואיכא דאמר\u0004 \u0005[ויש שאומר]:\u0006 \u0003שותפא שויה\u0004 \u0005[שותף עשה אותו].\u0006 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה],\u0006 מה ההבדל אם הוא שליח או שותף? ומשיבים: \u0003למיתפס פלגא\u0004 \u0005[לתפוס\u0006 \u0005מחצית],\u0006 שאם שותף הוא, יכול לתפוס עבור עצמו. ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 \u0003שליח שויה\u0004 \u0005[עשה אותו]\u0006 ואין מחזיק ההרשאה רשאי לתפוס לעצמו.","מי שיודעים אנו בו ש\u0003גנב על פי\u0004 עדות \u0003שנים\u0004 עדים, \u0003וטבח\u0004 או \u0003מכר על פיהם\u0004 (על פי עדות אותם עדים), \u0003או\u0004 שטבח או מכר \u0003על פי\u0004 עדות \u0003שנים אחרים\u0004 — \u0003משלם תשלומי ארבעה וחמשה.\u0004","\u0003גנב ומכר בשבת, גנב ומכר לעבודה זרה, גנב וטבח ביום הכפורים,\u0004 הרי אף שעבר עבירה מלבד זה שגנב ומכר או טבח, הואיל ואין בעבירה זו עונש מיתה, עדיין חייב הוא לשלם עבור הגניבה כל תשלומיה.","\u0003גנב משל אביו וטבח ומכר ואחר כך מת אביו\u0004 והוא מיורשי אביו, או אם \u0003גנב וטבח ואחר כך הקדיש\u0004 — \u0003משלם תשלומי ארבעה וחמשה.\u0004","וכן אם \u0003גנב וטבח\u0004 ואין שחיטה זו מביאה את הבהמה לאכילה, כגון ששחט \u0003לרפואה, או\u0004 כדי להאכיל \u0003לכלבים,\u0004 וכן \u0003השוחט\u0004 את הבהמה הגנובה \u0003ונמצאת טריפה,\u0004 או \u0003השוחט חולין בעזרה\u0004 — \u0003משלם תשלומי ארבעה וחמשה.\u0004","\u0003ר' שמעון פוטר בשני אלו,\u0004 בשני המקרים האחרונים, שלדעתו שחיטה שאינה ראויה להכשיר לאכילה, אינה קרויה שחיטה.","שנינו במשנה שאם שני עדים מעידים על הגניבה ושני עדים אחרים מעידים על הטביחה או המכירה — חייב בארבעה וחמישה. ומציעים: \u0003לימא מתניתין\u0004 \u0005[האם לומר\u0006 כי \u0005משנתנו]\u0006 ש\u0003לא כ\u0004דעת \u0003ר' עקיבא.\u0004","\u0003דאי\u0004 \u0005[שאם]\u0006 \u0003ר' עקיבא, האמר\u0004 \u0005[הרי אמר]:\u0006 נאמר בתורה בדיני עדות \"על פי שני עדים או על פי שלושה עדים יקום דבר\" (דברים יט, טו), וההדגשה \"דבר\" באה ללמדנו: שהעדים צריכים להעיד על \u0003דבר\u0004 שלם \u0003ולא\u0004 על \u0003חצי דבר.\u0004 ואם שניים מעידים על גניבה ושניים אחרים על טביחה או מכירה, הרי השניים האחרים מעידים רק על חצי דבר, שהרי בלעדי עדות השניים הראשונים אי אפשר לחייבו בארבעה וחמישה.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003אמר ר' יוסי: כשהלך אבא\u0004 (ר') \u0003חלפתא אצל ר' יוחנן בן נורי ללמוד תורה. ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שכך היתה הגרסה: כשהלך \u0003ר' יוחנן בן נורי אצל אבא\u0004"],["\u0003חלפתא, אמר לו\u0004 שאלה זו:","\u0003הרי\u0004 אדם \u0003ש\u0004ירד לשדה חבירו ו\u0003אכלה\u0004 (נהנה מפירות אותה חלקת אדמה) \u0003שנה ראשונה בפני שנים\u0004 המעידים על כך, שנה \u0003שניה בפני שנים\u0004 אחרים, שנה \u0003שלישית בפני שנים\u0004 אחרים, \u0003מהו?\u0004 האם נאמר שהעדויות מצטרפות, ואם כן יש עדות על חזקה בקרקע, שהיא באכילת שלוש שנים, והרי היא שלו או לא?","\u0003אמר לו: הרי זו חזקה. אמר לו\u0004 החכם השני: \u0003אף אני אומר כן, אלא שר'\u0004 \u0003עקיבא חולק בדבר, שהיה ר'\u0004 \u0003עקיבא אומר:\u0004 העדים צריכים להעיד על \u0003דבר\u0004 שלם \u0003ולא\u0004 על \u0003חצי דבר.\u0004 ואין זה כמשנתנו!","\u0003אמר אביי: אפילו תימא\u0004 \u0005[תאמר]\u0006 שמשנתנו כשיטת \u0003ר'\u0004 \u0003עקיבא, מי\u0004 \u0005[האם]\u0006 \u0003לא מודה ר'\u0004 \u0003עקיבא בשנים\u0004 שמעידים ו\u0003אומרים: קידש\u0004 איש פלוני אשה פלונית \u0003ושנים\u0004 אחרים \u0003אומרים: בעל\u0004 אותה, ונקבע לה בכך דין מיוחד,","\u0003דאף על גב\u0004 \u0005[שאף על פי]\u0006 ש\u0003עדי ביאה צריכי\u0004 \u0005[צריכים]\u0006 \u0003לעדי קדושין,\u0004 לפי שבלעדי עדי קדושין אין משמעות הלכתית לבעילה זו. מכל מקום \u0003כיון\u0004 ש\u0003עדי קדושין לא צריכי\u0004 \u0005[צריכים]\u0006 \u0003לעדי ביאה,\u0004 אלא מעידים הם על דבר שיש לו משמעות הלכתית לעצמו, הרי עדות זו של עדי ביאה \u0003דבר\u0004 שלם \u0003קרינא ביה\u0004 \u0005[קוראים אנו אותו].\u0006","\u0003הכא נמי\u0004 \u0005[כאן\u0006 בענין גניבה וטביחה או מכירה \u0005גם כן]\u0006 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003עדי טביחה צריכי\u0004 \u0005[צריכים]\u0006 \u0003לעדי גניבה\u0004 כדי שתהא זו עדות המחייבת תשלומי ארבעה וחמישה, אולם \u0003כיון\u0004 ש\u0003עדי גניבה לא צריכי\u0004 \u0005[צריכים]\u0006 \u0003לעדי טביחה\u0004 ועדותם בלבד מחייבת אותו, \u0003דבר\u0004 שלם של עדות \u0003קרינא ביה\u0004 \u0005[קוראים אנו אותו],\u0006 ולכן מתקבלת עדות זו.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 החולקים על ר' עקיבא, \u0003האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 ודיוקו: \u0003\"דבר\"\u0004 — \u0003ולא חצי דבר, למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]\u0006 בא כתוב זה? ומפרשים: \u0003למעוטי\u0004 \u0005[למעט]\u0006 צירוף עדויות על סימני בגרות אצל נערה, שהם שתי שערות, מקרה שעד \u0003אחד אומר\u0004 שראה שיער \u0003אחד בגבה\u0004 של נערה שהוא חצי סימן בגרות, \u0003ואחד אומר\u0004 שראה שיער \u0003אחד בכריסה,\u0004 שהם למדים מן הכתוב שאין זו עדות היכולה להצטרף.","ותוהים: \u0003האי\u0004 \u0005[זה]\u0006 אין צורך למעט, שהרי \u0003חצי דבר וחצי עדות הוא,\u0004 שהרי כל אחד מהם (שהוא \"חצי עדות\") אינו מעיד על שתי שערות, שהן סימן בגרות, אלא על שערה אחת (שהוא \"חצי דבר\")!","\u0003אלא\u0004 יש לדחות הסבר זה ולומר כי לשיטת חכמים בא הכתוב \u0003למעוטי\u0004 \u0005[למעט]\u0006 מקרה כזה: \u0003שנים אומרים\u0004 שראו שיער \u0003אחד בגבה, ושנים אומרים\u0004 שראו שיער \u0003אחד בכריסה.\u0004 שאף שיש כאן עדות שני עדים, מכל מקום \u0003הני אמרי\u0004 \u0005[אלו אומרים]\u0006 \u0003קטנה היא\u0004 שהרי ראו רק שערה אחת, \u0003והני אמרי\u0004 \u0005[ואלו אומרים]\u0006 \u0003קטנה היא.\u0004 וכיון שאין עדים המעידים שהיא גדולה, שיש לה שתי שערות הרי זה \"חצי דבר\" — ואין אני מצרף את שתי העדויות יחד, לומר שמדברי קבוצות העדים עולה שיש לה שתי שערות והרי היא גדולה.","שנינו במשנה: \u0003גנב ומכר בשבת\u0004 — הרי זה חייב על המכירה בתשלומי ארבעה וחמישה. ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שבכיוצא בזה \u0003פטור!\u0004","\u0003אמר רמי בר חמא: כי תניא\u0004 \u0005[כאשר שנינו]\u0006 את הברייתא \u0003ההיא\u0004 ש\u0003פטור\u0004 הריהי \u0003באומר לו\u0004 הקונה לגנב: \u0003עקוץ\u0004 (קטוף) \u0003לך תאינה מתאינתי\u0004 ותאנים אלה יהיו כתשלום עבור החפץ הגנוב, \u0003ו\u0004על ידי כך \u0003תיקני\u0004 \u0005[תקנה]\u0006 \u0003לי גניבותיך\u0004 \u0005[גניבתך]\u0006 וכיון שקטף בשבת והתחייב בכך מיתה — הריהו נפטר מעונש ממון\u0005.\u0006","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בשאלה על הסבר זה \u0003וכיון דכי תבע ליה קמן בדינא, לא אמרינן ליה: זיל שלים\u0004 \u0005[שכאשר יתבע אותו\u0006 בעל התאינה \u0005לפנינו בדין,\u0006 על שמכר לו דבר גנוב, \u0005אין אנו אומרים לו\u0006 לגנב: \u0005לך שלם]\u0006 לבעל התאינה את התאנים שקטפת או את הגניבה שגנבת, כיון \u0003דמחייב\u0004 \u0005[שמתחייב]\u0006 \u0003בנפשו הוא\u0004 על חילול השבת, שוב אינו חייב לשלם דמי התאינה, אם כן \u0003הא\u0004 \u0005[זו]\u0006 ה\u0003מכירה נמי לאו\u0004 \u0005[גם כן לא]\u0006 \u0003מכירה היא\u0004 ואין זה נקרא מכירה כלל, ובגלל זה יש לפטור אותו מארבעה וחמישה!","\u0003אלא אמר רב פפא:\u0004 מדובר כאן בברייתא \u0003באומר לו\u0004 הקונה לגנב: \u0003זרוק גניבותיך\u0004 \u0005[גניבתך]\u0006 \u0003לחצרי ותיקני\u0004 \u0005[ותיקנה]\u0006 \u0003לי\u0004 על ידי כך \u0003גניבותיך\u0004 \u0005[גניבתך],\u0006 שחילל שבת בהוצאת דבר מרשות הרבים שבה הוא עומד לחצר שהיא רשות היחיד.","ושואלים: אם כן, \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 היא הלכה זו? ומשיבים: \u0003כ\u0004שיטת \u0003ר'\u0004 \u0003עקיבא,\u0004 ש\u0003אמר:\u0004 \u0003קלוטה,\u0004 דבר שנקלט, שעבר בתוך החלל של מקום מסויים, הריהו \u0003כמי שהונחה\u0004 באותו מקום \u0003דמיא\u0004 \u0005[נחשבת]\u0006 לענין שבת. שכאשר הגיעה הגניבה לחלל החצר — מיד נתחייב הזורק משום העברה מרשות לרשות בשבת.","\u0003דאי כרבנן\u0004 \u0005[שאם\u0006 תאמר שהוא \u0005כ\u0006שיטת \u0005חכמים]\u0006 החולקים על ר' עקיבא בענין זה, הלא \u0003כיון דמטיא\u0004 \u0005[שמגיעה]\u0006 הגניבה \u0003ל\u0004חלל \u0003חצר ביתו\u0004 הרי הבעלים \u0003קנה\u0004 כבר את החפץ, שחלל החצר יפה כוחו כחצר עצמה לענין קנין, ואולם \u0003לענין שבת לא מחייב\u0004 \u0005[מתחייב]\u0006 \u0003עד דמטיא לארעא\u0004 \u0005[שתגיע לקרקע]\u0006 ממש, שכן חיוב העברה מרשות לרשות בקנין חצר, תלוי בהנחת החפץ ברשות שאליה הועבר, ואם כן נמצא שנתחייב קודם בגניבה ואחר כך בחילול שבת, ובכגון זה, שאין החיובים באים כאחד, ודאי שצריך לשלם עבור הגניבה!","ומשיבים: אפשר לומר שהוא גם כדברי חכמים, ומדובר \u0003באומר\u0004 הקונה לגנב: \u0003לא תיקני\u0004 \u0005[תיקנה]\u0006 \u0003לי גניבותיך\u0004 \u0005[גניבתך]\u0006 \u0003עד שתנוח\u0004 על הקרקע ממש, ובמקרה זה חיוב שבת וחיוב גניבה באים כאחד.","\u0003רבא אמר: לעולם\u0004 אפשר לפרש את הברייתא \u0003כ\u0004דברי \u0003רמי בר חמא,\u0004 שמדובר שהקונה אמר לגנב שיקטוף תאנים כתשלום גניבתו, משום שהקושיה שהקשינו עליו לא היתה מבוססת, שהרי גם במקרה שאין אפשרות לתבוע קיום הקנין בדין, אין זה מבטל את עצם המכירה. וראיה לכך מן ההלכה ש\u0003אתנן\u0004 זונה \u0003אסרה תורה\u0004 להשתמש בו כקרבן, \u0003ואפילו\u0004 אם היה זה אתנן של בן ש\u0003בא על אמו,\u0004 \u0003ו\u0004הרי \u0003אי תבעה ליה קמן בדינא\u0004 \u0005[אם תתבע אותו\u0006 אמו \u0005לפנינו בדין]\u0006 שישלם לה אתננה, \u0003מי אמרינן ליה\u0004 \u0005[האם נאמר לו]:\u0006 \u0003קום הב\u0004 \u0005[עמוד תן]\u0006 \u0003לה\u0004 את ה\u0003אתנן?\u0004 והרי התחייב בנפשו בביאה זו!","\u0003אלא אף על גב דכי קא תבעה ליה בדינא\u0004 \u0005[אף על פי שכאשר היא תתבע אותו בדין]\u0006 \u0003לא אמרינן ליה\u0004 \u0005[נאמר לו]:\u0006 \u0003זיל הב\u0004 \u0005[לך תן]\u0006 \u0003לה,\u0004 מכל מקום \u0003כיון דכי יהיב\u0004 \u0005[שכאשר נותן]\u0006 \u0003לה הוי\u0004 \u0005[הריהו]\u0006 \u0003אתנן\u0004 — \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לענין תשלומין אי תבע בדינא קמן \u0005[אם יתבע\u0006 הקונה את הגנב \u0005בדין לפנינו]\u0006 לא אמרינן ליה\u0004 \u0005[נאמר לו]:\u0006 \u0003זיל שלים\u0004 \u0005[לך שלם],\u0006"],["\u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003כיון דקא מקני ליה בהכי\u0004 \u0005[שמקנה לו בכך]\u0006 — \u0003הויא\u0004 \u0005[\u0006\u0005הריהי]\u0006 \u0003מכירה\u0004 למרות שאינו יכול לתבוע אותו בדין.","שנינו במשנה: \u0003גנב וטבח ביום הכפורים\u0004 הרי זה חייב בתשלומי ארבעה וחמישה. \u0003אמרי\u0004 \u0005[אומרים]\u0006 בשאלה על כך: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003נהי דקטלא ליכא\u0004 \u0005[אם אומנם ש\u0006עונש \u0005מוות אין כאן]\u0006 על חילול יום הכיפורים, אולם הלא עונש \u0003מלקות מיהא איכא\u0004 \u0005[מכל מקום יש כאן],\u0006 \u0003וקיימא לן\u0004 \u0005[ומוחזק בידינו]\u0006 הכלל ש\u0003אינו לוקה ומשלם,\u0004 שאם אדם לוקה על עבירה שוב אינו משלם עליה תשלומי ממון!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003הא מני\u0004 \u0005[\u0006משנה \u0005זו כ\u0006שיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר:\u0004 אדם \u0003לוקה ומשלם\u0004 על אותה עבירה.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 כדעת \u0003ר' מאיר, אפילו טבח בשבת\u0004 יהא חייב ובמשנתנו לא שנינו כן! \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003לוקה ומשלם אית ליה\u0004 \u0005[יש לו],\u0006 שלדעתו יכול להיענש בשניהם יחד, אולם \u0003מת ומשלם לית ליה\u0004 \u0005[אין לו].\u0006","על כך יש להקשות: \u0003ולא?\u0004 וכי אינו סבור כן? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003גנב וטבח בשבת, גנב וטבח לעבודה זרה, גנב שור הנסקל\u0004 (שהתחייב בסקילה, ואסור בהנאה) \u0003וטבחו\u0004 — בכל אלה \u0003משלם ארבעה וחמשה,\u0004 כ\u0003דברי ר' מאיר, וחכמים פוטרין!\u0004","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחייה: \u0003בר מינה דההיא\u0004 \u0005[חוץ מ\u0006ברייתא \u0005זו]\u0006 שאין להבינה כמשמעה, \u0003דהא אתמר עלה\u0004 \u0005[שהרי\u0006 כבר \u0005נאמר עליה]:\u0006 \u0003אמר ר' יעקב אמר ר' יוחנן, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003ר' ירמיה אמר ר' שמעון בן לקיש,\u0004 וכן \u0003ר' אבין ור' אלעא וכל חבורתא משמיה\u0004 \u0005[החבורה משמו]\u0006 של \u0003ר' יוחנן אמרי\u0004 \u0005[אמרו]:\u0006 מדובר כאן \u0003בטובח על ידי אחר,\u0004 שלא הגנב עצמו טבח בשבת או לעבודה זרה, אלא עשה זאת שליחו, שאין הגנב מתחייב מיתה על כך ולכן מתחייב הוא בתשלומים.","ושואלים על כך: \u0003וכי זה חוטא וזה מתחייב?\u0004 כיצד אחד (השליח) חוטא בטביחה והשני (הגנב) יתחייב על מעשהו?","\u0003אמר רבא: שאני הכא\u0004 \u0005[שונה כאן]\u0006 הדבר בדין ארבעה וחמישה, ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וטבחו\u0004 או \u0003מכרו\"\u0004 (שמות כא, לז) להקישם זה לזה, ובאופן זה: \u0003מה מכירה\u0004 נעשית בהכרח \u0003על ידי אחר,\u0004 שהרי אין אדם מוכר לעצמו, ומתחייב על כך — \u0003אף טביחה\u0004 חייב עליה לא רק אם טבח בעצמו, אלא גם \u0003על ידי אחר.\u0004","\u0003דבי\u0004 \u0005[\u0006החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה]\u0006 מקור אחר באותו כתוב להלכה זו: נאמר \"וטבחו או מכרו\", \u0003\"או\"\u0004 — הרי זה בא \u0003לרבות את השליח,\u0004 שאף הוא מחייב את שולחו בתשלומי ארבעה וחמישה. \u0003דבי\u0004 \u0005[\u0006החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה תנא\u0004 \u0005[שנה]\u0006 לימוד אחר לענין זה: נאמר \"חמשה בקר ישלם \u0003תחת\u0004 השור\" (שמות כא, לז) — הרי זה \u0003לרבות את השליח\u0004 שבא במקום (תחת) משלחו, לחייב את המשלח בארבעה וחמישה.","על הסבר זה של הברייתא \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003מר זוטרא: מי איכא מידי, דאילו עביד איהו לא מיחייב\u0004 \u0005[וכי יש דבר שאם היה עושה אותו הוא\u0006 עצמו, המשלח \u0005לא היה מתחייב],\u0006 שהרי יש עליו עונש מיתה הפוטרו מממון, \u0003ו\u0004אם \u0003עביד\u0004 \u0005[עושה]\u0006 אותו \u0003שליח ומיחייב\u0004 \u0005[ומתחייב],\u0006 והרי אין כוחו של השליח יכול להיות גדול מכוחו של משלחו?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי: התם\u0004 \u0005[שם]\u0006 אצלנו הסיבה היא \u0003לאו\u0004 \u0005[לא]\u0006 \u0003משום\u0004 ש\u0003לא מיחייב\u0004 \u0005[מחוייב]\u0006 \u0003הוא,\u0004 שמעיקרו של דבר היה צריך להיות חייב גם כשהמשלח טבח, \u0003אלא דקם ליה\u0004 \u0005[שעמד,\u0006 די, \u0005לו]\u0006 \u0003בדרבה מיניה\u0004 \u0005[ב\u0006עונש \u0005הגדול ממנו]\u0006 שאין מענישים אותו שני עונשים על אותה עבירה, אלא על האחד היותר גדול בין השניים. אבל במקרה שהוא אינו חייב מיתה — אכן, מחייבים אותו על הטביחה.","ושואלים מצד אחר: \u0003ואי\u0004 \u0005[ואם]\u0006 מדובר כאן \u0003בטובח על ידי אחר, מאי טעמא דרבנן דפטרי\u0004 \u0005[מה הטעם של חכמים\u0006 החולקים על ר' מאיר \u0005שפוטרים]\u0006 שהרי במקרה כזה צריכים היו גם חכמים לחייב!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003מאן\u0004 \u0005[מי הם]\u0006 \u0003חכמים\u0004 אלה? — \u0003ר' שמעון,\u0004 ש\u0003אמר: שחיטה שאינה ראויה\u0004 לאכילה \u0003לא שמה שחיטה,\u0004 ומשום כך אינו חייב עליה תשלומי ארבעה וחמישה משום טובח.","\u0003אמרי\u0004 \u0005[אומרים]\u0006 על כך בשאלה: \u0003בשלמא\u0004 \u0005[נניח]\u0006 שחיטה ל\u0003עבודה זרה\u0004 \u0003ו\u0004שחיטת \u0003שור הנסקל\u0004 הרי \u0003שחיטה שאינה ראויה\u0004 לאכילה \u0003היא,\u0004 כי הבהמה הנשחטת אסורה בהנאה, \u0003אלא\u0004 שחיטה ב\u0003שבת\u0004 הלא \u0003שחיטה ראויה היא! דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 במפורש: \u0003השוחט בשבת וביום הכפורים, אף על פי שמתחייב בנפשו\u0004 על מלאכת השחיטה, \u0003שחיטתו כשירה\u0004 לאכילה!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003סבר לה\u0004 \u0005[סבורים\u0006 חכמים החולקים על ר' מאיר \u0005ב\u0006ענין \u0005זה]\u0006 \u0003כ\u0004שיטת \u0003ר' יוחנן הסנדלר,\u0004 האוסר את הנשחט בשבת. ולכן, אף שחיטה בשבת הריהי שחיטה שאינה ראויה לאכילה.","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003המבשל בשבת,\u0004 אם בישל \u0003בשוגג\u0004 — \u0003יאכל\u0004 ממה שבישל, אם בישל \u0003במזיד\u0004 — \u0003לא יאכל,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר: בשוגג\u0004 — \u0003יאכל\u0004 אבל רק \u0003במוצאי שבת, במזיד\u0004 — \u0003לא יאכל עולמית,\u0004 שלא יהנה כלל ממלאכה שעשה בשבת, אבל הדבר מותר לאחרים.","\u0003ר' יוחנן הסנדלר אומר:\u0004 אם בישל \u0003בשוגג\u0004 — \u0003יאכל\u0004 מה שבישל \u0003למוצאי שבת לאחרים ולא לו, במזיד\u0004 — \u0003לא יאכל עולמית, לא לו ולא לאחרים.\u0004 נמצא שלדעת ר' יוחנן הסנדלר אסור ליהנות לעולם משחיטה שנעשתה במזיד בשבת, והרי זו שחיטה שאינה ראויה כלל לאכילה.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוחנן הסנדלר?\u0004 ומסבירים: \u0003כדדריש\u0004 \u0005[כפי שדרש]\u0006 \u0003ר' חייא אפיתחא דבי נשיאה\u0004 \u0005[על פתחו של בית הנשיא],\u0006 נאמר: \u0003\"ושמרתם את השבת כי קדש הוא לכם\"\u0004 (שמות לא, יד) ובאה השוואה זו בין שבת לקודש ללמד: \u0003מה קדש אסור באכילה, אף מעשה שבת אסורין באכילה.\u0004","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 כך אתה מקיש, שמא נאמר: \u0003מה קדש אסור בהנאה, אף מעשה שבת אסור בהנאה,\u0004 ולא רק באכילה! \u0003תלמוד לומר: \"לכם\",\u0004 כוונתו — \u0003שלכם יהא\u0004 אף שאסור לאכול ממנו, וכיון שיש לו בעלות עליו, יכול גם למוכרו או לעשות בו שימוש אחר של הנאה.","\u0003יכול אפילו בשוגג\u0004 יהא אסור באכילה? \u0003תלמוד לומר: \"מחלליה מות יומת\"\u0004 (שמות לא, יד), דווקא \u0003במזיד אמרתי לך\u0004 דבר זה, במי ששייך בו חיוב מיתה, \u0003ולא בשוגג.\u0004","ובענין זה מוסיפים: \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה,\u0004 בשאלה זו, \u0003רב אחא ורבינא, חד\u0004 \u0005[אחד]\u0006 מהם \u0003אמר: מעשה שבת\u0004 אסור \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם \u0003אמר: מעשה שבת\u0004 אסור רק \u0003דרבנן\u0004 \u0005[מדברי סופרים].\u0006","ואומרים: \u0003מאן דאמר דאורייתא, כדאמרן\u0004 \u0005[מי שאומר ש\u0006הוא איסור \u0005תורה,\u0006 טעמו \u0005כפי שאמרנו]\u0006 לפי דרשתו של ר' חייא. \u0003ומאן דאמר דרבנן\u0004 \u0005[ומי שאומר ש\u0006אסור רק \u0005מדברי סופרים],\u0006 הוא דייק כך בכתוב: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין שבת: \u0003\"קדש הוא\",\u0004 ללמד: \u0003הוא קדש ואין מעשיו קדש,\u0004 שהפסוק מלמד שמעשה שבת, כלומר, מלאכות שנעשו בשבת, אינו כקודש שאסור באכילה.","ושואלים לענייננו: \u0003בשלמא למאן דאמר דאורייתא\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר ש\u0006הוא איסור \u0005תורה],\u0006 \u0003אמטו\u0004"],["\u0003להכי\u0004 \u0005[משום כך]\u0006 \u0003פטרי רבנן\u0004 \u0005[פטרו חכמים]\u0006 מארבעה וחמישה מי שגנב וטבח בשבת, משום ששחיטת שבת שחיטה שאינה ראויה היא, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהנשחט בשבת אסור רק \u0003דרבנן\u0004 \u0005[\u0006מ\u0005דברי סופרים],\u0006 \u0003אמאי פטרי רבנן\u0004 \u0005[מדוע פטרו חכמים]?\u0006","ומשיבים: יש לומר שלא לענין שבת נאמר בברייתא שחכמים חולקים על ר' מאיר ופוטרים, אלא \u0003אשארא\u0004 \u0005[על שאר]\u0006 ההלכות הנזכרות שם, שהן שחיטה ל\u0003עבודה זרה ו\u0004שחיטת \u0003שור הנסקל,\u0004 שהם אסורים בהנאה מן התורה.","ושואלים: \u0003ור' מאיר,\u0004 אף אם הוא סבור ששחיטה זו נחשבת שחיטה. \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003מחייב\u0004 ב\u0003שוחט לעבודה זרה?\u0004","הלא \u0003כיון\u0004 ש\u0003שחט בה פורתא\u0004 \u0005[מעט]\u0006 לשם עבודה זרה כבר \u0003אסרה\u0004 בהנאה, \u0003אידך\u0004 \u0005[שאר]\u0006 פעולת השחיטה, כשממשיך לשחוט וגומר וטובח את הבהמה, הרי בהמה זו כבר בכלל \u0003איסורי הנאה הוא, ולא דמריה קא טבח\u0004 \u0005[של בעליו הוא טובח],\u0006 שהרי הופקעה הבהמה מרשות הבעלים, \u0003ולא דידיה קא טבח\u0004 \u0005[שלו הוא טובח]!\u0006","\u0003אמר רבא:\u0004 צריכים לומר כי מדובר \u0003באומר בגמר זביחה הוא עובדה,\u0004 שהתכוון שעבודת האלילים תתחיל לא מתחילת שחיטה אלא בסופה של השחיטה, ולכן רק כאשר הוא גומר את השחיטה אז מתחייב משום עבודה זרה, ונמצא שאיסור ההנאה וגמר מעשה הטביחה היו בבת אחת.","ושואלים עוד: הלא גם \u0003שור הנסקל איסורי הנאה נינהו\u0004 \u0005[הם],\u0006 ואם כן, גנב שטבח שור הנסקל נמצא ש\u0003לאו דמריה קא טבח ולאו דידיה קא טבח\u0004 \u0005[לא של בעליו הוא טובח ולא של עצמו הוא טובח]\u0006 ומדוע מחייבו ר' מאיר בארבעה וחמישה!","\u0003אמר רבא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שמסרו\u0004 בעליו את השור \u0003לשומר, והזיק\u0004 השור \u0003בבית שומר, והועד\u0004 והזיק שלוש פעמים \u0003בבית שומר, ונגמר דינו\u0004 כשעודו \u0003בבית שומר\u0004 לסקילה, וגנב זה גנבו מבית השומר וטבחו, ועליו לשלם תשלומי ארבעה וחמישה לשומר. \u0003ור' מאיר סבר לה\u0004 \u0005[סבור ב\u0006ענין \u0005זה]\u0006 גם \u0003כ\u0004שיטת \u0003ר' יעקב וסבר לה\u0004 \u0005[וסבור ב\u0006ענין \u0005זה]\u0006 גם כן \u0003כ\u0004שיטת \u0003ר' שמעון.\u0004 כיצד?","\u0003סבר לה\u0004 \u0005[סבור בזה]\u0006 \u0003כ\u0004שיטת \u0003ר' יעקב,\u0004 ש\u0003אמר:\u0004 \u0003אף משנגמר דינו\u0004 של השור שהרג, אם \u0003החזירו שומר לבעלים\u0004 כל עוד לא נהרג השור בפועל — הרי זה \u0003מוחזר,\u0004 ואינו צריך לשלם שור אחר. אף שהשור הזה עתה אין לו ערך כספי, לפי שהנזק שנגרם בו באובדן ערכו (על ידי פסק הדין) אינו נזק ניכר.","\u0003וסבר לה\u0004 \u0005[וסבור בזה]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון,\u0004 ש\u0003אמר: דבר הגורם לממון כממון דמי\u0004 \u0005[\u0006הוא \u0005נחשב].\u0006 ומנין שהוא סבור כך?","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ר' שמעון אומר:\u0004 הגונב \u0003קדשים שחייב\u0004 בעליהם \u0003באחריותן\u0004 שצריך להביא אחרים תחתיהם אם אבדו הראשונים שהקדיש — \u0003חייב\u0004 בתשלומי כפל, שאף על פי שהקדשים עצמם אינם שייכים לבעלים, מכל מקום כיון שהמקדיש חייב להביא אחרים תחתיהם נמצא שהגנב הפסידו ממון, \u0003אלמא\u0004 \u0005[מכאן]\u0006 כי לדעתו \u0003דבר הגורם לממון כממון דמי\u0004 \u0005[נחשב].\u0006 ומשום כך אף הגונב את השור מבית השומר וטבחו, הואיל וגרם לכך שאין השומר יכול עתה להחזירו עוד לבעלים — נמצא שגרם לשומר להפסיד את דמי השור. ולכן אף שהשור עצמו לאחר שנגמר דינו לסקילה הוא איסור הנאה ואינו שווה מאומה, מכל מקום יש משמעות ממונית לגניבה ולטביחה, ולכן משלם הגנב לשומר ארבעה וחמישה.","וחוזרים לעיקר הסוגיה, לפיה העמדנו דין טובח ביום הכיפורים שבמשנתנו כר' מאיר. \u0003אמר רב כהנא, אמריתא לשמעתא קמיה\u0004 \u0005[אמרתי את השמועה\u0006 הסוגיה הזו \u0005לפני]\u0006 \u0003רב זביד מנהרדעא\u0004 ושאלתיו: \u0003מי מצית מוקמת מתניתין\u0004 \u0005[האם יכול אתה להעמיד\u0006 את \u0005משנתנו]\u0006 \u0003כ\u0004שיטת \u0003ר' מאיר ולא כ\u0004שיטת \u0003ר' שמעון? והא קתני סיפא\u0004 \u0005[והרי שנה\u0006 ב\u0005סופה]:\u0006 \u0003ר' שמעון פוטר בשני אלו, מכלל\u0004 זה נלמד \u0003דבכולה מתניתין\u0004 \u0005[שבכל משנתנו]\u0006 הוא \u0003מודה\u0004 לחכמים!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא\u0004 כך יש לדייק, אלא \u0003מכלל\u0004 הדברים תלמד ש\u0003מודה\u0004 ר' שמעון \u0003בטבח ומכר לרפואה ולכלבים,\u0004 שאף שאין השחיטה מיועדת לאכילת אדם, מכל מקום היתה זו שחיטה העושה את הבהמה ראויה למאכל, ולכן נחשבת כשחיטה ראויה.","שנינו במשנה: \u0003גנב משל אביו וטבח ומכר\u0004 ואחר כך מת אביו — חייב בתשלומי ארבעה וחמישה ליורשי האב. \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מרב נחמן: גנב שור של שני שותפין וטבחו, ו\u0004אחר כך \u0003הודה\u0004 בעצמו \u0003לאחד מהן\u0004 שעשה זאת, \u0003מהו\u0004 הדין לענין תשלום ארבעה וחמישה, שהוא קנס? שהרי כיון שהודה לשותף אחד — הריהו פטור מלשלם לו קנס, כדינו של כל מודה בקנס, ונמצא שחייב לשלם רק מחצית הקנס לאחד מהם.","וצדדי השאלה: האם בהגדרת קנס זה \u0003\"חמשה בקר\" אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 \u0003ולא חמשה חצאי בקר,\u0004 שהתורה עמדה על כך שישלם דווקא את מלוא הקנס. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003\"חמשה בקר\" אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 \u0003ואפילו חמשה חצאי בקר\u0004 בכלל זה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003\"חמשה בקר\" אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 \u0003ולא חמשה חצאי בקר.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 רבא ממה ששנינו במשנה: \u0003גנב משל אביו וטבח ומכר, ואחר כך מת אביו\u0004 — \u0003משלם תשלומי ארבעה וחמשה. והא הכא\u0004 \u0005[והרי כאן]\u0006 \u0003כיון\u0004 ש\u0003מת אביו,\u0004 והוא יורשו עם שאר האחים — ולכן גם הוא זכאי עם אחיו בתשלומים אלה של ארבעה וחמישה, \u0003כמו שקדם והודה לאחד מהן דמי\u0004 \u0005[נחשב]\u0006 הדבר, שהרי בוודאי אינו משלם לעצמו את חלקו, \u0003וקתני\u0004 \u0005[ושנה]\u0006 בכל זאת: \u0003משלם תשלומי ארבעה וחמשה!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003כגון שעמד\u0004 עם \u0003אביו\u0004 כנגדו \u0003בדין\u0004 על הגניבה והטביחה, ונתחייב לשלם ממון לאביו קודם שנפטר. וכיון שנתחייב כבר חוב של ממון, הרי שאר האחים יורשים את כל החמישה בקר וארבעה הצאן, שהוא כשאר חובות שחבים אנשים לאביהם.","וחזר רבא והקשה: \u0003אבל\u0004 אם \u0003לא עמד בדין, מאי\u0004 \u0005[מה]\u0006 יהא הדין לפי זה — \u0003אינו משלם תשלומי ארבעה וחמשה? אי הכי, אדתני סיפא\u0004 \u0005[אם כך, עד ש\u0006הוא \u0005שונה\u0006 ב\u0005סופה\u0006 של המשנה\u0005]\u0006 אופן של פטור מארבעה וחמישה: \u0003גנב משל אביו ומת ואחר כך טבח ומכר\u0004 — \u0003אינו משלם תשלומי ארבעה וחמשה, ניפלוג בדידיה\u0004 \u0005[שיחלק ב\u0006אותו אופן \u0005עצמו]\u0006 וישנה כך: \u0003במה דברים אמורים\u0004 — \u0003כשעמד בדין, אבל\u0004 אם עדיין \u0003לא עמד בדין\u0004 — \u0003אינו משלם תשלומי ארבעה וחמשה!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003הכי נמי\u0004 \u0005[כך הוא גם כן]\u0006 הדין. אלא \u0003איידי דנסיב רישא\u0004 \u0005[מתוך שנקט\u0006 ב\u0005ראשונה]\u0006 את המקרה של \u0003גנב משל אביו וטבח ומכר ואחר כך מת אביו, נסיב סיפא נמי\u0004 \u0005[נקט\u0006 ב\u0005סוף גם כן]\u0006 את הדוגמה של \u0003גנב משל אביו ומת אביו ואחר כך טבח ומכר,\u0004 שלשם יפי הניסוח הביא הלכה זו בלשון דומה.","כל משא ומתן זה היה בערב, ואולם \u0003לצפרא\u0004 \u0005[בבוקר]\u0006 למחרתו \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן לרבא היפך הדברים בתשובה לשאלתו: \u0003\"חמשה בקר\" אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 \u0003ואפילו חמשה חצאי בקר,\u0004 והסביר רב נחמן את שינוי הדברים: \u0003והאי\u0004 \u0005[וזה]\u0006 ש\u0003לא אמרי\u0004 \u0005[אמרתי]\u0006 \u0003לך\u0004 כך \u0003באורתא\u0004 \u0005[בערב]\u0006 —"],["משום ש\u0003לא אכלי בשרא דתורא\u0004 \u0005[אכלתי בשר שור]\u0006 מפני שהתעניתי אתמול והייתי חלוש בגלל העדר אוכל, ולכן לא דקדקתי בדבר.","ושאלו רבא: אם כן \u0003ואלא מאי שנא רישא ומאי שנא סיפא\u0004 \u0005[\u0006ב\u0005מה שונה ההתחלה ו\u0006ב\u0005מה שונה הסוף]\u0006 ומדוע לא ישלם בכל מקרה לאחיו את חלקם בארבעה וחמישה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן בתשובה: \u0003רישא קרינא ביה\u0004 \u0005[\u0006ב\u0005תחילה קוראים אנו בו]\u0006 \u0003\"וטבחו\" כולו באיסורא\u0004 \u0005[באיסור],\u0006 שבזמן הטביחה היתה הבהמה שייכת כולה לאב, ונמצא שעשה מעשה עבירה גמור בטביחה. \u0003סיפא לא קרינא ביה\u0004 \u0005[\u0006ב\u0005סוף אין אנו קוראים בו]\u0006 \u0003\"וטבחו\" כולו באיסורא\u0004 \u0005[באיסור].\u0006 כי לאחר מות האב יש חלק גם לבנו הגנב בבהמה זו, ונמצא שטביחתה לא היתה כולה באיסור.","שנינו במשנה: \u0003השוחט ונמצאת טריפה\u0004 וכן השוחט חולין בעזרה — משלם תשלומי ארבעה וחמישה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חביבי מחוזנאה\u0004 (איש מחוזא) \u0003לרב אשי: שמע מינה\u0004 \u0005[למד מכאן]\u0006 מן הדין לגבי שחיטת חולין בעזרה, כי \u0003אינה לשחיטה אלא לבסוף,\u0004 שאין מעשה השחיטה נחשב כמעשה גמור אלא בסופו,","\u0003דאי\u0004 \u0005[שאם]\u0006 תאמר ש\u0003ישנה לשחיטה מתחילה ועד סוף,\u0004 ושמתחילת מעשה השחיטה הרי הוא נחשב כשוחט, אם כן, יש להקשות על דין המשנה: \u0003כיון\u0004 ש\u0003שחט בה פורתא\u0004 \u0005[מעט]\u0006 מיד \u0003אסרה\u0004 בהנאה כדין חולין שנשחטו בעזרה, \u0003אידך\u0004 \u0005[השאר]\u0006 \u0003לא דמריה קא טבח\u0004 \u0005[של בעליו הוא טובח]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא: כי קא מחייב\u0004 \u0005[כאשר הוא מתחייב]\u0006 בתשלומים על הטביחה — \u0003אההוא פורתא\u0004 \u0005[על אותו מעט]\u0006 ששחט בראשונה הוא שמתחייב. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי: לא תידחי\u0004 \u0005[תדחה]\u0006 כך, כי \u0003\"וטבחו\" כולו בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003וליכא\u0004 \u0005[ואין כאן].\u0006 שלענין תשלומין אין החיוב אלא על שחיטה מלאה.","אמר לו רב הונא: \u0003אלא\u0004 מכל מקום \u0003קשיא\u0004 \u0005[קשה]\u0006 מדין זה של שוחט חולין בעזרה, שהרי מכאן הוכחה ששחיטה היא רק בסוף! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב גמדא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: כגון ששחט מקצת\u0004 שני ה\u0003סימנין\u0004 (קנה וושט) של הבהמה \u0003בחוץ\u0004 והכניס את הבהמה למקדש, \u0003וגמרן,\u0004 ששחט עוד מעט עד לגמר מצוות השחיטה, \u0003בפנים.\u0004 נמצא שרק בסוף השחיטה מתחייב על עבירה של שחיטת חולין בעזרה והן בחיוב הטביחה לענין תשלומים.","\u0003איכא דמתני לה אהא\u0004 \u0005[יש ששונה\u0006 את הסוגיה \u0005הזו על\u0006 דבר \u0005זה]\u0006 שאמרנו: \u0003אמר ר' שמעון\u0004 בן לקיש \u0003משום\u0004 (בשם) \u0003ר' לוי סבא\u0004 \u0005[הזקן]:\u0006 \u0003אינה לשחיטה אלא לבסוף, ור' יוחנן אמר: ישנה לשחיטה מתחילה ועד סוף.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חביבי מחוזנאה לרב אשי: לימא קסבר\u0004 \u0005[האם לומר\u0006 ש\u0005סבור]\u0006 \u0003ר' יוחנן\u0004 ש\u0003חולין שנשחטו בעזרה לאו דאורייתא\u0004 \u0005[אין\u0006 איסורם \u0005מן התורה]?\u0006"],["\u0003דאי סלקא דעתך דאורייתא\u0004 \u0005[שאם יעלה על דעתך\u0006 לומר שאיסורם \u0005מן התורה],\u0006 הלא \u0003מכי שחיט לה פורתא\u0004 \u0005[מ\u0006הזמן \u0005אשר שחט אותה\u0006 בהמה \u0005מעט]\u0006 מסימניה \u0003אסרה\u0004 בהנאה, \u0003אידך\u0004 — \u0003לאו דמרה קא טבח\u0004 \u0005[השאר\u0006 גמר שחיטת הסימנים — \u0005לא של בעליה הוא טובח].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא: כי קא מחייב\u0004 \u0005[כאשר הוא מתחייב]\u0006 תשלומים משום טביחה — \u0003נמי אההוא פורתא\u0004 \u0005[גם כן על אותו מעט\u0006 הוא מתחייב\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי: לא תידחיה\u0004 \u0005[תדחה אותו]\u0006 כך, \u0003\"וטבחו\"\u0004 משמע \u0003כולו בעינן\u0004 \u0005[צריכים אנו],\u0006 כדי לחייבו בתשלומי ארבעה וחמישה, \u0003וליכא\u0004 \u0005[ואין כאן].\u0006","שאלו רב אחא: \u0003אלא\u0004 מכל מקום \u0003קשיא\u0004 \u0005[קשה]\u0006 על ר' יוחנן! \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב גמדא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: כי קא מחייב\u0004 \u0005[כאשר הוא מתחייב],\u0006 הרי זה \u0003כגון ששחט מקצת סימנין בחוץ וגמרן בפנים.\u0004","מי שהעידו בו ש\u0003גנב\u0004 שור או שה\u0003על פי שנים\u0004 עדים, \u0003וטבח ומכר על פיהן\u0004 (על פי עדותם), \u0003ונמצאו\u0004 עדים אלה \u0003זוממים,\u0004 שהעידו עליהם שלא היו כלל באותו מקום באותו זמן עליו הם מעידים — \u0003משלמין הכל\u0004 ארבעה וחמישה, כפי שרצו לחייב אותו, כדינו של עד זומם שנענש בעונש אותו זמם לעשות לזה, כנאמר \"ועשיתם לו כאשר זמם לעשות לאחיו\" (דברים יט, יט).","\u0003גנב על פי\u0004 עדות של \u0003שנים,\u0004 \u0003וטבח ומכר על פי\u0004 עדותם של \u0003שנים אחרים,\u0004 אם \u0003אלו ואלו נמצאו זוממין\u0004 הרי \u0003הראשונים\u0004 שהעידו על הגניבה — \u0003משלמין\u0004 לו \u0003תשלומי כפל, ואחרונים\u0004 — \u0003משלמין תשלומי\u0004 שנים או \u0003שלשה\u0004 שהיה מוסיף ומתחייב לשלם על פיהם.","\u0003נמצאו אחרונים\u0004 בלבד \u0003זוממין,\u0004 שנתברר שאכן גנב, אבל מה שהעידו בו שטבח היתה עדות מוזמת — \u0003הוא משלם תשלומי כפל\u0004 לבעלים כגנב, \u0003והן משלמין\u0004 לגנב \u0003תשלומי\u0004 שנים או \u0003שלשה\u0004 שרצו לחייבו לשלם בנוסף לתשלומי הכפל.","נמצא \u0003אחד מן אחרונים זוממין\u0004 — \u0003בטלה עדות שניה.\u0004 נמצא \u0003אחד מן הראשונים זוממין\u0004 — \u0003בטלה כל העדות, ש\u0004כן \u0003אם אין גניבה\u0004 מוכחת, ממילא \u0003אין טביחה ואין מכירה\u0004 של גנב, שהרי כל עוד לא ברור שבהמה של אחר הוא טובח ומוכר — אי אפשר לחייבו בתשלומים.","ומבררים תחילה עניינו של עד זומם. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בדינו של \u0003עד זומם. אביי אמר: למפרע הוא נפסל,\u0004 כלומר, יש לפסול כל עדות שהעיד מאותה שעה שהעיד עדות זו שהוזמה עתה, אף אלה שהעיד לפני שהוזם בפועל. ואילו \u0003רבא אמר: מכאן ולהבא,\u0004 משעה שהעידו בו והזימוהו \u0003הוא נפסל,\u0004 אבל לא משעת עדותו.","ומסבירים את טעמיהם: \u0003אביי אמר למפרע הוא נפסל,\u0004 וטעמו: \u0003מההוא שעתא דאסהיד\u0004 \u0005[מאותה שעה שהעיד]\u0006 שקר \u0003הוה ליה\u0004 \u0005[הריהו]\u0006 \u0003רשע, והתורה אמרה: \"אל תשת\u0004 ידך עם \u0003רשע\u0004 להיות \u0003עד\u0004 חמס\u0003\"\u0004(שמות כג, א).","ואילו \u0003רבא אמר: מכאן ולהבא הוא נפסל,\u0004 כי כל דין \u0003עד זומם חידוש\u0004 מיוחד \u0003הוא\u0004 שחידשה התורה, שאינו דומה לשאר הלכות, \u0003דהא תרי ותרי נינהו\u0004 \u0005[שהרי שנים ושנים הם]\u0006 גם העדים הזוממים וגם העדים המזימים אותם, \u0003מאי חזית דציית להני\u0004 \u0005[מה ראית ש\u0006אתה \u0005שומע\u0006 מאמין, דווקא \u0005לאלה]\u0006 האחרונים המזימים? \u0003ציית להני\u0004 \u0005[שמע לאלה\u0006 הראשונים\u0005]!\u0006","\u0003הלכך\u0004 \u0005[על כן]\u0006 מכיון שיש בו חידוש \u0003אין לך בו\u0004 לפוסלו לעדות \u0003אלא משעת חידוש,\u0004 כלומר, משעה שהוזם \u0003ואילך.\u0004","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003רבא נמי\u0004 \u0005[גם כן]\u0006 בעיקרו של הדבר \u0003כאביי סבירא ליה\u0004 \u0005[סבור הוא],\u0006 ש\u0003אמר למפרע הוא נפסל, והכא היינו טעמיה\u0004 \u0005[וכאן זהו\u0006 \u0005טעמו]\u0006 של \u0003רבא,\u0004"],["\u0003משום פסידא\u0004 \u0005[הפסד]\u0006 של ה\u0003לקוחות,\u0004 שאם אכן תיפסל עדותם למפרע, ייגרם בכך נזק לקונים שהחתימו אותם על שטרות מכירה בתקופה זו שבין עדותם להזמתם, בלא לדעת שעדים אלו יתבררו מאוחר יותר כעדים פסולים.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל למעשה \u0005ביניהן]\u0006 בין שתי הלשונות הללו של רבא, אם זה או זה הוא טעמו? ומשיבים: ההבדל הוא כגון \u0003דאסהידו ביה תרי לחד ותרי לחד\u0004 \u0005[שהעידו בו,\u0006 שהזימוהו שנים עדים באחד ושנים עדים באחד], שלא היתה ההזמה על ידי שנים כנגד שנים, אלא הזימו שני עדים כל אחד ואחד מן העדים הראשונים, ובמקרה שכזה יש סברה להאמין לעדים המזימים ואין חידוש בדבר. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 במקרה כזה שהעדים האחרים לא פסלום כזוממים אלא \u0003דפסלינהו בגזלנותא\u0004 \u0005[שפסלום ב\u0006של \u0005גזלנות].\u0006","ובאופן זה יהיה הבדל בין שתי הלשונות בשני המקרים הללו: \u0003להך לישנא דאמרת\u0004 \u0005[לאותה לשון האומרת]\u0006 שפסולם של עדים זוממים לשיטת רבא מכאן ואילך הוא \u0003משום חידוש\u0004 — הרי כאן \u0003ליכא\u0004 \u0005[אין]\u0006 חידוש, ומודה רבא לאביי שייפסלו למפרע. \u0003להך לישנא דאמרת\u0004 \u0005[ללשון זו האומרת]\u0006 שהסיבה היא \u0003משום פסידא\u0004 \u0005[הפסד]\u0006 ה\u0003לקוחות\u0004 — \u0003איכא\u0004 \u0005[יש]\u0006 גם כאן טעם לדברי רבא, שלא ייפסלו אלא משעת העדאת העדים המזימים.","\u0003אמר ר' ירמיה מדפתי: עבד\u0004 \u0005[עשה]\u0006 \u0003רב פפא עובדא כוותיה\u0004 \u0005[מעשה כשיטתו] של \u0006\u0003רבא. רב אשי אמר:\u0004 בענין זה \u0003הלכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003אביי.\u0004 ומסכמים: \u0003והלכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003אביי\u0004 במחלוקותיו עם רבא \u0003ב\u0004שש הלכות, וסימנן (בראשי תיבות): \u0003יע\"ל קג\"ם\u0004 ועד זומם בכללן.","למרות שנמסר פסק ההלכה בענין זה, מבררים ודנים בשיטת אביי. \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003גנב על פי שנים וטבח ומכר על פיהם, ונמצאו זוממין\u0004 — \u0003משלמין את הכל.\u0004","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן \u0003שהעידו\u0004 אותם עדים תחילה \u0003על הגניבה, וחזרו והעידו על הטביחה, והוזמו\u0004 תחילה בעדותם \u0003על הגניבה וחזרו והוזמו\u0004 בעדותם \u0003על הטביחה. ו\u0004מעתה","\u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר כשיטת אביי שעד זומם \u0003למפרע הוא נפסל, הני כיון דאיתזמו להו\u0004 \u0005[\u0006עדים \u0005אלה כיון שהוזמו]\u0006 תחילה על עדות ה\u0003גניבה\u0004 אם כן בכך \u0003איגלאי מילתא\u0004 \u0005[נתברר הדבר]\u0006 \u0003למפרע דכי אסהדו\u0004 \u0005[שכאשר העידו]\u0006 על ה\u0003טביחה פסולין הוו\u0004 \u0005[היו]\u0006 ולא היה ממש בעדותם, ואם כן \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003משלמין\u0004 על ה\u0003טביחה\u0004 הרי התברר שהיו עדים פסולים ולא היתה עדותם ראויה כלל להזמה!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שהוזמו על\u0004 עדות \u0003הטביחה תחילה,\u0004 ונמצא שאף אם נפסלים למפרע אין זה פוסל את עדות הגניבה שקדמה לעדות הטביחה. ואחר כך הוזמו על הגניבה, ומשום כך משלמים על שתי העדויות.","\u0003אמרי\u0004 \u0005[אומרים]\u0006 כנגד זה: \u0003סוף סוף כי הדרי מיתזמי\u0004 \u0005[כאשר הם חוזרים\u0006 ומוזמים] על ה\u0003גניבה\u0004 \u0003איגלאי מילתא\u0004 \u0005[התברר הדבר]\u0006 \u0003דכי אסהדו\u0004 \u0005[שכאשר העידו]\u0006 על ה\u0003טביחה פסולין הוו\u0004 \u0005[היו]\u0006 מלהעיד, אם כן \u0003אמאי משלמי\u0004 \u0005[מדוע משלמים]\u0006 על ה\u0003טביחה?\u0004","ומסבירים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 זו יש להעמיד לפי אביי: \u0003שהעידו בבת אחת\u0004 על הגניבה ועל הטביחה, \u0003והוזמו,\u0004 שאף אם ייפסלו למפרע כשהוזמו על עדות הגניבה — לא קדמה עדות זו לעדות הטביחה כדי לפוסלה, ואז מתיישבים הדברים לשיטת אביי.","ומציעים: \u0003לימא כתנאי\u0004 \u0005[האם לומר\u0006 שאביי ורבא חלוקים במחלוקת תנאים] באותו ענין, ששנינו בברייתא: \u0003היו שנים מעידין אותו שגנב, והן\u0004 עצמם \u0003מעידין אותו שטבח, והוזמו על הגניבה\u0004 בלבד — הרי \u0003עדות שבטלה מקצתה בטלה כולה.\u0004","אבל \u0003הוזמו על הטביחה\u0004 בלבד — \u0003הוא,\u0004 הגנב, \u0003משלם תשלומי כפל,\u0004 שהרי עדות הגניבה קיימת ונתברר שגנב, \u0003והן,\u0004 העדים הזוממים, \u0003משלמין תשלומי\u0004 שנים או \u0003שלשה\u0004 שרצו לחייבו כתוספת לכפל.","\u0003אמר ר' יוסי: במה דברים אמורים\u0004 — כאשר היה זה \u0003בשתי עדיות, אבל בעדות אחת\u0004 והוזמו על הטביחה — \u0003עדות שבטלה מקצתה בטלה כולה.\u0004","ומעתה נברר את דברי ר' יוסי: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"בשתי עדיות\", ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"בעדות אחת\"? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003\"בשתי עדיות\"\u0004 כוונתו \u0003בשתי עדיות\u0004 נבדלות \u0003ממש,\u0004 שהיו \u0003בשתי כתות\u0004 שונות של עדים שהעידו בנפרד על כל דבר ודבר, ואילו \u0003\"בעדות אחת\"\u0004 כוונתו \u0003בכת אחת\u0004 של עדים שהעידו \u0003בזה אחר זה\u0004 על הגניבה ואחר כך על הטביחה.","\u0003ו\u0004לפיכך יש לפרש כי זה ש\u0003אמר ר' יוסי בעדות אחת,\u0004 כלומר \u0003בכת אחת\u0004 של עדים המעידים \u0003בזה אחר זה, כי מסהדי\u0004 \u0005[כאשר מעידים]\u0006 על ה\u0003גניבה והדר מסהדי\u0004 \u0005[וחוזרים\u0006 אחר כך ומעידים] על ה\u0003טביחה, כי מתזמי\u0004 \u0005[כאשר\u0006 הם מוזמים] על ה\u0003טביחה\u0004 הרי \u0003עדות שבטלה מקצתה בטלה כולה, ואיתזמו להו\u0004 \u0005[והוזמו להם]\u0006 על ה\u0003גניבה\u0004 גם כן, \u0003מהיכא תיתי הך\u0004 \u0005[מהיכן יבוא\u0006 דבר \u0005זה]?\u0006 אמנם עדותם על הטביחה הוזמה, אבל עדותם על הגניבה לא הוזמה כלל, ומדוע תיבטל העדות?","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 צריך לפרש כי \u0003\"בשתי עדיות\" —\u0004 משמעו \u0003בעדות אחת כעין שתי עדיות, ומאי נינהו\u0004 \u0005[ומה הן]\u0006 כיצד היה הדבר? שהיתה זו \u0003כת אחת\u0004 שהעידה על שני הדברים \u0003בזה אחר זה,\u0004 ולפיכך יש להבין: \u0003אבל בעדות אחת\u0004 כוונתו \u0003בבת אחת\u0004 שהעידו בזמן אחד גם על הגניבה וגם על הטביחה \u0003לא\u0004 מתחייב על הגניבה, שעדות שבטלה מקצתה בטלה כולה.","וכדי להסביר את הדברים לענייננו מקדימים כי \u0003סברוה\u0004 \u0005[סברו ב\u0006ענין זה] התלמידים שעסקו בזה, \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 כל דבר שאומר העד \u0003תוך כדי דיבור כדיבור\u0004 עצמו הוא \u0003דמי\u0004 \u0005[נחשב],\u0006 והרי הוא כעדות אחת.","ולפי הנחה זו, \u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006דבר \u0005זה\u0006 הם חלוקים], \u0003דרבנן סברי\u0004 \u0005[שחכמים סבורים]:\u0006 \u0003מכאן ולהבא הוא נפסל, וכיון דמההיא שעתא קא מיתזמי\u0004 \u0005[שמאותה שעה הם מוזמים],\u0006 שנפסלים משעת הזמה, על ה\u0003טביחה דקא מיתזמי\u0004 \u0005[ש\u0006עליה \u0005הוזמו]\u0006 — \u0003איתזום,\u0004 על ה\u0003גניבה\u0004 ש\u0003לא מיתזמי\u0004 \u0005[הוזמו]\u0006 — \u0003לא איתזום\u0004 \u0005[הוזמו].\u0006","ואילו \u0003ר' יוסי סבר\u0004 \u0005[סבור]:\u0006 עד זומם \u0003למפרע הוא נפסל, וכיון\u0004 ש\u0003מייד כי אסהידו הוא דמיפסלי\u0004 \u0005[כאשר העידו הם נפסלים],\u0006 \u0003אי איתזמו להו\u0004 \u0005[אם\u0006 כאשר הוזמו] \u0003טביחה איתזמו להו נמי אגניבה\u0004 \u0005[הוזמו כם כן אגניבה\u0006 \u0005[הוזמו גם כן על הגניבה],\u0006 כלומר נפסלה העדות על הגניבה, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003תוך כדי דיבור כדיבור דמי\u0004 \u0005[נחשב],\u0006 ואם כן נחשבות שתי העדויות כאילו העידו בבת אחת?","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003אי\u0004 \u0005[אם]\u0006 אכן מניחים ש\u0003תוך כדי דיבור כדיבור דמי\u0004 \u0005[נחשב],\u0006 הרי \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003למפרע הוא נפסל,\u0004 וכדעת אביי, ומשום כך אם הוזמו אף במחצית העדות השניה — העדות כולה נפסלת. \u0003אלא הכא\u0004 \u0005[כאן]\u0006 \u0003ב\u0004שאלה האם \u0003תוך כדי דיבור כדיבור דמי\u0004 \u0005[נחשב]\u0006 \u0003קא מיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 \u0003רבנן סברי\u0004 \u0005[חכמים סבורים]:\u0006 \u0003תוך כדי דיבור\u0004"],["\u0003לאו\u0004 \u0005[לא]\u0006 \u0003כ\u0004אותו \u0003דיבור\u0004 עצמו הוא \u0003דמי\u0004 \u0005[נחשב]\u0006 אלא כדיבור נפרד, \u0003ור' יוסי סבר\u0004 \u0005[סבור]:\u0006 \u0003תוך כדי דיבור כדיבור דמי\u0004 \u0005[נחשב].\u0006","ושואלים: \u0003וסבר\u0004 \u0005[ו\u0006האם \u0005סבור]\u0006 \u0003ר' יוסי\u0004 כי \u0003תוך כדי דיבור כדיבור דמי\u0004 \u0005[נחשב]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו]\u0006 במשנה אחרת: האומר על בהמה \u0003\"הרי זו תמורת\u0004 קרבן \u0003עולה תמורת שלמים\"\u0004 — \u0003הרי זו\u0004 הבהמה נעשית \u0003תמורת עולה,\u0004 אלו \u0003דברי ר' מאיר.\u0004","\u0003ר' יוסי אומר: אם לכך נתכוון מתחילה,\u0004 שרצה שהבהמה תהיה גם תמורת עולה וגם תמורת שלמים, \u0003הואיל ואי אפשר לקרות\u0004 (לקרוא) \u0003שני שמות כאחד\u0004 שהרי אין אדם יכול לומר עולה ושלמים באותו דיבור עצמו — \u0003דבריו קיימין,\u0004 וחל על בהמה זו גם דין תמורת עולה וגם דין תמורת שלמים, אבל \u0003אם אמר \"תמורת עולה\" ונמלך\u0004 (התחרט) \u0003ואמר \"תמורת שלמים\"\u0004 — \u0003הרי זו תמורת עולה;\u0004","\u0003והוינן\u0004 \u0005[והיינו\u0006 דנים] \u0003בה,\u0004 במשנה זו: אם \u0003נמלך\u0004 — \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכך הדבר שהיא תמורת עולה, שהרי כבר חלה עליה קדושת עולה משעה שאמר דיבור ראשון ואין אדם יכול לחזור בו!","\u0003ואמר\u0004 על כך \u0003רב פפא: נמלך בתוך כדי דיבור קאמרינן\u0004 \u0005[אומרים אנו],\u0006 כלומר, אף שהיה זה בתוך כדי דיבור לדיבור הקודם, בכל זאת ר' יוסי סבור שאינו יכול עוד לחזור בו מדיבורו הקודם. ואם כן אינו סבור שתוך כדי דיבור הריהו כאותו דיבור, וכפי שרצינו להעמיד כן את דעתו!","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003תרי\u0004 \u0005[שני]\u0006 סוגים של \u0003תוך כדי דיבור הוי\u0004 \u0005[הם],\u0006 \u0003חד\u0004 \u0005[אחד]\u0006 מהם הוא סמוך \u0003כדי שאילת\u0004 שלום של \u0003תלמיד לרב\u0004 שהיא ארוכה יותר, \u0003וחד\u0004 \u0005[ואחד]\u0006 הוא \u0003כדי שאילת\u0004 שלום של \u0003הרב לתלמיד\u0004 שהיא קצרה יותר, ויש לחלק ביניהם כך: \u0003כי לית ליה\u0004 \u0005[כאשר אין לו]\u0006 \u0003לר' יוסי\u0004 סברה זו שתוך כדי דיבור הוא כדיבור הרי זה בהפסק גדול קצת יותר שהוא \u0003כדי שאילת תלמיד לרב\u0004 שאומר לו \u0003\"שלום עליך רבי ומורי\", דנפיש\u0004 \u0005[שמרובה],\u0006 אולם בהפסק של \u0003כדי שאילת הרב לתלמיד\u0004 שאומר לו רק \u0003\"שלום עליך\"\u0004 — \u0003אית ליה\u0004 \u0005[יש לו],\u0006 שהוא נחשב כדיבור אחד.","\u0003אמר רבא: עדים\u0004 שהעידו על אדם שהוא חייב מיתה \u0003ש\u0004תחילה \u0003הוכחשו\u0004 בעדותם, שעדים אחרים העידו שאינו חייב מיתה, \u0003ולבסוף\u0004 לאחר שהוכחשו \u0003הוזמו,\u0004 שבאו עדים אחרים והעידו שהיו עדים ראשונים אלה במקום אחר בזמן שעליו הם מעידים — הרי הם \u0003נהרגין\u0004 כדין עדים זוממים, שכן אנו אומרים כי \u0003הכחשה\u0004 שהוכחשו מתחילה \u0003תחילת הזמה היא, אלא שלא נגמרה\u0004 כולה בשעתה, ועל כן כאשר באו גם עדי הזמה הרי הם גומרים את הזמת העדים.","\u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מניין אומר אני אותה\u0006 את ההלכה הזו\u0005]?\u0006 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 באה כת עדים והעידה: \u0003\"מעידני באיש פלוני שסימא את עין עבדו\u0004 (ובכך יוצא העבד לחירות) \u0003ו\u0004לאחר מכן \u0003הפיל את שינו\"\u0004 (וחייב האדון בתשלומים על כך) \u0003שהרי הרב אומר כן,\u0004 שגם האדון מודה שכך היה הדבר, \u0003ונמצאו\u0004 העדים האומרים כן \u0003זוממין\u0004 — הריהם \u0003משלמין דמי עין לעבד,\u0004 שהרי אם היה נעשה כעדותם והיה העבד משתחרר על ידי כך, לא היה מקבל פיצויים עבור עינו.","ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אילימא כדקתני\u0004 \u0005[אם תאמר כפי ששנינו],\u0006 \u0003דליכא כת אחרינא\u0004 \u0005[שאין כת\u0006 עדים \u0005אחרת]\u0006 שמעידה בזה, מדוע \u0003משלמין דמי עין לעבד?\u0004 \u0003בתר דמפקי ליה\u0004 [\u0005אחרי ש\u0006בעדותם \u0005זממו להוציא אותו]\u0006 \u0003לחירות\u0004 על הכאת עינו ושלא יקבל עליה תשלום, אם כן משהוזמו את \u0003דמי עינו קבעי שלומי\u0004 \u0005[צריכים\u0006 הם לשלם]?","\u0003ועוד,\u0004 אם נמצא שעדותם היתה עדות שקר — \u0003דמי כוליה\u0004 \u0005[כל]\u0006 ה\u0003עבד לרב בעי לשלומי\u0004 \u0005[צריכים\u0006 הם לשלם] שהרי רצו להפסיד מן האדון את העבד כולו. \u0003ועוד,\u0004 מה שנאמר שם \u0003\"שהרי הרב אומר כן\"\u0004 — \u0003הרב מי ניחא ליה\u0004 \u0005[האם נוח לו]\u0006 בזה שמשחררים את עבדו?","\u0003אלא, לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003כגון דאתו בי תרי ואמרי\u0004 \u0005[שבאו שנים\u0006 קודם לכן \u0005ואמרו]:\u0006 האדון \u0003הפיל את שינו\u0004 של העבד ואחר כך \u0003סימא את עינו, דבעי מיתיב ליה\u0004 \u0005[ש\u0006לפי עדותם \u0005צריך להשיב,\u0006 לתת \u0005לו]\u0006 \u0003הרב\u0004 לעבד \u0003דמי עינו,\u0004 שהרי עם הפלת השן נשתחרר העבד, ואם אחר כך סימא את עינו עשה נזק בבן חורין וחייב לשלם לו את דמי העין. \u0003ואתו בי תרי מציעאי\u0004 \u0005[ובאו שנים אמצעיים],\u0006 אלו המוזכרים בברייתא, \u0003ואמרי\u0004 \u0005[ואמרו]\u0006 שלא כך היה, אלא תחילה סימא את \u0003עינו והדר\u0004 \u0005[ואחר כך]\u0006 הפיל את \u0003שינו,\u0004 שנשתחרר העבד על ידי הוצאת העין, ולפי עדות זו \u0003לא בעי למיתב ליה\u0004 \u0005[צריך להשיב לו\u0006 לעבד] \u0003אלא דמי שינו\u0004 בלבד שהם פחותים הרבה, \u0003דקא מכחשי ליה קמאי למציעאי\u0004 \u0005[שמכחישים\u0006 העדים \u0005הראשונים את\u0006 העדים \u0005האמצעיים],\u0006","\u0003והיינו\u0004 \u0005[וזהו]\u0006 הסבר האמור שם \u0003\"שהרי הרב אומר כן\",\u0004 שגם האדון מסכים לעדות שניה זו, משום \u0003דניחא ליה במאי דקאמרי\u0004 \u0005[שנוח לו במה שהם אומרים].\u0006","שאף שגם לפי עדותם של אלה צריך הוא לשחרר את העבד, מכל מקום יש הבדל בין מה שישלם עבור עין או עבור שן, \u0003וקתני\u0004 \u0005[ושנה]:\u0006 \u0003ונמצאו זוממין,\u0004 והכוונה היא לעדים \u0003מציעאי\u0004 \u0005[האמצעיים],\u0006 שבאה כת שלישית של עדים והעידה שלא היו כלל באותו מקום, משום כך נפסק שהם \u0003משלמין דמי עין לעבד,\u0004 שהרי רצו להפסיד לו את דמי עינו.","הרי אף על פי שהיתה הכחשה לעדותם, מכל מקום יכולים הם להיות מוזמים, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003הכחשה\u0004 עצמה \u0003תחילת הזמה היא,\u0004 והרי זו הוכחה לשיטתו של רבא.","\u0003אמר אביי: לא,\u0004 אין מכאן הוכחה לשיטת רבא, משום שאפשר לפרש הדבר אחרת","\u0003דאפכינהו ואזמינהו\u0004 \u0005[שהפכום והזימום]\u0006, כלומר שעדות זו שבברייתא לא הוכחשה תחילה על ידי עדות קודמת לה, אלא אותם עדים שהזימו הפכו את עדותם ואמרו שלא היה המעשה כפי שאמרו הראשונים (שפגע האדון בעין ואחר כך בשן) אלא להיפך (שפגע תחילה בשן ואחר כך בעין). ונוסף לזה אומרים הם לראשונים: אתם עצמכם לא הייתם באותו מקום, ואינכם יכולים להעיד כלל, ויש כאן באמת רק עדות אחת שיש בה גם הכחשה וגם הזמה.","ומסבירים: \u0003ממאי\u0004 \u0005[ממה]\u0006 מהיכן יודע אתה שכך יש לפרש?"]]};
